/**
 * Handle incoming Telegram webhook (POST requests)
 * This is called instantly when user sends a message to the bot
 */
function handleTelegramWebhook(update) {
  try {
    if (!update || !update.message) {
      return { success: false, error: 'Invalid update' };
    }

    const message = update.message;
    const chatId = message.chat.id.toString();
    const text = message.text || '';

    // Security: Only respond to owner
    if (chatId !== TELEGRAM_CONFIG.OWNER_CHAT_ID) {
      sendTelegramMessage(chatId, 'Unauthorized. This bot only responds to the farm owner.');
      return { success: false, error: 'Unauthorized' };
    }

    // Handle commands
    if (text.startsWith('/')) {
      return handleTelegramCommand(chatId, text);
    }

    // Generate response using Chief of Staff AI
    const response = chatWithChiefOfStaff(text, '[]');

    if (response.success && response.message) {
      sendTelegramMessage(chatId, response.message);

      // Log to coordination system
      sendClaudeMessage({
        from: 'OWNER',
        to: 'CLAUDE_CODE',
        subject: 'Telegram Message',
        body: text,
        type: 'direct',
        priority: 'normal'
      });
      sendClaudeMessage({
        from: 'CLAUDE_CODE',
        to: 'OWNER',
        subject: 'Telegram Response',
        body: response.message,
        type: 'response',
        priority: 'normal'
      });

      return { success: true, responded: true };
    } else {
      sendTelegramMessage(chatId, 'Sorry, I could not process that. Please try again.');
      return { success: false, error: 'AI response failed' };
    }
  } catch (error) {
    Logger.log('handleTelegramWebhook error: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Handle Telegram commands
 */
function handleTelegramCommand(chatId, command) {
  const cmd = command.toLowerCase().split(' ')[0];

  switch (cmd) {
    case '/start':
      sendTelegramMessage(chatId, '🌱 Tiny Seed Farm AI Assistant\n\nI can help you with:\n• Farm status and updates\n• Task management\n• Weather and planning\n• Email summaries\n• Anything else!\n\nJust type your question or use /help for commands.');
      break;
    case '/help':
      sendTelegramMessage(chatId, '📋 Commands:\n/status - Farm status\n/tasks - Today\'s tasks\n/weather - Weather forecast\n/brief - Morning brief\n/sales - Sales summary\n\nOr just type any question!');
      break;
    case '/status':
      const status = chatWithChiefOfStaff('Give me a quick farm status update', '[]');
      sendTelegramMessage(chatId, status.message || 'Could not get status');
      break;
    case '/tasks':
      const tasks = chatWithChiefOfStaff('What tasks need my attention today?', '[]');
      sendTelegramMessage(chatId, tasks.message || 'Could not get tasks');
      break;
    case '/weather':
      const weather = chatWithChiefOfStaff('What is the weather forecast?', '[]');
      sendTelegramMessage(chatId, weather.message || 'Could not get weather');
      break;
    case '/brief':
      const brief = chatWithChiefOfStaff('Give me my morning brief', '[]');
      sendTelegramMessage(chatId, brief.message || 'Could not get brief');
      break;
    case '/sales':
      const sales = chatWithChiefOfStaff('Summarize recent sales', '[]');
      sendTelegramMessage(chatId, sales.message || 'Could not get sales');
      break;
    default:
      sendTelegramMessage(chatId, 'Unknown command. Type /help for available commands.');
  }
  return { success: true };
}

/**
 * Send a message to Telegram
 */
function sendTelegramMessage(chatId, text) {
  const url = `https://api.telegram.org/bot${TELEGRAM_CONFIG.BOT_TOKEN}/sendMessage`;

  const payload = {
    chat_id: chatId,
    text: text,
    parse_mode: 'Markdown'
  };

  try {
    UrlFetchApp.fetch(url, {
      method: 'post',
      contentType: 'application/json',
      payload: JSON.stringify(payload),
      muteHttpExceptions: true
    });
    return true;
  } catch (error) {
    // Try without markdown if it fails
    try {
      payload.parse_mode = undefined;
      UrlFetchApp.fetch(url, {
        method: 'post',
        contentType: 'application/json',
        payload: JSON.stringify(payload),
        muteHttpExceptions: true
      });
      return true;
    } catch (e) {
      Logger.log('sendTelegramMessage error: ' + e.toString());
      return false;
    }
  }
}

/**
 * Set up the Telegram webhook - RUN THIS ONCE
 * After running, the bot will respond instantly to messages
 */
function setupTelegramWebhook() {
  const webAppUrl = ScriptApp.getService().getUrl();
  const webhookUrl = `https://api.telegram.org/bot${TELEGRAM_CONFIG.BOT_TOKEN}/setWebhook?url=${encodeURIComponent(webAppUrl)}`;

  const response = UrlFetchApp.fetch(webhookUrl);
  const result = JSON.parse(response.getContentText());

  Logger.log('Webhook setup result: ' + JSON.stringify(result));
  return result;
}

/**
 * Get current webhook info
 */
function getTelegramWebhookInfo() {
  const url = `https://api.telegram.org/bot${TELEGRAM_CONFIG.BOT_TOKEN}/getWebhookInfo`;
  const response = UrlFetchApp.fetch(url);
  return JSON.parse(response.getContentText());
}

/**
 * Send a proactive message to owner (for notifications)
 */
function notifyOwnerViaTelegram(message) {
  return sendTelegramMessage(TELEGRAM_CONFIG.OWNER_CHAT_ID, message);
}

// ═══════════════════════════════════════════════════════════════════════════
// META/INSTAGRAM WEBHOOK HANDLER
// Handles webhooks from Instagram, Facebook, and Threads
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Handle incoming Meta webhooks (Instagram, Facebook Page, Threads)
 * @param {object} data - The webhook payload from Meta
 */
function handleMetaWebhook(data) {
  try {
    Logger.log('Meta webhook received: ' + JSON.stringify(data).substring(0, 500));

    const ss = SpreadsheetApp.openById('128O56X_FN9_U-s0ENHBBRyLpae_yvWHPYbBheVlR3Vc');
    let logSheet = ss.getSheetByName('META_WebhookLog');

    // Create log sheet if it doesn't exist
    if (!logSheet) {
      logSheet = ss.insertSheet('META_WebhookLog');
      logSheet.getRange(1, 1, 1, 6).setValues([['Timestamp', 'Platform', 'Event Type', 'From', 'Content', 'Raw Data']]);
      logSheet.setFrozenRows(1);
    }

    const timestamp = new Date().toISOString();
    const platform = data.object; // 'instagram' or 'page'

    // Process each entry in the webhook
    if (data.entry && Array.isArray(data.entry)) {
      data.entry.forEach(entry => {
        // Handle Instagram events
        if (platform === 'instagram') {
          // Comments
          if (entry.changes) {
            entry.changes.forEach(change => {
              const eventType = change.field;
              const eventData = change.value;

              logSheet.appendRow([
                timestamp,
                'Instagram',
                eventType,
                eventData.from?.username || eventData.from?.id || 'Unknown',
                eventData.text || eventData.message || JSON.stringify(eventData).substring(0, 200),
                JSON.stringify(change).substring(0, 1000)
              ]);

              // Notify owner of important events
              if (eventType === 'comments' || eventType === 'mentions') {
                notifyOwnerViaTelegram(`📸 Instagram ${eventType}: ${eventData.text || 'New activity'}`);
              }
            });
          }

          // Direct Messages
          if (entry.messaging) {
            entry.messaging.forEach(msg => {
              logSheet.appendRow([
                timestamp,
                'Instagram DM',
                'message',
                msg.sender?.id || 'Unknown',
                msg.message?.text || '[Media/Attachment]',
                JSON.stringify(msg).substring(0, 1000)
              ]);

              notifyOwnerViaTelegram(`📩 Instagram DM received: ${msg.message?.text || '[Media]'}`);
            });
          }
        }

        // Handle Facebook Page events
        if (platform === 'page') {
          if (entry.changes) {
            entry.changes.forEach(change => {
              const eventType = change.field;
              const eventData = change.value;

              logSheet.appendRow([
                timestamp,
                'Facebook',
                eventType,
                eventData.from?.name || eventData.sender_id || 'Unknown',
                eventData.message || eventData.item || JSON.stringify(eventData).substring(0, 200),
                JSON.stringify(change).substring(0, 1000)
              ]);

              // Notify owner of messages
              if (eventType === 'messages' || eventType === 'feed') {
                notifyOwnerViaTelegram(`📘 Facebook ${eventType}: ${eventData.message || 'New activity'}`);
              }
            });
          }

          // Messenger messages
          if (entry.messaging) {
            entry.messaging.forEach(msg => {
              logSheet.appendRow([
                timestamp,
                'Messenger',
                'message',
                msg.sender?.id || 'Unknown',
                msg.message?.text || '[Media/Attachment]',
                JSON.stringify(msg).substring(0, 1000)
              ]);

              notifyOwnerViaTelegram(`💬 Messenger: ${msg.message?.text || '[Media]'}`);
            });
          }
        }
      });
    }

    return { success: true, message: 'Webhook processed' };
  } catch (error) {
    Logger.log('handleMetaWebhook error: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Get Meta webhook logs
 */
function getMetaWebhookLogs(limit = 50) {
  const ss = SpreadsheetApp.openById('128O56X_FN9_U-s0ENHBBRyLpae_yvWHPYbBheVlR3Vc');
  const logSheet = ss.getSheetByName('META_WebhookLog');

  if (!logSheet) {
    return { success: true, logs: [], message: 'No webhook logs yet' };
  }

  const data = logSheet.getDataRange().getValues();
  const headers = data[0];
  const logs = [];

  // Get last N rows (most recent)
  const startRow = Math.max(1, data.length - limit);
  for (let i = data.length - 1; i >= startRow; i--) {
    const row = data[i];
    const log = {};
    headers.forEach((header, idx) => {
      log[header.toLowerCase().replace(/\s+/g, '_')] = row[idx];
    });
    logs.push(log);
  }

  return { success: true, logs: logs, total: data.length - 1 };
}

/**
 * Handle Meta Data Deletion Callback
 * Meta requires apps to handle user data deletion requests
 * https://developers.facebook.com/docs/development/create-an-app/app-dashboard/data-deletion-callback
 */
function handleMetaDataDeletion(data) {
  try {
    Logger.log('Meta data deletion request: ' + JSON.stringify(data));

    // Parse the signed_request from Meta
    const signedRequest = data.signed_request;

    if (!signedRequest) {
      // If no signed_request, this might be a direct test
      Logger.log('No signed_request - processing as test/direct deletion');
    }

    // Generate a unique confirmation code
    const confirmationCode = 'TSFDEL_' + Date.now() + '_' + Math.random().toString(36).substring(7);

    // Log the deletion request to spreadsheet
    const ss = SpreadsheetApp.openById('128O56X_FN9_U-s0ENHBBRyLpae_yvWHPYbBheVlR3Vc');
    let logSheet = ss.getSheetByName('META_DataDeletionLog');

    // Create log sheet if it doesn't exist
    if (!logSheet) {
      logSheet = ss.insertSheet('META_DataDeletionLog');
      logSheet.getRange(1, 1, 1, 5).setValues([['Timestamp', 'Confirmation Code', 'User ID', 'Status', 'Raw Data']]);
      logSheet.setFrozenRows(1);
    }

    // Extract user_id if available (from decoded signed_request)
    const userId = data.user_id || 'unknown';

    logSheet.appendRow([
      new Date().toISOString(),
      confirmationCode,
      userId,
      'PENDING',
      JSON.stringify(data).substring(0, 500)
    ]);

    // Notify owner via Telegram
    notifyOwnerViaTelegram('📋 Meta Data Deletion Request\nConfirmation: ' + confirmationCode + '\nUser ID: ' + userId);

    // Meta expects a specific JSON response format
    // url: A URL where users can check deletion status
    // confirmation_code: A unique code for this deletion request
    return {
      success: true,
      url: 'https://app.tinyseedfarm.com/web_app/privacy-policy.html',
      confirmation_code: confirmationCode
    };
  } catch (error) {
    Logger.log('handleMetaDataDeletion error: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

