// CORE EMAIL PROCESSING
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Process a single email thread with full body access
 * @param {string} threadId - Gmail thread ID
 */
function processEmailThread(threadId) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const stateSheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    if (!stateSheet) {
      initializeChiefOfStaffSheets();
    }

    // Get the Gmail thread
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Thread not found' };
    }

    const messages = thread.getMessages();
    const latestMessage = messages[messages.length - 1];

    // Extract full email data
    const emailData = {
      threadId: threadId,
      messageId: latestMessage.getId(),
      subject: thread.getFirstMessageSubject(),
      from: latestMessage.getFrom(),
      fromName: extractName(latestMessage.getFrom()),
      to: latestMessage.getTo(),
      receivedAt: latestMessage.getDate().toISOString(),
      body: latestMessage.getPlainBody(),
      htmlBody: latestMessage.getBody(),
      messageCount: messages.length,
      labels: thread.getLabels().map(l => l.getName()),
      isUnread: thread.isUnread(),
      hasAttachments: latestMessage.getAttachments().length > 0
    };

    // Classify with Claude AI
    const classification = classifyEmailWithAI(emailData);

    // Check if thread already exists
    const existingRow = findThreadRow(stateSheet, threadId);

    const now = new Date().toISOString();
    const rowData = [
      threadId,
      emailData.messageId,
      emailData.subject,
      emailData.from,
      emailData.fromName,
      emailData.to,
      emailData.receivedAt,
      classification.category,
      classification.priority,
      'NEW',
      '', // Assigned_To
      classification.dueDate || '',
      '', // Follow_Up_Date
      classification.customerId || '',
      classification.vendorId || '',
      classification.orderId || '',
      JSON.stringify(classification.tags || []),
      classification.summary,
      classification.suggestedAction,
      classification.confidence,
      JSON.stringify({ status: 'NEW', history: [{ status: 'NEW', at: now }] }),
      now,
      now,
      '',
      ''
    ];

    if (existingRow) {
      // Update existing row
      const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
      sheet.getRange(existingRow, 1, 1, rowData.length).setValues([rowData]);
    } else {
      // Insert new row
      const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
      sheet.appendRow(rowData);
    }

    // Create suggested action if applicable
    if (classification.suggestedAction && classification.confidence >= 0.7) {
      suggestActionForEmail(threadId, classification);
    }

    // Log to audit
    logChiefOfStaffAudit({
      agent: 'A',
      action: 'PROCESS_EMAIL',
      threadId: threadId,
      input: { subject: emailData.subject, from: emailData.from },
      output: classification,
      confidence: classification.confidence
    });

    return {
      success: true,
      data: {
        threadId,
        subject: emailData.subject,
        category: classification.category,
        priority: classification.priority,
        summary: classification.summary,
        suggestedAction: classification.suggestedAction,
        confidence: classification.confidence
      }
    };
  } catch (error) {
    Logger.log('Error processing email thread: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Triage all new/unprocessed emails
 */
function triageInbox() {
  const results = {
    processed: 0,
    skipped: 0,
    errors: 0,
    newMessages: 0,
    details: [],
    warnings: [],
    degraded: false
  };

  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    let stateSheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    if (!stateSheet) {
      initializeChiefOfStaffSheets();
      stateSheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
    }

    // Check if AI classification is available
    const apiKey = CLAUDE_CONFIG.API_KEY;
    if (!apiKey || apiKey === 'YOUR_ANTHROPIC_API_KEY_HERE') {
      results.degraded = true;
      results.warnings.push('AI classification unavailable - using rule-based classification. Set ANTHROPIC_API_KEY for better results.');
      Logger.log('WARNING: triageInbox running in degraded mode - no Anthropic API key');
    }

    // Get processed thread IDs and their message counts
    const processedThreads = new Map(); // threadId -> messageCount
    if (stateSheet.getLastRow() > 1) {
      const headers = stateSheet.getRange(1, 1, 1, stateSheet.getLastColumn()).getValues()[0];
      const threadIdCol = headers.indexOf('Thread_ID');
      const msgCountCol = headers.indexOf('Message_Count');

      if (threadIdCol >= 0) {
        const data = stateSheet.getRange(2, 1, stateSheet.getLastRow() - 1, stateSheet.getLastColumn()).getValues();
        data.forEach(row => {
          const threadId = row[threadIdCol];
          const msgCount = msgCountCol >= 0 ? parseInt(row[msgCountCol]) || 0 : 0;
          processedThreads.set(threadId, msgCount);
        });
      }
    }

    // Get inbox threads - increased from 100 to 500
    const threads = GmailApp.getInboxThreads(0, 500);

    for (const thread of threads) {
      const threadId = thread.getId();
      const currentMsgCount = thread.getMessageCount();

      if (processedThreads.has(threadId)) {
        const storedMsgCount = processedThreads.get(threadId);

        // Check if there are new messages in this thread
        if (currentMsgCount > storedMsgCount) {
          results.newMessages++;
          Logger.log('New messages detected in thread ' + threadId + ': ' + storedMsgCount + ' -> ' + currentMsgCount);

          // Re-process thread with new messages
          try {
            const result = processEmailThread(threadId);
            if (result.success) {
              results.processed++;
              results.details.push({
                threadId,
                subject: result.data.subject,
                category: result.data.category,
                priority: result.data.priority,
                isUpdate: true,
                newMessageCount: currentMsgCount - storedMsgCount
              });
            } else {
              results.errors++;
              results.details.push({ threadId, error: result.error, isUpdate: true });
            }
          } catch (e) {
            results.errors++;
            Logger.log('Error reprocessing thread ' + threadId + ': ' + e.toString());
            results.details.push({ threadId, error: e.toString(), isUpdate: true });
          }
        } else {
          // No new messages, skip
          results.skipped++;
        }
        continue;
      }

      // Process new thread
      try {
        const result = processEmailThread(threadId);
        if (result.success) {
          results.processed++;
          results.details.push({
            threadId,
            subject: result.data.subject,
            category: result.data.category,
            priority: result.data.priority,
            isNew: true
          });
        } else {
          results.errors++;
          results.details.push({ threadId, error: result.error, isNew: true });
        }
      } catch (e) {
        results.errors++;
        Logger.log('Error processing thread ' + threadId + ': ' + e.toString());
        // Continue processing other threads instead of failing completely
        results.details.push({ threadId, error: e.toString(), isNew: true });
      }
    }

    // Log to audit
    logChiefOfStaffAudit({
      agent: 'A',
      action: 'TRIAGE_INBOX',
      input: { threadCount: threads.length, degraded: results.degraded },
      output: results
    });

    return {
      success: true,
      data: results,
      degraded: results.degraded,
      warnings: results.warnings,
      message: `Processed ${results.processed} emails (${results.newMessages} updated), skipped ${results.skipped}, errors: ${results.errors}${results.degraded ? ' [DEGRADED MODE]' : ''}`
    };
  } catch (error) {
    Logger.log('triageInbox fatal error: ' + error.toString());
    // Return partial results instead of failing completely
    return {
      success: false,
      error: error.toString(),
      partialResults: results,
      message: 'Triage failed but partial results available'
    };
  }
}

/**
 * Classify email using Claude AI
 * Returns degraded: true if falling back to rule-based classification
 */
function classifyEmailWithAI(emailData) {
  const apiKey = CLAUDE_CONFIG.API_KEY;

  // Explicit check for empty or placeholder API key
  if (!apiKey || apiKey.trim() === '') {
    Logger.log('WARNING: classifyEmailWithAI - ANTHROPIC_API_KEY is not set. Falling back to rule-based classification.');
    const ruleResult = classifyEmailWithRules(emailData);
    return {
      ...ruleResult,
      degraded: true,
      reason: 'API key not configured',
      classificationMethod: 'rules'
    };
  }

  if (apiKey === 'YOUR_ANTHROPIC_API_KEY_HERE') {
    Logger.log('WARNING: classifyEmailWithAI - ANTHROPIC_API_KEY has placeholder value. Falling back to rule-based classification.');
    const ruleResult = classifyEmailWithRules(emailData);
    return {
      ...ruleResult,
      degraded: true,
      reason: 'API key has placeholder value - please configure a real key',
      classificationMethod: 'rules'
    };
  }

  try {
    const prompt = `Analyze this email and classify it for a small organic farm business.

EMAIL:
From: ${emailData.from}
Subject: ${emailData.subject}
Body: ${emailData.body ? emailData.body.substring(0, 2000) : '(No body)'}

Respond with ONLY valid JSON (no markdown):
{
  "category": "CUSTOMER" | "VENDOR" | "INTERNAL" | "MARKETING" | "PERSONAL",
  "priority": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
  "summary": "2-3 sentence summary",
  "suggestedAction": "What should be done next",
  "actionType": "REPLY" | "CREATE_TASK" | "CREATE_EVENT" | "UPDATE_CRM" | "NONE",
  "confidence": 0.0-1.0,
  "tags": ["tag1", "tag2"],
  "extractedData": {
    "customerName": "if detected",
    "orderNumber": "if mentioned",
    "deadline": "if mentioned"
  }
}

Priority Rules:
- CRITICAL: Payment issues, urgent deadlines <24h, legal matters
- HIGH: Customer complaints, vendor confirmations, time-sensitive <48h
- MEDIUM: General inquiries, routine orders
- LOW: Marketing, newsletters, FYI only`;

    const response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      },
      payload: JSON.stringify({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 1000,
        messages: [{ role: 'user', content: prompt }]
      }),
      muteHttpExceptions: true
    });

    const responseCode = response.getResponseCode();
    const responseText = response.getContentText();

    // Check for API errors
    if (responseCode !== 200) {
      Logger.log('AI classification API error: HTTP ' + responseCode + ' - ' + responseText);
      const ruleResult = classifyEmailWithRules(emailData);
      return {
        ...ruleResult,
        degraded: true,
        reason: 'API returned error: HTTP ' + responseCode,
        classificationMethod: 'rules'
      };
    }

    const result = JSON.parse(responseText);

    if (result.content && result.content[0] && result.content[0].text) {
      const parsed = JSON.parse(result.content[0].text);
      return {
        category: parsed.category || 'PERSONAL',
        priority: parsed.priority || 'MEDIUM',
        summary: parsed.summary || emailData.subject,
        suggestedAction: parsed.suggestedAction || '',
        actionType: parsed.actionType || 'NONE',
        confidence: parsed.confidence || 0.5,
        tags: parsed.tags || [],
        customerId: null,
        vendorId: null,
        orderId: parsed.extractedData?.orderNumber || null,
        dueDate: parsed.extractedData?.deadline || null,
        degraded: false,
        classificationMethod: 'ai'
      };
    }

    // AI response was empty or malformed
    Logger.log('AI classification returned empty/malformed response. Falling back to rules.');
    const ruleResult = classifyEmailWithRules(emailData);
    return {
      ...ruleResult,
      degraded: true,
      reason: 'AI response was empty or malformed',
      classificationMethod: 'rules'
    };

  } catch (error) {
    Logger.log('AI classification error: ' + error.toString() + '. Falling back to rule-based classification.');
    const ruleResult = classifyEmailWithRules(emailData);
    return {
      ...ruleResult,
      degraded: true,
      reason: 'AI classification failed: ' + error.toString(),
      classificationMethod: 'rules'
    };
  }
}

/**
 * Rule-based classification fallback
 */
function classifyEmailWithRules(emailData) {
  const from = emailData.from.toLowerCase();
  const subject = emailData.subject.toLowerCase();
  const body = (emailData.body || '').toLowerCase();
  const combined = from + ' ' + subject + ' ' + body;

  let category = 'PERSONAL';
  let priority = 'MEDIUM';
  const tags = [];

  // Category detection
  if (combined.includes('order') || combined.includes('csa') || combined.includes('delivery') ||
      combined.includes('pickup') || combined.includes('member')) {
    category = 'CUSTOMER';
    tags.push('customer');
  } else if (combined.includes('invoice') || combined.includes('seed') || combined.includes('supply') ||
             combined.includes('johnny') || combined.includes('fedex') || combined.includes('usps')) {
    category = 'VENDOR';
    tags.push('vendor');
  } else if (from.includes('tinyseed') || from.includes('tiny seed')) {
    category = 'INTERNAL';
  } else if (combined.includes('unsubscribe') || combined.includes('newsletter') ||
             combined.includes('promotion')) {
    category = 'MARKETING';
  }

  // Priority detection
  if (combined.includes('urgent') || combined.includes('asap') || combined.includes('immediately') ||
      combined.includes('critical')) {
    priority = 'CRITICAL';
    tags.push('urgent');
  } else if (combined.includes('important') || combined.includes('deadline') ||
             combined.includes('payment') || combined.includes('overdue')) {
    priority = 'HIGH';
  } else if (category === 'MARKETING') {
    priority = 'LOW';
  }

  // Extract order number
  const orderMatch = combined.match(/order\s*#?\s*(\d+)/i);
  const orderId = orderMatch ? orderMatch[1] : null;

  return {
    category,
    priority,
    summary: `${category} email from ${emailData.fromName || emailData.from}`,
    suggestedAction: category === 'CUSTOMER' ? 'Review and respond to customer' :
                     category === 'VENDOR' ? 'Review vendor communication' : '',
    actionType: (category === 'CUSTOMER' || category === 'VENDOR') ? 'REPLY' : 'NONE',
    confidence: 0.6,
    tags,
    customerId: null,
    vendorId: null,
    orderId,
    dueDate: null
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// WORKFLOW STATE MACHINE
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Transition email to new state
 */
function transitionEmailState(threadId, newStatus, metadata = {}) {
  if (!threadId || !newStatus) {
    return { success: false, error: 'threadId and newStatus required' };
  }

  if (!EMAIL_STATUSES.includes(newStatus)) {
    return { success: false, error: 'Invalid status: ' + newStatus };
  }

  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    const row = findThreadRow(sheet, threadId);
    if (!row) {
      return { success: false, error: 'Thread not found' };
    }

    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    const statusCol = headers.indexOf('Status') + 1;
    const workflowCol = headers.indexOf('Workflow_State') + 1;
    const updatedCol = headers.indexOf('Updated_At') + 1;
    const resolvedCol = headers.indexOf('Resolved_At') + 1;
    const resolutionCol = headers.indexOf('Resolution_Notes') + 1;

    const currentStatus = sheet.getRange(row, statusCol).getValue();

    // Validate transition
    const validTransitions = {
      'NEW': ['TRIAGED', 'ARCHIVED'],
      'TRIAGED': ['AWAITING_RESPONSE', 'AWAITING_REVIEW', 'RESOLVED', 'ARCHIVED'],
      'AWAITING_REVIEW': ['TRIAGED', 'AWAITING_RESPONSE', 'RESOLVED', 'ARCHIVED'],
      'AWAITING_RESPONSE': ['AWAITING_THEM', 'RESOLVED', 'ARCHIVED'],
      'AWAITING_THEM': ['AWAITING_RESPONSE', 'RESOLVED', 'ARCHIVED'],
      'RESOLVED': ['ARCHIVED'],
      'ARCHIVED': []
    };

    if (validTransitions[currentStatus] && !validTransitions[currentStatus].includes(newStatus)) {
      return {
        success: false,
        error: `Invalid transition from ${currentStatus} to ${newStatus}`
      };
    }

    // Update workflow state
    let workflowState = {};
    try {
      workflowState = JSON.parse(sheet.getRange(row, workflowCol).getValue() || '{}');
    } catch (e) {
      workflowState = {};
    }

    workflowState.status = newStatus;
    workflowState.history = workflowState.history || [];
    workflowState.history.push({
      from: currentStatus,
      to: newStatus,
      at: new Date().toISOString(),
      metadata
    });

    const now = new Date().toISOString();

    // Update cells
    sheet.getRange(row, statusCol).setValue(newStatus);
    sheet.getRange(row, workflowCol).setValue(JSON.stringify(workflowState));
    sheet.getRange(row, updatedCol).setValue(now);

    if (newStatus === 'RESOLVED') {
      sheet.getRange(row, resolvedCol).setValue(now);
      if (metadata.notes) {
        sheet.getRange(row, resolutionCol).setValue(metadata.notes);
      }
    }

    // Log to audit
    logChiefOfStaffAudit({
      agent: 'A',
      action: 'TRANSITION_STATE',
      threadId,
      input: { from: currentStatus, to: newStatus, metadata },
      output: { success: true }
    });

    return {
      success: true,
      data: {
        threadId,
        previousStatus: currentStatus,
        newStatus,
        updatedAt: now
      }
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Get emails by status
 */
function getEmailsByStatus(params = {}) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    if (!sheet || sheet.getLastRow() <= 1) {
      return { success: true, data: [], count: 0 };
    }

    const data = sheet.getDataRange().getValues();
    const headers = data[0];

    const statusFilter = params.status ? params.status.split(',') : null;
    const categoryFilter = params.category ? params.category.split(',') : null;
    const priorityFilter = params.priority ? params.priority.split(',') : null;
    const limit = parseInt(params.limit) || 50;
    const offset = parseInt(params.offset) || 0;

    const statusCol = headers.indexOf('Status');
    const categoryCol = headers.indexOf('Category');
    const priorityCol = headers.indexOf('Priority');

    const results = [];
    for (let i = 1; i < data.length; i++) {
      const row = data[i];

      if (statusFilter && !statusFilter.includes(row[statusCol])) continue;
      if (categoryFilter && !categoryFilter.includes(row[categoryCol])) continue;
      if (priorityFilter && !priorityFilter.includes(row[priorityCol])) continue;

      const email = {};
      headers.forEach((h, idx) => {
        email[h.toLowerCase().replace(/_/g, '')] = row[idx];
      });

      results.push(email);
    }

    // Sort by priority then date
    const priorityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
    results.sort((a, b) => {
      const pDiff = (priorityOrder[a.priority] || 4) - (priorityOrder[b.priority] || 4);
      if (pDiff !== 0) return pDiff;
      return new Date(b.receivedat) - new Date(a.receivedat);
    });

    const paginated = results.slice(offset, offset + limit);

    return {
      success: true,
      data: paginated,
      count: results.length,
      limit,
      offset
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Get combined communications (emails + SMS) for Chief of Staff dashboard
 */
function getCombinedCommunications(params = {}) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
    const limit = parseInt(params.limit) || 100;

    const results = [];
    const counts = { critical: 0, high: 0, medium: 0, low: 0 };

    // Get emails from EMAIL_INBOX_STATE
    if (sheet && sheet.getLastRow() > 1) {
      const data = sheet.getDataRange().getValues();
      const headers = data[0];

      const threadIdCol = headers.indexOf('Thread_ID');
      const subjectCol = headers.indexOf('Subject');
      const fromCol = headers.indexOf('From');
      const fromNameCol = headers.indexOf('From_Name');
      const receivedCol = headers.indexOf('Received_At');
      const categoryCol = headers.indexOf('Category');
      const priorityCol = headers.indexOf('Priority');
      const statusCol = headers.indexOf('Status');
      const summaryCol = headers.indexOf('AI_Summary');
      const actionCol = headers.indexOf('AI_Suggested_Action');

      for (let i = 1; i < data.length && results.length < limit; i++) {
        const row = data[i];
        const status = row[statusCol];

        // Skip resolved/archived emails
        if (status === 'RESOLVED' || status === 'ARCHIVED') continue;

        const priority = row[priorityCol] || 'MEDIUM';

        // Count by priority
        const pLower = priority.toLowerCase();
        if (counts[pLower] !== undefined) counts[pLower]++;

        results.push({
          id: row[threadIdCol],
          type: 'email',
          from: row[fromNameCol] || row[fromCol],
          subject: row[subjectCol],
          preview: (row[summaryCol] || '').substring(0, 150),
          timestamp: row[receivedCol],
          category: row[categoryCol],
          priority: priority,
          status: status,
          suggestedAction: row[actionCol]
        });
      }
    }

    // Sort by priority then date
    const priorityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
    results.sort((a, b) => {
      const pDiff = (priorityOrder[a.priority] || 4) - (priorityOrder[b.priority] || 4);
      if (pDiff !== 0) return pDiff;
      return new Date(b.timestamp) - new Date(a.timestamp);
    });

    return {
      success: true,
      data: results,
      counts: counts,
      total: results.length
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Reclassify an email's priority and/or category
 */
function reclassifyEmail(threadId, newPriority, newCategory) {
  try {
    if (!threadId) {
      return { success: false, error: 'Thread ID required' };
    }

    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    if (!sheet) {
      return { success: false, error: 'EMAIL_INBOX_STATE sheet not found' };
    }

    const row = findThreadRow(sheet, threadId);
    if (!row) {
      return { success: false, error: 'Thread not found' };
    }

    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    const priorityCol = headers.indexOf('Priority') + 1;
    const categoryCol = headers.indexOf('Category') + 1;
    const updatedCol = headers.indexOf('Updated_At') + 1;

    const updates = [];

    if (newPriority && EMAIL_PRIORITIES.includes(newPriority)) {
      sheet.getRange(row, priorityCol).setValue(newPriority);
      updates.push({ field: 'priority', value: newPriority });
    }

    // Allow ANY category - including custom ones created by the user
    // Previously this was restricted to EMAIL_CATEGORIES which broke custom categories
    if (newCategory && newCategory.trim()) {
      const cleanCategory = newCategory.trim().toUpperCase();
      sheet.getRange(row, categoryCol).setValue(cleanCategory);
      updates.push({ field: 'category', value: cleanCategory });

      // If this is a custom category, make sure it's in the custom categories sheet
      if (!EMAIL_CATEGORIES.includes(cleanCategory)) {
        try {
          addCustomCategory({ name: cleanCategory });
        } catch (e) {
          // Already exists or couldn't add - that's fine
        }
      }
    }

    if (updates.length > 0) {
      sheet.getRange(row, updatedCol).setValue(new Date().toISOString());

      // Log the reclassification for AI learning
      logChiefOfStaffAudit({
        agent: 'USER',
        action: 'RECLASSIFY_EMAIL',
        threadId: threadId,
        input: { newPriority, newCategory },
        output: { success: true, updates },
        humanOverride: true,
        overrideReason: 'User reclassification'
      });
    }

    return {
      success: true,
      data: {
        threadId,
        updates,
        message: updates.length > 0 ? 'Classification updated' : 'No changes made'
      }
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Reclassify an SMS message priority
 */
function reclassifySMS(messageId, newPriority) {
  try {
    if (!messageId) {
      return { success: false, error: 'Message ID required' };
    }

    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(SMS_LOG_SHEET);

    if (!sheet) {
      return { success: false, error: 'SMS log sheet not found' };
    }

    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const idCol = headers.indexOf('Message_ID');
    const priorityCol = headers.indexOf('Priority');

    if (idCol === -1 || priorityCol === -1) {
      return { success: false, error: 'Required columns not found' };
    }

    // Find the row
    let rowIndex = -1;
    for (let i = 1; i < data.length; i++) {
      if (data[i][idCol] === messageId) {
        rowIndex = i + 1; // +1 for sheet row (1-indexed)
        break;
      }
    }

    if (rowIndex === -1) {
      return { success: false, error: 'SMS message not found' };
    }

    if (newPriority && ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'].includes(newPriority)) {
      sheet.getRange(rowIndex, priorityCol + 1).setValue(newPriority);

      // Log for AI learning
      logChiefOfStaffAudit({
        agent: 'USER',
        action: 'RECLASSIFY_SMS',
        messageId: messageId,
        input: { newPriority },
        output: { success: true },
        humanOverride: true,
        overrideReason: 'User reclassification'
      });

      return { success: true, data: { messageId, newPriority } };
    }

    return { success: false, error: 'Invalid priority' };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Resolve an email thread
 */
function resolveEmail(threadId, notes = '') {
  return transitionEmailState(threadId, 'RESOLVED', { notes });
}

/**
 * Get full email details including body
 */
function getEmailDetail(threadId) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Email thread not found' };
    }

    const messages = thread.getMessages();
    const latestMessage = messages[messages.length - 1];

    // Get classification from sheet if available
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
    let classification = {};

    if (sheet) {
      const row = findThreadRow(sheet, threadId);
      if (row) {
        const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
        const rowData = sheet.getRange(row, 1, 1, sheet.getLastColumn()).getValues()[0];
        headers.forEach((h, idx) => {
          classification[h.toLowerCase().replace(/_/g, '')] = rowData[idx];
        });
      }
    }

    return {
      success: true,
      data: {
        threadId: threadId,
        subject: thread.getFirstMessageSubject(),
        from: latestMessage.getFrom(),
        to: latestMessage.getTo(),
        cc: latestMessage.getCc(),
        date: latestMessage.getDate().toISOString(),
        body: latestMessage.getPlainBody(),
        htmlBody: latestMessage.getBody(),
        messageCount: messages.length,
        isUnread: thread.isUnread(),
        labels: thread.getLabels().map(l => l.getName()),
        hasAttachments: latestMessage.getAttachments().length > 0,
        attachments: latestMessage.getAttachments().map(a => ({
          name: a.getName(),
          size: a.getSize(),
          type: a.getContentType()
        })),
        classification: classification
      }
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * FAST email body retrieval - OPTIMIZED FOR SPEED
 * Skips: spreadsheet lookup, attachments, labels, HTML body
 * Only returns plain text body - 10x faster than getEmailDetail
 */
function getEmailBodyFast(threadId) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Email thread not found' };
    }

    const messages = thread.getMessages();
    const latestMessage = messages[messages.length - 1];

    // ONLY get the essential data - no spreadsheet, no attachments, no labels
    return {
      success: true,
      body: latestMessage.getPlainBody(),
      subject: thread.getFirstMessageSubject(),
      from: latestMessage.getFrom(),
      date: latestMessage.getDate().toISOString(),
      messageCount: messages.length
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Archive an email thread
 */
function archiveEmail(threadId) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Email thread not found' };
    }

    // Move to archive in Gmail with proper error handling
    try {
      thread.moveToArchive();
    } catch (gmailError) {
      Logger.log('Gmail archive operation failed: ' + gmailError.toString());
      return {
        success: false,
        error: 'Gmail archive operation failed: ' + gmailError.toString(),
        errorType: 'GMAIL_OPERATION_FAILED'
      };
    }

    // Verify the archive actually happened by checking if thread is still in inbox
    try {
      // Refresh thread state
      const refreshedThread = GmailApp.getThreadById(threadId);
      if (refreshedThread && refreshedThread.isInInbox()) {
        Logger.log('Archive verification failed - thread still in inbox: ' + threadId);
        return {
          success: false,
          error: 'Archive verification failed - email may not have been archived',
          errorType: 'ARCHIVE_VERIFICATION_FAILED'
        };
      }
    } catch (verifyError) {
      // Log but don't fail - the archive may have worked
      Logger.log('Archive verification check failed: ' + verifyError.toString());
    }

    // Initialize sheets if needed before calling transitionEmailState
    try {
      const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
      let stateSheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
      if (!stateSheet) {
        initializeChiefOfStaffSheets();
      }
    } catch (sheetError) {
      Logger.log('Sheet initialization check failed: ' + sheetError.toString());
      // Continue anyway - archive in Gmail succeeded
    }

    // Update status in sheet
    const transitionResult = transitionEmailState(threadId, 'ARCHIVED', { archivedAt: new Date().toISOString() });

    // Log even if transition fails (Gmail archive succeeded)
    if (!transitionResult.success) {
      Logger.log('State transition failed but Gmail archive succeeded: ' + JSON.stringify(transitionResult));
    }

    logChiefOfStaffAudit({
      agent: 'USER',
      action: 'ARCHIVE_EMAIL',
      threadId: threadId,
      output: { success: true, transitionResult: transitionResult.success }
    });

    return {
      success: true,
      message: 'Email archived',
      gmailArchived: true,
      stateUpdated: transitionResult.success
    };
  } catch (error) {
    Logger.log('archiveEmail error: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Delete an email thread (move to trash)
 */
function deleteEmail(threadId) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Email thread not found' };
    }

    // Move to trash in Gmail
    thread.moveToTrash();

    // Update status in sheet
    transitionEmailState(threadId, 'DELETED', { deletedAt: new Date().toISOString() });

    logChiefOfStaffAudit({
      agent: 'USER',
      action: 'DELETE_EMAIL',
      threadId: threadId,
      output: { success: true }
    });

    return { success: true, message: 'Email deleted' };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Create a draft reply to an email
 */
function draftEmailReply(threadId, replyBody, sendImmediately = false) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }
  if (!replyBody) {
    return { success: false, error: 'Reply body required' };
  }

  try {
    const thread = GmailApp.getThreadById(threadId);
    if (!thread) {
      return { success: false, error: 'Email thread not found' };
    }

    const messages = thread.getMessages();
    const lastMessage = messages[messages.length - 1];

    // Add signature
    const signature = `\n\n--\nTiny Seed Farm\nFresh, Local, Organic`;
    const fullBody = replyBody + signature;

    if (sendImmediately) {
      // Send immediately
      lastMessage.reply(fullBody);

      // Update status
      transitionEmailState(threadId, 'AWAITING_THEM', { repliedAt: new Date().toISOString() });

      logChiefOfStaffAudit({
        agent: 'USER',
        action: 'SEND_REPLY',
        threadId: threadId,
        input: { bodyPreview: replyBody.substring(0, 100) },
        output: { success: true }
      });

      return { success: true, message: 'Reply sent', sent: true };
    } else {
      // Create draft
      const draft = lastMessage.createDraftReply(fullBody);

      logChiefOfStaffAudit({
        agent: 'USER',
        action: 'CREATE_DRAFT',
        threadId: threadId,
        input: { bodyPreview: replyBody.substring(0, 100) },
        output: { success: true, draftId: draft.getId() }
      });

      return {
        success: true,
        message: 'Draft created',
        draftId: draft.getId(),
        sent: false
      };
    }
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Generate AI draft reply for an email
 */
function generateAIDraftReply(threadId, userInstructions) {
  if (!threadId) {
    return { success: false, error: 'Thread ID required' };
  }

  try {
    // Get email details
    const emailResult = getEmailDetail(threadId);
    if (!emailResult.success) {
      return emailResult;
    }

    const email = emailResult.data;
    const apiKey = PropertiesService.getScriptProperties().getProperty('ANTHROPIC_API_KEY');

    if (!apiKey) {
      return { success: false, error: 'AI not configured' };
    }

    // Build prompt with user instructions if provided
    let prompt = `You are responding on behalf of Tiny Seed Farm, a small organic vegetable farm.
Write a professional, friendly reply to this email.

From: ${email.from}
Subject: ${email.subject}
Body:
${email.body}`;

    if (userInstructions && userInstructions.trim()) {
      prompt += `\n\nIMPORTANT - Include these key points in your reply:\n${userInstructions}`;
    }

    prompt += `\n\nWrite ONLY the reply body, no subject line or signature. Be concise and helpful.`;

    const response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      payload: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        max_tokens: 1024,
        messages: [{ role: 'user', content: prompt }]
      }),
      muteHttpExceptions: true
    });

    const result = JSON.parse(response.getContentText());

    if (result.error) {
      return { success: false, error: result.error.message };
    }

    const draftBody = result.content[0].text;

    return {
      success: true,
      threadId: threadId,
      subject: email.subject,
      originalFrom: email.from,
      suggestedReply: draftBody
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Assign email to user
 */
function assignEmail(threadId, assignTo) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);

    const row = findThreadRow(sheet, threadId);
    if (!row) {
      return { success: false, error: 'Thread not found' };
    }

    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
    const assignCol = headers.indexOf('Assigned_To') + 1;
    const updatedCol = headers.indexOf('Updated_At') + 1;

    sheet.getRange(row, assignCol).setValue(assignTo);
    sheet.getRange(row, updatedCol).setValue(new Date().toISOString());

    logChiefOfStaffAudit({
      agent: 'A',
      action: 'ASSIGN_EMAIL',
      threadId,
      input: { assignTo },
      output: { success: true }
    });

    return { success: true, data: { threadId, assignedTo: assignTo } };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

