// ============================================
// POPULATE TRAY SIZES FROM CROP PROFILES
// ============================================

/**
 * One-time function to populate Tray_Cell_Count (column AC) in PLANNING_2026
 * Uses crop profiles to look up default tray sizes for each planting
 */
function populateTraySizesFromProfiles() {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const planSheet = ss.getSheetByName('PLANNING_2026');
    const profileSheet = ss.getSheetByName('REF_CropProfiles');

    if (!planSheet) {
      return { success: false, error: 'PLANNING_2026 sheet not found' };
    }
    if (!profileSheet) {
      return { success: false, error: 'REF_CropProfiles sheet not found' };
    }

    // Get planning data
    const planData = planSheet.getDataRange().getValues();
    const planHeaders = planData[0];

    // Find column indices
    const cropCol = planHeaders.indexOf('Crop');
    const varietyCol = planHeaders.indexOf('Variety');
    const methodCol = planHeaders.indexOf('Planting_Method');
    const traySizeCol = planHeaders.indexOf('Tray_Cell_Count');

    if (traySizeCol === -1) {
      return { success: false, error: 'Tray_Cell_Count column not found in PLANNING_2026. Please add it as column AC.' };
    }

    // Build crop profile lookup map
    const profileData = profileSheet.getDataRange().getValues();
    const profileHeaders = profileData[0];
    const profCropCol = profileHeaders.indexOf('Crop') !== -1 ? profileHeaders.indexOf('Crop') : 0;
    const profVarietyCol = profileHeaders.indexOf('Variety') !== -1 ? profileHeaders.indexOf('Variety') : 5;
    const profTraySizeCol = profileHeaders.indexOf('Tray_Size') !== -1 ? profileHeaders.indexOf('Tray_Size') :
                           profileHeaders.indexOf('TraySize') !== -1 ? profileHeaders.indexOf('TraySize') : 15; // Column P = index 15

    const profileMap = {};
    for (let i = 1; i < profileData.length; i++) {
      const crop = (profileData[i][profCropCol] || '').toString().trim().toLowerCase();
      const variety = (profileData[i][profVarietyCol] || '').toString().trim().toLowerCase();
      const traySize = profileData[i][profTraySizeCol];
      if (crop) {
        // Store with variety
        profileMap[crop + '|' + variety] = traySize || 72;
        // Also store crop-only as fallback
        if (!profileMap[crop + '|']) {
          profileMap[crop + '|'] = traySize || 72;
        }
      }
    }

    // Process each planting row
    let updated = 0;
    let skipped = 0;
    const updates = [];

    for (let i = 1; i < planData.length; i++) {
      const row = planData[i];
      const crop = (row[cropCol] || '').toString().trim().toLowerCase();
      const variety = (row[varietyCol] || '').toString().trim().toLowerCase();
      const method = (row[methodCol] || '').toString().toLowerCase();
      const currentTraySize = row[traySizeCol];

      // Skip if already has a tray size
      if (currentTraySize && currentTraySize !== '' && currentTraySize !== 0) {
        skipped++;
        continue;
      }

      // Skip direct seed - they don't use trays
      if (method.includes('direct')) {
        skipped++;
        continue;
      }

      // Look up tray size from profile
      let traySize = profileMap[crop + '|' + variety] || profileMap[crop + '|'] || 72;

      updates.push({
        row: i + 1,
        col: traySizeCol + 1,
        value: traySize
      });
      updated++;
    }

    // Batch update all cells
    updates.forEach(u => {
      planSheet.getRange(u.row, u.col).setValue(u.value);
    });

    return {
      success: true,
      message: `Populated tray sizes: ${updated} updated, ${skipped} skipped (already set or direct seed)`,
      updated: updated,
      skipped: skipped
    };

  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

// ============================================
// PLANTING WIZARD WEB FUNCTIONS
// ============================================

/**
 * Save a planting from the web app (succession.html)
 * Accepts URL parameters and creates a row in PLANNING_2026
 */
function savePlantingFromWeb(params) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName('PLANNING_2026');

    if (!sheet) {
      return { success: false, error: 'PLANNING_2026 sheet not found' };
    }

    // Get headers to build row in correct order
    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Map URL parameters to header columns
    const paramMapping = {
      'STATUS': params.STATUS || 'Planned',
      'Batch_ID': params.Batch_ID || generateBatchId(params.Crop),
      'Crop': params.Crop || '',
      'Variety': params.Variety || 'Standard',
      'Planting_Method': params.Planting_Method || 'Transplant',
      'Target_Bed_ID': params.Target_Bed_ID || 'Unassigned',
      'Feet_Used': params.Feet_Used || 0,
      'Plants_Needed': params.Plants_Needed || 0,
      'Trays_Needed': params.Trays_Needed || 0,
      'Tray_Cell_Count': params.Tray_Cell_Count || 72,
      'Paperpot_Spacing': params.Paperpot_Spacing || '',
      'Plan_GH_Sow': params.Plan_GH_Sow || '',
      'Actual_GH_Sow': '',
      'Plan_Field_Sow': params.Plan_Field_Sow || '',
      'Actual_Field_Sow': '',
      'Plan_Transplant': params.Plan_Transplant || '',
      'Actual_Transplant': '',
      'First_Harvest': params.First_Harvest || '',
      'Last_Harvest': '',
      'Notes': params.Notes || ''
    };

    // Build row array matching header order
    const row = headers.map(header => {
      // Check for exact match first
      if (paramMapping.hasOwnProperty(header)) {
        return paramMapping[header];
      }
      // Check for case-insensitive match
      const lowerHeader = header.toLowerCase().replace(/[^a-z0-9]/g, '');
      for (const [key, value] of Object.entries(paramMapping)) {
        if (key.toLowerCase().replace(/[^a-z0-9]/g, '') === lowerHeader) {
          return value;
        }
      }
      return '';
    });

    // Append the row
    sheet.appendRow(row);

    // Try to deduct seeds from inventory
    let seedDeduction = null;
    try {
      seedDeduction = deductSeedsForPlanting({
        crop: paramMapping['Crop'],
        variety: paramMapping['Variety'],
        plantsNeeded: Number(paramMapping['Plants_Needed']) || 0,
        batchId: paramMapping['Batch_ID'],
        method: paramMapping['Planting_Method']
      });
    } catch (seedError) {
      // Non-fatal - planting still saved even if seed deduction fails
      Logger.log('Seed deduction error: ' + seedError.toString());
    }

    // Auto-generate tasks for this planting - STATE-OF-THE-ART
    let taskGeneration = null;
    try {
      taskGeneration = generatePlantingTasks({
        batchId: paramMapping['Batch_ID'],
        crop: paramMapping['Crop'],
        plantDate: paramMapping['Plan_Transplant'] || paramMapping['Plan_GH_Sow'] || paramMapping['Plan_Field_Sow'],
        bedId: paramMapping['Target_Bed_ID'] || ''
      });
    } catch (taskError) {
      // Non-fatal - planting still saved even if task generation fails
      Logger.log('Task generation error: ' + taskError.toString());
    }

    return {
      success: true,
      message: 'Planting saved successfully',
      batchId: paramMapping['Batch_ID'],
      crop: paramMapping['Crop'],
      variety: paramMapping['Variety'],
      seedDeduction: seedDeduction,
      taskGeneration: taskGeneration
    };

  } catch (error) {
    return {
      success: false,
      error: error.toString()
    };
  }
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════
// NATURAL LANGUAGE PLANTING INTELLIGENCE - AI-POWERED PLANTING CREATION
// Enables users to create plantings via natural language commands
// Example: "add four plantings Benefine Endive one per month starting May 1st"
// ═══════════════════════════════════════════════════════════════════════════════════════════════

/**
 * Parse a natural language planting request into structured data
 * Handles variations like:
 *   - "add four plantings Benefine Endive one per month starting May 1st"
 *   - "plant lettuce every 2 weeks from May through August"
 *   - "add a single planting of carrots on June 1"
 */
function parsePlantingRequest(params) {
  try {
    const text = (params.text || params.query || '').toLowerCase();

    if (!text) {
      return { success: false, error: 'No text provided to parse' };
    }

    const result = {
      crop: null,
      variety: null,
      count: 1,
      frequency: 'once',
      startDate: null,
      endDate: null,
      dates: [],
      rawText: text
    };

    // Extract crop and variety
    // Look for crop names from REF_CropProfiles
    const cropData = getCropProfiles();
    if (cropData.success && cropData.data) {
      for (const profile of cropData.data) {
        const cropName = String(profile.Crop_Name || '').toLowerCase();
        const variety = String(profile.Variety_Default || '').toLowerCase();

        if (text.includes(cropName)) {
          result.crop = profile.Crop_Name;

          // Check if variety is mentioned
          const varietyPattern = new RegExp(`\\b${variety}\\b`, 'i');
          if (variety && text.match(varietyPattern)) {
            result.variety = variety;
          }
          break;
        }
      }
    }

    // Extract count: "four plantings", "4 plantings", "a single planting"
    const countMatches = text.match(/(\d+|one|two|three|four|five|six|seven|eight|nine|ten|single)\s+(plantings?|succession)/);
    if (countMatches) {
      const numWord = countMatches[1];
      const numberMap = {
        'one': 1, 'single': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10
      };
      result.count = numberMap[numWord] || parseInt(numWord) || 1;
    }

    // Extract frequency: "every week", "weekly", "every 2 weeks", "biweekly", "monthly", "one per month"
    if (text.match(/weekly|every week|per week/)) {
      result.frequency = 'weekly';
    } else if (text.match(/biweekly|every (2|two) weeks|bi-weekly/)) {
      result.frequency = 'biweekly';
    } else if (text.match(/monthly|every month|per month|one per month/)) {
      result.frequency = 'monthly';
    } else if (text.match(/every (\d+) days/)) {
      const days = parseInt(text.match(/every (\d+) days/)[1]);
      result.frequency = `every_${days}_days`;
    }

    // Extract start date
    const startDateMatch = text.match(/starting\s+([a-z]+\s+\d+)/i) ||
                          text.match(/from\s+([a-z]+\s+\d+)/i) ||
                          text.match(/on\s+([a-z]+\s+\d+)/i);

    if (startDateMatch) {
      result.startDate = parseNaturalDate(startDateMatch[1]);
    }

    // Extract end date
    const endDateMatch = text.match(/through\s+([a-z]+)/i) || text.match(/until\s+([a-z]+)/i);
    if (endDateMatch) {
      result.endDate = parseNaturalDate(endDateMatch[1]);
    }

    // Generate dates array based on frequency and count
    if (result.startDate) {
      result.dates = generatePlantingDates({
        startDate: result.startDate,
        endDate: result.endDate,
        frequency: result.frequency,
        count: result.count
      });
    }

    return {
      success: true,
      data: result,
      summary: `Found: ${result.crop || 'unknown crop'}, ${result.count} plantings, ${result.frequency}, starting ${result.startDate || 'no date'}`
    };

  } catch (error) {
    return {
      success: false,
      error: error.toString()
    };
  }
}

/**
 * Parse a natural date string like "May 1st", "June 15", "first of the month"
 */
function parseNaturalDate(dateStr) {
  const str = dateStr.toLowerCase().trim();
  const currentYear = new Date().getFullYear();

  // Month mapping
  const months = {
    'jan': 0, 'january': 0,
    'feb': 1, 'february': 1,
    'mar': 2, 'march': 2,
    'apr': 3, 'april': 3,
    'may': 4,
    'jun': 5, 'june': 5,
    'jul': 6, 'july': 6,
    'aug': 7, 'august': 7,
    'sep': 8, 'sept': 8, 'september': 8,
    'oct': 9, 'october': 9,
    'nov': 10, 'november': 10,
    'dec': 11, 'december': 11
  };

  // Parse "May 1", "May 1st", "May 15th"
  const match = str.match(/([a-z]+)\s+(\d+)/);
  if (match) {
    const monthName = match[1];
    const day = parseInt(match[2]);

    for (const [key, monthNum] of Object.entries(months)) {
      if (monthName.startsWith(key)) {
        return formatDateYYYYMMDD(new Date(currentYear, monthNum, day));
      }
    }
  }

  // Parse just month name (default to 1st of month)
  for (const [key, monthNum] of Object.entries(months)) {
    if (str === key || str.startsWith(key)) {
      return formatDateYYYYMMDD(new Date(currentYear, monthNum, 1));
    }
  }

  // Parse "first of the month" - use current month
  if (str.includes('first of')) {
    const now = new Date();
    return formatDateYYYYMMDD(new Date(now.getFullYear(), now.getMonth(), 1));
  }

  return null;
}

/**
 * Generate a series of planting dates based on frequency
 */
function generatePlantingDates(params) {
  const { startDate, endDate, frequency, count } = params;
  const dates = [];

  if (!startDate) return dates;

  const start = new Date(startDate);
  let current = new Date(start);
  const end = endDate ? new Date(endDate) : null;

  for (let i = 0; i < count; i++) {
    // Check if we've exceeded end date
    if (end && current > end) break;

    dates.push(formatDateYYYYMMDD(current));

    // Calculate next date based on frequency
    if (frequency === 'weekly') {
      current.setDate(current.getDate() + 7);
    } else if (frequency === 'biweekly') {
      current.setDate(current.getDate() + 14);
    } else if (frequency === 'monthly') {
      current.setMonth(current.getMonth() + 1);
    } else if (frequency.startsWith('every_') && frequency.endsWith('_days')) {
      const days = parseInt(frequency.match(/every_(\d+)_days/)[1]);
      current.setDate(current.getDate() + days);
    } else {
      // Default: just do count times without incrementing
      break;
    }
  }

  return dates;
}

/**
 * Create multiple plantings from AI-parsed request
 * Automatically calculates sowing dates based on crop data
 */
function addPlantingsFromAI(params) {
  try {
    const { crop, variety, dates, autoSowing = true, plantsNeeded = 100, bedId = 'Unassigned' } = params;

    if (!crop) {
      return { success: false, error: 'Crop name is required' };
    }

    if (!dates || dates.length === 0) {
      return { success: false, error: 'No planting dates provided' };
    }

    // VALIDATION: Ensure all dates are valid ISO strings (YYYY-MM-DD)
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    const invalidDates = [];
    for (const d of dates) {
      if (typeof d !== 'string' || !dateRegex.test(d)) {
        invalidDates.push(d);
      } else {
        // Also validate the date is parseable and reasonable (year 2020-2030)
        const parsed = new Date(d);
        if (isNaN(parsed.getTime())) {
          invalidDates.push(d);
        } else {
          const year = parsed.getFullYear();
          if (year < 2020 || year > 2030) {
            invalidDates.push(d + ' (year out of range)');
          }
        }
      }
    }
    if (invalidDates.length > 0) {
      return {
        success: false,
        error: `Invalid date format. Expected YYYY-MM-DD strings (e.g., "2026-04-15"). Invalid: ${invalidDates.join(', ')}`
      };
    }

    // Get crop profile for transplant timing
    const cropProfile = getCropProfile(crop);
    let daysToTransplant = 28; // Default

    if (cropProfile.success && cropProfile.data) {
      // Try to find transplant days from crop profile
      const profile = cropProfile.data;
      daysToTransplant = profile.Rec_Transplant || profile.Days_To_Transplant || 28;
    }

    const results = [];
    const errors = [];

    // Create plantings for each date
    for (const fieldDate of dates) {
      try {
        const fieldDateObj = new Date(fieldDate);
        const sowDateObj = new Date(fieldDateObj);
        sowDateObj.setDate(sowDateObj.getDate() - daysToTransplant);
        const sowDate = formatDateYYYYMMDD(sowDateObj);

        // 1. Create greenhouse sowing (if autoSowing enabled)
        if (autoSowing) {
          const sowResult = savePlantingFromWeb({
            Crop: crop,
            Variety: variety || 'Standard',
            Planting_Method: 'Greenhouse Sowing',
            Plan_GH_Sow: sowDate,
            Plan_Transplant: fieldDate,
            Plants_Needed: plantsNeeded,
            Target_Bed_ID: 'Greenhouse',
            Notes: `Auto-sow for ${fieldDate} field transplant`
          });

          if (!sowResult.success) {
            errors.push(`Sowing ${sowDate}: ${sowResult.error}`);
          }
        }

        // 2. Create field transplant planting
        const transplantResult = savePlantingFromWeb({
          Crop: crop,
          Variety: variety || 'Standard',
          Planting_Method: 'Transplant',
          Plan_Transplant: fieldDate,
          Plants_Needed: plantsNeeded,
          Target_Bed_ID: bedId,
          Notes: autoSowing ? `From ${sowDate} greenhouse sowing` : 'Added via AI'
        });

        if (transplantResult.success) {
          results.push({
            fieldDate: fieldDate,
            sowDate: autoSowing ? sowDate : null,
            batchId: transplantResult.batchId,
            crop: crop,
            variety: variety
          });
        } else {
          errors.push(`Transplant ${fieldDate}: ${transplantResult.error}`);
        }

      } catch (dateError) {
        errors.push(`Date ${fieldDate}: ${dateError.toString()}`);
      }
    }

    return {
      success: results.length > 0,
      plantingsCreated: results.length,
      details: results,
      errors: errors.length > 0 ? errors : null,
      summary: `Created ${results.length} planting(s) of ${crop} ${variety || ''} ${autoSowing ? 'with greenhouse sowings' : ''}`
    };

  } catch (error) {
    return {
      success: false,
      error: error.toString()
    };
  }
}

/**
 * Format a Date object as YYYY-MM-DD string
 */
function formatDateYYYYMMDD(date) {
  const d = new Date(date);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

