/**
 * Upload a video to YouTube
 * Note: Videos must be at a publicly accessible URL
 */
function postToYouTube(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const accessToken = props.getProperty('YOUTUBE_ACCESS_TOKEN');

        if (!accessToken) {
            return { success: false, error: 'YouTube not configured. Set up API credentials first.', setup_required: true };
        }

        const { title, description, videoUrl, tags, privacyStatus } = params;

        // For now, YouTube requires video upload via resumable upload or direct file
        // This is a placeholder for the community post feature
        return {
            success: false,
            error: 'YouTube video upload requires direct file upload. Use YouTube Studio or the uploadVideoToYouTube function with file data.',
            hint: 'For community posts (text/image), YouTube Community API is more suitable.'
        };
    } catch (error) {
        Logger.log('Error posting to YouTube: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

// =============================================================================
// TIKTOK POSTING FUNCTIONS
// =============================================================================

/**
 * Post a video to TikTok
 * Note: Requires approved Content Posting API access
 */
function postToTikTok(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const accessToken = props.getProperty('TIKTOK_ACCESS_TOKEN');

        if (!accessToken) {
            return { success: false, error: 'TikTok not configured. Set up API credentials first.', setup_required: true };
        }

        const { videoUrl, caption } = params;

        // Step 1: Initialize video upload
        const initResponse = UrlFetchApp.fetch('https://open.tiktokapis.com/v2/post/publish/video/init/', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            payload: JSON.stringify({
                post_info: {
                    title: caption,
                    privacy_level: 'MUTUAL_FOLLOW_FRIENDS' // Can be PUBLIC_TO_EVERYONE, MUTUAL_FOLLOW_FRIENDS, SELF_ONLY
                },
                source_info: {
                    source: 'PULL_FROM_URL',
                    video_url: videoUrl
                }
            }),
            muteHttpExceptions: true
        });

        const initResult = JSON.parse(initResponse.getContentText());

        if (initResult.error) {
            return { success: false, error: initResult.error.message || 'Failed to initialize upload' };
        }

        // Log the post
        logSocialPost({
            account: 'TikTok',
            mediaType: 'VIDEO',
            caption: caption,
            mediaId: initResult.data?.publish_id || 'pending',
            timestamp: new Date().toISOString()
        });

        return {
            success: true,
            platform: 'tiktok',
            publishId: initResult.data?.publish_id,
            message: 'Video submitted to TikTok for processing'
        };
    } catch (error) {
        Logger.log('Error posting to TikTok: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

// =============================================================================
// PINTEREST POSTING FUNCTIONS
// =============================================================================

/**
 * Create a Pin on Pinterest
 */
function postToPinterest(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const accessToken = props.getProperty('PINTEREST_ACCESS_TOKEN');

        if (!accessToken) {
            return { success: false, error: 'Pinterest not configured. Set up API credentials first.', setup_required: true };
        }

        const { boardId, imageUrl, title, description, link } = params;

        if (!boardId) {
            return { success: false, error: 'Board ID is required. Use getPinterestBoards() to get available boards.' };
        }

        const pinData = {
            board_id: boardId,
            media_source: {
                source_type: 'image_url',
                url: imageUrl
            }
        };

        if (title) pinData.title = title;
        if (description) pinData.description = description;
        if (link) pinData.link = link;

        const response = UrlFetchApp.fetch('https://api.pinterest.com/v5/pins', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            payload: JSON.stringify(pinData),
            muteHttpExceptions: true
        });

        const result = JSON.parse(response.getContentText());

        if (result.code) {
            return { success: false, error: result.message || 'Failed to create pin' };
        }

        // Log the post
        logSocialPost({
            account: 'Pinterest',
            mediaType: 'PIN',
            caption: description || title || '',
            mediaId: result.id,
            timestamp: new Date().toISOString()
        });

        return {
            success: true,
            platform: 'pinterest',
            pinId: result.id,
            pinUrl: `https://pinterest.com/pin/${result.id}`
        };
    } catch (error) {
        Logger.log('Error posting to Pinterest: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Get user's Pinterest boards
 */
function getPinterestBoards() {
    try {
        const props = PropertiesService.getScriptProperties();
        const accessToken = props.getProperty('PINTEREST_ACCESS_TOKEN');

        if (!accessToken) {
            return { success: false, error: 'Pinterest not configured' };
        }

        const response = UrlFetchApp.fetch('https://api.pinterest.com/v5/boards', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${accessToken}`
            },
            muteHttpExceptions: true
        });

        const result = JSON.parse(response.getContentText());

        if (result.code) {
            return { success: false, error: result.message };
        }

        return {
            success: true,
            boards: result.items.map(board => ({
                id: board.id,
                name: board.name,
                description: board.description,
                pinCount: board.pin_count
            }))
        };
    } catch (error) {
        Logger.log('Error getting Pinterest boards: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

function logSocialPost(params) {
    try {
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let sheet = ss.getSheetByName('MARKETING_InstagramPosts');
        if (!sheet) { sheet = ss.insertSheet('MARKETING_InstagramPosts'); sheet.getRange(1, 1, 1, 7).setValues([['Timestamp', 'Account', 'Media_Type', 'Caption', 'Media_ID', 'Impressions', 'Engagement']]); sheet.setFrozenRows(1); }
        sheet.appendRow([params.timestamp || new Date().toISOString(), params.account || '', params.mediaType || '', params.caption || '', params.mediaId || '', params.impressions || 0, params.engagement || 0]);
        return { success: true };
    } catch (error) { Logger.log('Error logging social post: ' + error.toString()); return { success: false, error: error.toString() }; }
}

/**
 * Get Social Media Stats for all platforms
 * Returns follower counts and growth data for the Social Growth Engine
 */
function getSocialStats(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);

        // Get or create Social Stats tracking sheet
        let statsSheet = ss.getSheetByName('MARKETING_SocialStats');
        if (!statsSheet) {
            statsSheet = ss.insertSheet('MARKETING_SocialStats');
            statsSheet.getRange(1, 1, 1, 10).setValues([[
                'Timestamp', 'Platform', 'Account_Handle', 'Followers', 'Following',
                'Posts', 'Engagement_Rate', 'Impressions', 'Reach', 'Growth_Weekly'
            ]]);
            statsSheet.setFrozenRows(1);
        }

        const stats = {
            instagram: {},
            facebook: {},
            tiktok: {},
            pinterest: {},
            youtube: {},
            threads: {}
        };

        // Try to get Instagram stats from Graph API if configured
        const accounts = JSON.parse(props.getProperty('instagram_accounts') || '[]');
        for (let i = 0; i < accounts.length; i++) {
            const account = accounts[i];
            const accessToken = props.getProperty(`ig_token_${i}`);
            if (accessToken && account.igUserId) {
                try {
                    const result = JSON.parse(UrlFetchApp.fetch(
                        `https://graph.facebook.com/v24.0/${account.igUserId}?fields=followers_count,media_count,username&access_token=${accessToken}`,
                        { muteHttpExceptions: true }
                    ).getContentText());

                    if (!result.error) {
                        stats.instagram[account.name || result.username] = {
                            followers: result.followers_count || 0,
                            posts: result.media_count || 0,
                            handle: result.username || account.name
                        };
                    }
                } catch (apiError) {
                    Logger.log('Instagram API error for ' + account.name + ': ' + apiError.toString());
                }
            }
        }

        // Get historical data from sheet for growth calculation
        const data = statsSheet.getDataRange().getValues();
        const latestByPlatform = {};
        const weekAgoByPlatform = {};
        const weekAgo = new Date();
        weekAgo.setDate(weekAgo.getDate() - 7);

        for (let i = 1; i < data.length; i++) {
            const row = data[i];
            const timestamp = new Date(row[0]);
            const platform = row[1];
            const handle = row[2];
            const followers = row[3];
            const key = `${platform}_${handle}`;

            if (!latestByPlatform[key] || timestamp > latestByPlatform[key].timestamp) {
                latestByPlatform[key] = { timestamp, followers, platform, handle };
            }
            if (timestamp <= weekAgo && (!weekAgoByPlatform[key] || timestamp > weekAgoByPlatform[key].timestamp)) {
                weekAgoByPlatform[key] = { timestamp, followers, platform, handle };
            }
        }

        // Calculate growth rates
        const growth = {};
        Object.keys(latestByPlatform).forEach(key => {
            const latest = latestByPlatform[key];
            const weekAgoData = weekAgoByPlatform[key];
            if (weekAgoData && weekAgoData.followers > 0) {
                growth[key] = {
                    current: latest.followers,
                    weekAgo: weekAgoData.followers,
                    growthRate: ((latest.followers - weekAgoData.followers) / weekAgoData.followers * 100).toFixed(2) + '%',
                    growthAbsolute: latest.followers - weekAgoData.followers
                };
            }
        });

        return {
            success: true,
            timestamp: new Date().toISOString(),
            stats: stats,
            growth: growth,
            message: accounts.length > 0 ? `Found ${accounts.length} configured Instagram accounts` : 'No Instagram accounts configured. Add accounts in Connections tab.'
        };
    } catch (error) {
        Logger.log('Error getting social stats: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Log social stats for tracking growth over time
 */
function logSocialStats(params) {
    try {
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let sheet = ss.getSheetByName('MARKETING_SocialStats');
        if (!sheet) {
            sheet = ss.insertSheet('MARKETING_SocialStats');
            sheet.getRange(1, 1, 1, 10).setValues([[
                'Timestamp', 'Platform', 'Account_Handle', 'Followers', 'Following',
                'Posts', 'Engagement_Rate', 'Impressions', 'Reach', 'Growth_Weekly'
            ]]);
            sheet.setFrozenRows(1);
        }

        sheet.appendRow([
            params.timestamp || new Date().toISOString(),
            params.platform || '',
            params.handle || '',
            params.followers || 0,
            params.following || 0,
            params.posts || 0,
            params.engagementRate || 0,
            params.impressions || 0,
            params.reach || 0,
            params.growthWeekly || 0
        ]);

        return { success: true };
    } catch (error) {
        Logger.log('Error logging social stats: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

