/**
 * Generate Daily Briefing - THE BRAIN
 * Creates prioritized action list with AI-generated recommendations
 * Call this every morning at 6 AM via trigger
 */
function generateDailyBriefing(params) {
    try {
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        const today = new Date();
        const dayOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][today.getDay()];

        // Gather all intelligence
        const sentimentHealth = checkSentimentHealth({});
        const commentsQueue = getCommentsNeedingResponse({});
        const scheduledPosts = getScheduledPosts({ status: 'scheduled' });
        const evergreenReady = getEvergreenContent({});
        const revenueData = getRevenueByPlatform({});
        const optimalTimes = calculateOptimalTimes({});
        const socialStats = getSocialStats({});

        // Build action queue by priority
        const urgentActions = [];
        const todayActions = [];
        const thisWeekActions = [];

        // PRIORITY 1: Crisis check
        if (sentimentHealth.status === 'crisis') {
            urgentActions.push({
                priority: 'CRITICAL',
                type: 'CRISIS_RESPONSE',
                action: 'Review negative comments immediately - posts are paused',
                estimatedImpact: 'Prevent reputation damage',
                aiRecommendation: 'Address complaints before resuming posting'
            });
        }

        // PRIORITY 2: Sales opportunity comments
        const salesComments = (commentsQueue.comments || []).filter(c =>
            c.text && (
                c.text.toLowerCase().includes('order') ||
                c.text.toLowerCase().includes('buy') ||
                c.text.toLowerCase().includes('deliver') ||
                c.text.toLowerCase().includes('price') ||
                c.text.toLowerCase().includes('available') ||
                c.text.toLowerCase().includes('how do i') ||
                c.text.toLowerCase().includes('where can')
            )
        );

        salesComments.forEach(comment => {
            urgentActions.push({
                priority: 'HIGH',
                type: 'SALES_OPPORTUNITY',
                action: `Reply to @${comment.author}: "${comment.text.substring(0, 50)}..."`,
                platform: comment.platform,
                draftReply: comment.aiDraftReply,
                estimatedImpact: 'Potential sale - respond within 1 hour',
                commentId: comment.id
            });
        });

        // PRIORITY 3: Complaint comments
        const complaintComments = (commentsQueue.comments || []).filter(c =>
            c.sentiment < -0.3 && !salesComments.includes(c)
        );

        complaintComments.forEach(comment => {
            urgentActions.push({
                priority: 'HIGH',
                type: 'COMPLAINT_RESPONSE',
                action: `Address complaint from @${comment.author}`,
                platform: comment.platform,
                draftReply: comment.aiDraftReply,
                estimatedImpact: 'Prevent negative review - respond within 2 hours',
                commentId: comment.id
            });
        });

        // PRIORITY 4: Other comments needing response
        const otherComments = (commentsQueue.comments || []).filter(c =>
            !salesComments.includes(c) && !complaintComments.includes(c)
        );

        if (otherComments.length > 0) {
            todayActions.push({
                priority: 'MEDIUM',
                type: 'COMMENT_RESPONSE',
                action: `Reply to ${otherComments.length} other comments`,
                estimatedImpact: 'Build community engagement'
            });
        }

        // PRIORITY 5: Content posting recommendations
        const postRecommendation = getNextBestPost({ dayOfWeek: dayOfWeek });
        if (postRecommendation.success && postRecommendation.recommendation) {
            todayActions.push({
                priority: 'MEDIUM',
                type: 'CREATE_POST',
                action: postRecommendation.recommendation.action,
                contentIdea: postRecommendation.recommendation.contentIdea,
                bestTime: postRecommendation.recommendation.bestTime,
                platform: postRecommendation.recommendation.platform,
                estimatedImpact: postRecommendation.recommendation.expectedEngagement,
                aiGeneratedCaption: postRecommendation.recommendation.suggestedCaption
            });
        }

        // PRIORITY 6: Evergreen recycling opportunity
        if (evergreenReady.content && evergreenReady.content.length > 0) {
            const topEvergreen = evergreenReady.content[0];
            if (topEvergreen.daysSinceUsed > 60) {
                thisWeekActions.push({
                    priority: 'LOW',
                    type: 'RECYCLE_CONTENT',
                    action: `Recycle high-performer: "${topEvergreen.content.substring(0, 50)}..."`,
                    originalPerformance: topEvergreen.performanceScore,
                    daysSinceUsed: topEvergreen.daysSinceUsed,
                    evergreenId: topEvergreen.id
                });
            }
        }

        // Build performance summary
        const yesterdayPerformance = {
            postsScheduled: (scheduledPosts.posts || []).length,
            commentsReceived: (commentsQueue.comments || []).length,
            sentimentScore: sentimentHealth.avgSentiment || 0,
            revenueAttributed: Object.values(revenueData.platforms || {}).reduce((sum, p) => sum + (p.revenue || 0), 0)
        };

        // Generate AI summary
        const briefingSummary = generateBriefingSummary({
            urgentCount: urgentActions.length,
            todayCount: todayActions.length,
            sentimentStatus: sentimentHealth.status,
            dayOfWeek: dayOfWeek
        });

        // Store briefing
        let briefingSheet = ss.getSheetByName('SOCIAL_DailyBriefings');
        if (!briefingSheet) {
            briefingSheet = ss.insertSheet('SOCIAL_DailyBriefings');
            briefingSheet.getRange(1, 1, 1, 8).setValues([[
                'Date', 'Day', 'Urgent_Count', 'Today_Count', 'Sentiment_Status',
                'Revenue_Attributed', 'Briefing_JSON', 'Generated_At'
            ]]);
            briefingSheet.setFrozenRows(1);
        }

        const briefingData = {
            date: today.toISOString().split('T')[0],
            dayOfWeek: dayOfWeek,
            summary: briefingSummary,
            urgentActions: urgentActions,
            todayActions: todayActions,
            thisWeekActions: thisWeekActions,
            performance: yesterdayPerformance,
            optimalPostTimes: optimalTimes.optimalTimes || {},
            generatedAt: today.toISOString()
        };

        briefingSheet.appendRow([
            today.toISOString().split('T')[0],
            dayOfWeek,
            urgentActions.length,
            todayActions.length,
            sentimentHealth.status,
            yesterdayPerformance.revenueAttributed,
            JSON.stringify(briefingData),
            today.toISOString()
        ]);

        // Send SMS alert if urgent actions exist
        if (urgentActions.length > 0 || sentimentHealth.status === 'crisis') {
            sendSocialBrainAlert({
                urgentCount: urgentActions.length,
                status: sentimentHealth.status,
                topUrgent: urgentActions[0]
            });
        }

        return {
            success: true,
            briefing: briefingData,
            message: `Daily briefing generated: ${urgentActions.length} urgent, ${todayActions.length} today`
        };
    } catch (error) {
        Logger.log('Error generating daily briefing: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Get Next Best Post - AI recommends what to post
 * Considers: day of week, content gaps, seasonal relevance, past performance
 */
function getNextBestPost(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const apiKey = props.getProperty('ANTHROPIC_API_KEY') || props.getProperty('OPENAI_API_KEY');

        if (!apiKey) {
            // Return default recommendation without AI
            return {
                success: true,
                recommendation: {
                    action: 'Create and post content',
                    contentIdea: 'Share what you harvested today',
                    bestTime: '9:00 AM',
                    platform: 'instagram',
                    expectedEngagement: 'Average',
                    suggestedCaption: null
                }
            };
        }

        // Get context
        const trainingPosts = getTrainingPosts({});
        const evergreenContent = getEvergreenContent({});
        const recentPosts = getScheduledPosts({ status: 'posted' });

        const topPosts = (trainingPosts.posts || []).slice(0, 5).map(p => p.content).join('\n---\n');
        const dayOfWeek = params.dayOfWeek || new Date().toLocaleDateString('en-US', { weekday: 'long' });
        const month = new Date().toLocaleDateString('en-US', { month: 'long' });

        // Determine which API to use
        const isAnthropicKey = apiKey.startsWith('sk-ant');

        let response;
        if (isAnthropicKey) {
            response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
                method: 'POST',
                headers: {
                    'x-api-key': apiKey,
                    'anthropic-version': '2023-06-01',
                    'Content-Type': 'application/json'
                },
                payload: JSON.stringify({
                    model: 'claude-sonnet-4-20250514',
                    max_tokens: 1000,
                    messages: [{
                        role: 'user',
                        content: `You are the social media brain for Tiny Seed Farm, a small organic farm in Pennsylvania.

TODAY: ${dayOfWeek}, ${month}
FARM CONTEXT: Small family farm, CSA boxes, farmers markets, organic vegetables and flowers

TOP PERFORMING POSTS (match this voice):
${topPosts || 'No training data yet - use authentic farm voice'}

Based on the day of week and season, recommend what to post TODAY.

Return JSON only:
{
  "action": "What to do",
  "contentIdea": "Specific content idea for today",
  "bestTime": "Optimal posting time",
  "platform": "instagram or facebook",
  "expectedEngagement": "High/Medium/Low with reason",
  "suggestedCaption": "Full caption in the farm's voice",
  "hashtags": ["relevant", "hashtags"],
  "whyThisWorks": "Brief explanation"
}`
                    }]
                }),
                muteHttpExceptions: true
            });
        } else {
            response = UrlFetchApp.fetch('https://api.openai.com/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Authorization': 'Bearer ' + apiKey,
                    'Content-Type': 'application/json'
                },
                payload: JSON.stringify({
                    model: 'gpt-4o',
                    messages: [
                        { role: 'system', content: 'You are the social media brain for Tiny Seed Farm.' },
                        { role: 'user', content: `TODAY: ${dayOfWeek}, ${month}

TOP POSTS (match this voice):
${topPosts || 'Use authentic farm voice'}

Recommend what to post. Return JSON: {"action": "", "contentIdea": "", "bestTime": "", "platform": "", "expectedEngagement": "", "suggestedCaption": "", "hashtags": [], "whyThisWorks": ""}` }
                    ],
                    temperature: 0.7
                }),
                muteHttpExceptions: true
            });
        }

        const result = JSON.parse(response.getContentText());

        let content;
        if (isAnthropicKey) {
            content = result.content && result.content[0] ? result.content[0].text : null;
        } else {
            content = result.choices && result.choices[0] ? result.choices[0].message.content : null;
        }

        if (!content) {
            return { success: false, error: 'No recommendation generated' };
        }

        try {
            const recommendation = JSON.parse(content.replace(/```json\n?|\n?```/g, ''));
            return { success: true, recommendation: recommendation };
        } catch (e) {
            return { success: true, recommendation: { rawRecommendation: content } };
        }
    } catch (error) {
        Logger.log('Error getting next best post: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Generate Briefing Summary - Natural language summary
 */
function generateBriefingSummary(params) {
    const { urgentCount, todayCount, sentimentStatus, dayOfWeek } = params;

    let summary = `Good morning! Here's your ${dayOfWeek} social media briefing.\n\n`;

    if (sentimentStatus === 'crisis') {
        summary += '🚨 ALERT: Negative sentiment detected. All posting is paused until you review.\n\n';
    } else if (sentimentStatus === 'warning') {
        summary += '⚠️ HEADS UP: Some negative comments need attention.\n\n';
    }

    if (urgentCount > 0) {
        summary += `📌 ${urgentCount} urgent action${urgentCount > 1 ? 's' : ''} requiring immediate attention.\n`;
    }

    if (todayCount > 0) {
        summary += `📋 ${todayCount} item${todayCount > 1 ? 's' : ''} on your social media to-do list for today.\n`;
    }

    if (urgentCount === 0 && todayCount === 0) {
        summary += '✅ No urgent items! Great time to create fresh content or engage with your community.\n';
    }

    return summary;
}

/**
 * Get Social Action Queue - Priority-ordered actions for dashboard
 *
 * Updated 2026-02-11: Now uses unified task system as primary source
 * Falls back to legacy briefing data if no unified tasks exist
 *
 * Parameters:
 *   useUnified - 'true' to use unified task system (default: true)
 *   syncFromBriefing - 'true' to sync briefing actions to unified (default: false)
 */
function getSocialActionQueue(params) {
    try {
        const useUnified = params.useUnified !== 'false';
        const syncFromBriefing = params.syncFromBriefing === 'true';

        // Try to get marketing tasks from unified system first
        if (useUnified) {
            const unifiedResult = getMarketingTasksFromUnified(params);
            if (unifiedResult.success && unifiedResult.stats.total > 0) {
                return {
                    success: true,
                    source: 'unified',
                    actionQueue: unifiedResult.actionQueue,
                    stats: unifiedResult.stats,
                    generatedAt: new Date().toISOString()
                };
            }
        }

        // Fall back to legacy briefing system
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        const briefingSheet = ss.getSheetByName('SOCIAL_DailyBriefings');

        if (!briefingSheet) {
            // Generate new briefing
            const briefingResult = generateDailyBriefing({});

            // Sync to unified tasks if requested
            if (syncFromBriefing && briefingResult.success && briefingResult.briefing) {
                syncMarketingActionsToUnifiedTasks(briefingResult.briefing.urgentActions || [], 'urgent');
                syncMarketingActionsToUnifiedTasks(briefingResult.briefing.todayActions || [], 'today');
            }

            return briefingResult;
        }

        const data = briefingSheet.getDataRange().getValues();
        if (data.length <= 1) {
            return generateDailyBriefing({});
        }

        // Get today's or most recent briefing
        const today = new Date().toISOString().split('T')[0];
        let latestBriefing = null;

        for (let i = data.length - 1; i >= 1; i--) {
            if (data[i][0] === today) {
                latestBriefing = JSON.parse(data[i][6]);
                break;
            }
        }

        if (!latestBriefing) {
            // Generate new briefing for today
            const briefingResult = generateDailyBriefing({});

            // Sync to unified tasks
            if (syncFromBriefing && briefingResult.success && briefingResult.briefing) {
                syncMarketingActionsToUnifiedTasks(briefingResult.briefing.urgentActions || [], 'urgent');
                syncMarketingActionsToUnifiedTasks(briefingResult.briefing.todayActions || [], 'today');
            }

            return briefingResult;
        }

        // Sync existing briefing actions to unified system if requested
        if (syncFromBriefing) {
            syncMarketingActionsToUnifiedTasks(latestBriefing.urgentActions || [], 'urgent');
            syncMarketingActionsToUnifiedTasks(latestBriefing.todayActions || [], 'today');
        }

        return {
            success: true,
            source: 'briefing',
            actionQueue: {
                urgent: latestBriefing.urgentActions || [],
                today: latestBriefing.todayActions || [],
                thisWeek: latestBriefing.thisWeekActions || []
            },
            summary: latestBriefing.summary,
            generatedAt: latestBriefing.generatedAt
        };
    } catch (error) {
        Logger.log('Error getting action queue: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Classify Comment Priority - Detect sales opportunities
 */
function classifyCommentPriority(params) {
    try {
        const text = (params.text || '').toLowerCase();

        // Sales opportunity keywords
        const salesKeywords = ['order', 'buy', 'purchase', 'deliver', 'shipping', 'price', 'cost',
            'available', 'how do i', 'where can', 'when can', 'do you have', 'can i get',
            'sign up', 'subscribe', 'csa', 'membership', 'how much'];

        // Complaint keywords
        const complaintKeywords = ['disappointed', 'unhappy', 'wrong', 'bad', 'terrible',
            'never again', 'refund', 'missing', 'late', 'damaged', 'rotten', 'moldy'];

        // Question keywords
        const questionKeywords = ['how', 'what', 'when', 'where', 'why', 'can you', 'do you',
            'is there', 'are there'];

        // Check for sales opportunity first (highest value)
        const isSalesOpportunity = salesKeywords.some(kw => text.includes(kw));
        if (isSalesOpportunity) {
            return {
                success: true,
                priority: 1,
                category: 'SALES_OPPORTUNITY',
                responseTime: '1 hour',
                reason: 'Potential customer inquiry detected'
            };
        }

        // Check for complaint
        const isComplaint = complaintKeywords.some(kw => text.includes(kw));
        if (isComplaint) {
            return {
                success: true,
                priority: 2,
                category: 'COMPLAINT',
                responseTime: '2 hours',
                reason: 'Negative feedback requires attention'
            };
        }

        // Check for question
        const isQuestion = questionKeywords.some(kw => text.includes(kw)) || text.includes('?');
        if (isQuestion) {
            return {
                success: true,
                priority: 3,
                category: 'QUESTION',
                responseTime: '4 hours',
                reason: 'Question from potential or current customer'
            };
        }

        // Default: compliment/other
        return {
            success: true,
            priority: 4,
            category: 'ENGAGEMENT',
            responseTime: '24 hours',
            reason: 'General engagement - respond when convenient'
        };
    } catch (error) {
        return { success: false, error: error.toString() };
    }
}

/**
 * Generate Weekly Content Calendar
 * Creates 7-day content plan based on AI analysis
 */
function generateContentCalendar(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const apiKey = props.getProperty('ANTHROPIC_API_KEY') || props.getProperty('OPENAI_API_KEY');

        const startDate = params.startDate ? new Date(params.startDate) : new Date();
        const trainingPosts = getTrainingPosts({});
        const topPosts = (trainingPosts.posts || []).slice(0, 10).map(p => p.content).join('\n---\n');

        const month = startDate.toLocaleDateString('en-US', { month: 'long' });
        const weekStart = startDate.toISOString().split('T')[0];

        if (!apiKey) {
            // Return template calendar without AI
            const defaultCalendar = [];
            for (let i = 0; i < 7; i++) {
                const date = new Date(startDate);
                date.setDate(date.getDate() + i);
                const dayName = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][date.getDay()];

                defaultCalendar.push({
                    date: date.toISOString().split('T')[0],
                    day: dayName,
                    platform: 'instagram',
                    contentType: i % 2 === 0 ? 'harvest_photo' : 'behind_scenes',
                    idea: 'Share what\'s happening on the farm today',
                    bestTime: '9:00 AM',
                    caption: null
                });
            }
            return { success: true, calendar: defaultCalendar, generatedBy: 'template' };
        }

        const isAnthropicKey = apiKey.startsWith('sk-ant');
        let response;

        const prompt = `Create a 7-day social media content calendar for Tiny Seed Farm starting ${weekStart}.

CONTEXT: Small organic farm in Pennsylvania, ${month}. CSA boxes, farmers markets, vegetables and flowers.

VOICE EXAMPLES (match this style):
${topPosts || 'Authentic, warm, farm-focused content'}

Generate a calendar with variety: harvest photos, behind-scenes, educational, engagement posts.

Return JSON array of 7 days:
[{
  "date": "YYYY-MM-DD",
  "day": "Monday",
  "platform": "instagram",
  "contentType": "harvest_photo|behind_scenes|educational|engagement|recipe",
  "idea": "Specific content idea",
  "bestTime": "9:00 AM",
  "caption": "Full caption in farm voice with hashtags"
}]`;

        if (isAnthropicKey) {
            response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
                method: 'POST',
                headers: {
                    'x-api-key': apiKey,
                    'anthropic-version': '2023-06-01',
                    'Content-Type': 'application/json'
                },
                payload: JSON.stringify({
                    model: 'claude-sonnet-4-20250514',
                    max_tokens: 2000,
                    messages: [{ role: 'user', content: prompt }]
                }),
                muteHttpExceptions: true
            });
        } else {
            response = UrlFetchApp.fetch('https://api.openai.com/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Authorization': 'Bearer ' + apiKey,
                    'Content-Type': 'application/json'
                },
                payload: JSON.stringify({
                    model: 'gpt-4o',
                    messages: [{ role: 'user', content: prompt }],
                    temperature: 0.7
                }),
                muteHttpExceptions: true
            });
        }

        const result = JSON.parse(response.getContentText());
        let content;

        if (isAnthropicKey) {
            content = result.content && result.content[0] ? result.content[0].text : null;
        } else {
            content = result.choices && result.choices[0] ? result.choices[0].message.content : null;
        }

        if (!content) {
            return { success: false, error: 'No calendar generated' };
        }

        try {
            const calendar = JSON.parse(content.replace(/```json\n?|\n?```/g, ''));

            // Store calendar
            const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
            let calendarSheet = ss.getSheetByName('SOCIAL_ContentCalendar');
            if (!calendarSheet) {
                calendarSheet = ss.insertSheet('SOCIAL_ContentCalendar');
                calendarSheet.getRange(1, 1, 1, 8).setValues([[
                    'Date', 'Day', 'Platform', 'Content_Type', 'Idea', 'Best_Time', 'Caption', 'Status'
                ]]);
                calendarSheet.setFrozenRows(1);
            }

            calendar.forEach(day => {
                calendarSheet.appendRow([
                    day.date,
                    day.day,
                    day.platform,
                    day.contentType,
                    day.idea,
                    day.bestTime,
                    day.caption,
                    'planned'
                ]);
            });

            return { success: true, calendar: calendar, generatedBy: 'ai' };
        } catch (e) {
            return { success: true, rawCalendar: content };
        }
    } catch (error) {
        Logger.log('Error generating content calendar: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Generate Content For Gap Days
 * Creates AI-generated content for days that don't have scheduled posts
 */
function generateContentForGaps(params) {
    try {
        const dates = params.dates || [];
        const platforms = params.platforms || ['instagram', 'facebook'];

        if (dates.length === 0) {
            return { success: false, error: 'No dates provided' };
        }

        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let queueSheet = ss.getSheetByName('MARKETING_Queue');
        if (!queueSheet) {
            queueSheet = ss.insertSheet('MARKETING_Queue');
            queueSheet.getRange(1, 1, 1, 8).setValues([[
                'Queue_ID', 'Scheduled_Date', 'Platform', 'Content', 'Content_Type', 'Status', 'Created_At', 'AI_Generated'
            ]]);
            queueSheet.setFrozenRows(1);
        }

        const contentIdeas = [
            { type: 'original', template: 'Fresh harvest alert! Check out what we picked today. These beauties are ready for your kitchen! #TinySeedFarm #FarmFresh #LocalFood' },
            { type: 'curated', template: 'Great tip we found: Store your leafy greens wrapped in a paper towel to keep them fresh longer. What are your best produce storage tips? #FarmTips' },
            { type: 'personal', template: 'Morning vibes on the farm. There\'s nothing like watching the sunrise over the fields. What do you love about mornings? #FarmLife #MorningMotivation' },
            { type: 'original', template: 'Behind the scenes: This is what harvest day looks like! It takes a lot of work to get these veggies from field to your table. #BehindTheScenes #FarmToTable' },
            { type: 'curated', template: 'Support local farmers this week! When you buy local, you\'re supporting your community and getting the freshest produce possible. #SupportLocal #ShopLocal' }
        ];

        let generatedCount = 0;
        const generatedPosts = [];

        dates.forEach((dateStr, index) => {
            const idea = contentIdeas[index % contentIdeas.length];
            platforms.forEach(platform => {
                const queueId = 'Q-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4);
                const row = [
                    queueId,
                    dateStr + 'T10:00:00',
                    platform,
                    idea.template,
                    idea.type,
                    'draft',
                    new Date().toISOString(),
                    'true'
                ];
                queueSheet.appendRow(row);
                generatedCount++;
                generatedPosts.push({ id: queueId, date: dateStr, platform: platform, content: idea.template });
            });
        });

        return { success: true, generated: generatedCount, posts: generatedPosts };
    } catch (error) {
        Logger.log('Error generating content for gaps: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Enhance Caption with AI
 * Uses Claude or OpenAI to improve a caption while maintaining brand voice
 */
function enhanceCaption(params) {
    try {
        const caption = params.caption || '';
        const platform = params.platform || 'instagram';
        const tone = params.tone || 'authentic farm voice';

        if (!caption.trim()) {
            return { success: false, error: 'No caption provided' };
        }

        // Get API key from Script Properties
        const props = PropertiesService.getScriptProperties();
        const claudeKey = props.getProperty('CLAUDE_API_KEY');
        const openaiKey = props.getProperty('OPENAI_API_KEY');

        if (!claudeKey && !openaiKey) {
            // Fallback: Add hashtags and emojis
            const hashtags = ' #TinySeedFarm #FarmFresh #LocalFood #Pittsburgh #FarmToTable';
            const enhanced = caption.trim() + '\n\n' + hashtags;
            return { success: true, enhancedCaption: enhanced, method: 'fallback' };
        }

        const prompt = `You are a social media expert for Tiny Seed Farm, a small organic farm in Pittsburgh.

Enhance this ${platform} caption while keeping the ${tone}:

Original: "${caption}"

Requirements:
- Keep the authentic, friendly voice
- Keep it under 2200 characters for Instagram
- Add 3-5 relevant hashtags
- Add 1-2 appropriate emojis
- Make it engaging and shareable
- Include a call to action if appropriate

Return ONLY the enhanced caption, nothing else.`;

        let enhancedCaption;

        if (claudeKey) {
            const response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'x-api-key': claudeKey,
                    'anthropic-version': '2023-06-01'
                },
                payload: JSON.stringify({
                    model: 'claude-3-haiku-20240307',
                    max_tokens: 500,
                    messages: [{ role: 'user', content: prompt }]
                }),
                muteHttpExceptions: true
            });

            const result = JSON.parse(response.getContentText());
            if (result.content && result.content[0]) {
                enhancedCaption = result.content[0].text;
            }
        } else if (openaiKey) {
            const response = UrlFetchApp.fetch('https://api.openai.com/v1/chat/completions', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + openaiKey
                },
                payload: JSON.stringify({
                    model: 'gpt-4o-mini',
                    messages: [{ role: 'user', content: prompt }],
                    max_tokens: 500
                }),
                muteHttpExceptions: true
            });

            const result = JSON.parse(response.getContentText());
            if (result.choices && result.choices[0]) {
                enhancedCaption = result.choices[0].message.content;
            }
        }

        if (enhancedCaption) {
            return { success: true, enhancedCaption: enhancedCaption.trim(), method: claudeKey ? 'claude' : 'openai' };
        } else {
            // Fallback
            const hashtags = ' #TinySeedFarm #FarmFresh #LocalFood #Pittsburgh #FarmToTable';
            return { success: true, enhancedCaption: caption.trim() + '\n\n' + hashtags, method: 'fallback' };
        }
    } catch (error) {
        Logger.log('Error enhancing caption: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Check All API Status
 * Returns status of all integrated APIs
 */
function checkAllAPIStatus() {
    try {
        const props = PropertiesService.getScriptProperties();
        const statuses = {};

        // Check Instagram Graph API
        statuses.instagram = {
            name: 'Instagram Graph API',
            configured: !!props.getProperty('INSTAGRAM_ACCESS_TOKEN_0'),
            status: 'unknown'
        };

        if (props.getProperty('INSTAGRAM_ACCESS_TOKEN_0')) {
            try {
                const token = props.getProperty('INSTAGRAM_ACCESS_TOKEN_0');
                const response = UrlFetchApp.fetch(`https://graph.facebook.com/v18.0/me?access_token=${token}`, {
                    muteHttpExceptions: true
                });
                statuses.instagram.status = response.getResponseCode() === 200 ? 'connected' : 'error';
            } catch (e) {
                statuses.instagram.status = 'error';
            }
        }

        // Check Claude API
        statuses.claude = {
            name: 'Claude AI',
            configured: !!props.getProperty('CLAUDE_API_KEY'),
            status: props.getProperty('CLAUDE_API_KEY') ? 'configured' : 'not_configured'
        };

        // Check OpenAI API
        statuses.openai = {
            name: 'OpenAI',
            configured: !!props.getProperty('OPENAI_API_KEY'),
            status: props.getProperty('OPENAI_API_KEY') ? 'configured' : 'not_configured'
        };

        // Check Twilio
        statuses.twilio = {
            name: 'Twilio SMS',
            configured: !!props.getProperty('TWILIO_ACCOUNT_SID'),
            status: props.getProperty('TWILIO_ACCOUNT_SID') ? 'configured' : 'not_configured'
        };

        // Check Meta Ads API
        statuses.metaAds = {
            name: 'Meta Ads',
            configured: !!props.getProperty('META_ADS_ACCESS_TOKEN'),
            status: props.getProperty('META_ADS_ACCESS_TOKEN') ? 'configured' : 'not_configured'
        };

        // Check Shopify
        statuses.shopify = {
            name: 'Shopify',
            configured: !!props.getProperty('SHOPIFY_ACCESS_TOKEN'),
            status: props.getProperty('SHOPIFY_ACCESS_TOKEN') ? 'configured' : 'not_configured'
        };

        return { success: true, statuses: statuses };
    } catch (error) {
        Logger.log('Error checking API status: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Get Todd's Latest Writing Prompt Input
 * Retrieves the most recent response from Todd's writing prompts
 */
function getToddLatestInput() {
    try {
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let inputSheet = ss.getSheetByName('MARKETING_ToddInput');

        if (!inputSheet) {
            // Create the sheet if it doesn't exist
            inputSheet = ss.insertSheet('MARKETING_ToddInput');
            inputSheet.getRange(1, 1, 1, 5).setValues([[
                'Input_ID', 'Prompt', 'Response', 'Timestamp', 'Posts_Generated'
            ]]);
            inputSheet.setFrozenRows(1);
            return { success: true, input: null, message: 'No inputs yet - send Todd a writing prompt!' };
        }

        const data = inputSheet.getDataRange().getValues();
        if (data.length <= 1) {
            return { success: true, input: null, message: 'No inputs yet - send Todd a writing prompt!' };
        }

        // Get the most recent input (last row)
        const headers = data[0];
        const lastRow = data[data.length - 1];

        const input = {
            id: lastRow[0],
            prompt: lastRow[1],
            response: lastRow[2],
            timestamp: lastRow[3],
            postsGenerated: lastRow[4] || 0
        };

        // Get generated posts if any
        let generatedPosts = [];
        const queueSheet = ss.getSheetByName('MARKETING_Queue');
        if (queueSheet) {
            const queueData = queueSheet.getDataRange().getValues();
            for (let i = 1; i < queueData.length; i++) {
                if (queueData[i][7] === input.id) { // AI_Source = input.id
                    generatedPosts.push({
                        platform: queueData[i][2],
                        content: queueData[i][3],
                        status: queueData[i][5]
                    });
                }
            }
        }

        return { success: true, input: input, generatedPosts: generatedPosts };
    } catch (error) {
        Logger.log('Error getting Todd input: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Generate Posts from Todd's Input
 * Creates social media posts from Todd's written response to a prompt
 */
function generateFromToddInput(params) {
    try {
        const inputId = params.inputId;
        const inputText = params.inputText || '';
        const platforms = params.platforms || ['instagram', 'facebook'];

        if (!inputText.trim()) {
            return { success: false, error: 'No input text provided' };
        }

        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let queueSheet = ss.getSheetByName('MARKETING_Queue');
        if (!queueSheet) {
            queueSheet = ss.insertSheet('MARKETING_Queue');
            queueSheet.getRange(1, 1, 1, 9).setValues([[
                'Queue_ID', 'Scheduled_Date', 'Platform', 'Content', 'Content_Type', 'Status', 'Created_At', 'AI_Generated', 'AI_Source'
            ]]);
            queueSheet.setFrozenRows(1);
        }

        // Get AI key
        const props = PropertiesService.getScriptProperties();
        const claudeKey = props.getProperty('CLAUDE_API_KEY');
        const openaiKey = props.getProperty('OPENAI_API_KEY');

        let generatedPosts = [];

        if (claudeKey || openaiKey) {
            const prompt = `You are the social media manager for Tiny Seed Farm, a small organic farm in Pittsburgh.

Todd (the farmer) just wrote this about what's happening on the farm:
"${inputText}"

Generate 3 different social media posts from this input:
1. An Instagram post (engaging, visual-focused, 150-250 characters, 3-5 hashtags)
2. A Facebook post (can be longer, conversational, community-focused)
3. A quick update post (short, punchy, under 100 characters)

Use Todd's authentic voice - warm, friendly, genuine. Don't be overly promotional.

Return as JSON array:
[{"platform":"instagram","content":"..."},{"platform":"facebook","content":"..."},{"platform":"twitter","content":"..."}]`;

            let response;
            if (claudeKey) {
                response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'x-api-key': claudeKey,
                        'anthropic-version': '2023-06-01'
                    },
                    payload: JSON.stringify({
                        model: 'claude-3-haiku-20240307',
                        max_tokens: 1000,
                        messages: [{ role: 'user', content: prompt }]
                    }),
                    muteHttpExceptions: true
                });

                const result = JSON.parse(response.getContentText());
                if (result.content && result.content[0]) {
                    const text = result.content[0].text;
                    const jsonMatch = text.match(/\[[\s\S]*\]/);
                    if (jsonMatch) {
                        generatedPosts = JSON.parse(jsonMatch[0]);
                    }
                }
            } else if (openaiKey) {
                response = UrlFetchApp.fetch('https://api.openai.com/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + openaiKey
                    },
                    payload: JSON.stringify({
                        model: 'gpt-4o-mini',
                        messages: [{ role: 'user', content: prompt }],
                        max_tokens: 1000
                    }),
                    muteHttpExceptions: true
                });

                const result = JSON.parse(response.getContentText());
                if (result.choices && result.choices[0]) {
                    const text = result.choices[0].message.content;
                    const jsonMatch = text.match(/\[[\s\S]*\]/);
                    if (jsonMatch) {
                        generatedPosts = JSON.parse(jsonMatch[0]);
                    }
                }
            }
        }

        // Fallback if AI didn't work
        if (generatedPosts.length === 0) {
            const shortVersion = inputText.length > 200 ? inputText.substring(0, 197) + '...' : inputText;
            generatedPosts = [
                { platform: 'instagram', content: shortVersion + '\n\n#TinySeedFarm #FarmFresh #Pittsburgh' },
                { platform: 'facebook', content: inputText }
            ];
        }

        // Save to queue
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        tomorrow.setHours(10, 0, 0, 0);

        let savedCount = 0;
        generatedPosts.forEach((post, i) => {
            if (platforms.includes(post.platform) || platforms.includes('all')) {
                const queueId = 'Q-' + Date.now() + '-' + i;
                const scheduleDate = new Date(tomorrow);
                scheduleDate.setDate(scheduleDate.getDate() + i);

                queueSheet.appendRow([
                    queueId,
                    scheduleDate.toISOString(),
                    post.platform,
                    post.content,
                    'original',
                    'draft',
                    new Date().toISOString(),
                    'true',
                    inputId || ''
                ]);
                savedCount++;
            }
        });

        // Update input record with posts generated count
        if (inputId) {
            const inputSheet = ss.getSheetByName('MARKETING_ToddInput');
            if (inputSheet) {
                const inputData = inputSheet.getDataRange().getValues();
                for (let i = 1; i < inputData.length; i++) {
                    if (inputData[i][0] === inputId) {
                        inputSheet.getRange(i + 1, 5).setValue((inputData[i][4] || 0) + savedCount);
                        break;
                    }
                }
            }
        }

        return { success: true, generated: savedCount, posts: generatedPosts };
    } catch (error) {
        Logger.log('Error generating from Todd input: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Mark Action Complete - Track completed actions
 *
 * Updated 2026-02-11: Now also updates unified task system
 *
 * Parameters:
 *   taskId - Unified task ID (if action was synced to unified system)
 *   actionType - Type of action (SALES_OPPORTUNITY, COMMENT_RESPONSE, etc.)
 *   actionId - Legacy action ID or comment ID
 *   details - Additional details
 *   completedBy - Who completed it (default: 'owner')
 *   result - Result of completion (default: 'completed')
 */
function markSocialActionComplete(params) {
    try {
        // If we have a unified taskId, update that first
        if (params.taskId && params.taskId.startsWith('UTASK_')) {
            const updateResult = updateUnifiedTask({
                taskId: params.taskId,
                status: 'completed',
                completedBy: params.completedBy || 'owner'
            });

            if (!updateResult.success) {
                Logger.log('Warning: Failed to update unified task: ' + updateResult.error);
            }
        }

        // Also log to legacy completed actions sheet for backward compatibility
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        let actionsSheet = ss.getSheetByName('SOCIAL_CompletedActions');
        if (!actionsSheet) {
            actionsSheet = ss.insertSheet('SOCIAL_CompletedActions');
            actionsSheet.getRange(1, 1, 1, 6).setValues([[
                'Timestamp', 'Action_Type', 'Action_ID', 'Details', 'Completed_By', 'Result'
            ]]);
            actionsSheet.setFrozenRows(1);
        }

        actionsSheet.appendRow([
            new Date().toISOString(),
            params.actionType || '',
            params.taskId || params.actionId || '',
            params.details || '',
            params.completedBy || 'owner',
            params.result || 'completed'
        ]);

        return { success: true, message: 'Action marked complete' };
    } catch (error) {
        return { success: false, error: error.toString() };
    }
}

/**
 * Get Trending Hashtags for Social Media
 * Returns relevant hashtags for farm/agriculture social media
 */
function getTrendingHashtags(params) {
    try {
        // Farm-focused trending hashtags - curated for organic farm content
        const seasonalHashtags = getSeasonalHashtags();
        const coreHashtags = [
            'farmfresh', 'localgrown', 'supportlocal', 'organicfarming',
            'farmtotable', 'freshveggies', 'csa', 'pittsburgh', 'pghfood',
            'sustainablefarming', 'smallfarm', 'farmlife', 'growyourown',
            'healthyeating', 'wholefood', 'vegetables', 'farmersmarket'
        ];

        // Combine seasonal and core hashtags
        const allHashtags = [...seasonalHashtags, ...coreHashtags];

        // Shuffle and return top 12
        const shuffled = allHashtags.sort(() => Math.random() - 0.5);

        return {
            success: true,
            hashtags: shuffled.slice(0, 12),
            timestamp: new Date().toISOString()
        };
    } catch (error) {
        return { success: false, error: error.toString() };
    }
}

function getSeasonalHashtags() {
    const month = new Date().getMonth();

    // Spring (March-May)
    if (month >= 2 && month <= 4) {
        return ['springplanting', 'seedstarting', 'springgreens', 'freshstart', 'springharvest'];
    }
    // Summer (June-August)
    else if (month >= 5 && month <= 7) {
        return ['summerharvest', 'tomatoseason', 'zucchini', 'farmersmarketseason', 'summerveggies'];
    }
    // Fall (September-November)
    else if (month >= 8 && month <= 10) {
        return ['fallharvest', 'pumpkinseason', 'rootvegetables', 'autumnfarm', 'preserving'];
    }
    // Winter (December-February)
    else {
        return ['wintergreens', 'seasonextension', 'coldframes', 'wintercsa', 'storagecrop'];
    }
}

/**
 * Get Content Ideas for Social Media
 * AI-powered or template-based content suggestions
 */
function getContentIdeas(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const apiKey = props.getProperty('OPENAI_API_KEY');

        const dayOfWeek = new Date().toLocaleDateString('en-US', { weekday: 'long' });
        const month = new Date().toLocaleDateString('en-US', { month: 'long' });

        // Try AI generation if available
        if (apiKey) {
            try {
                const response = UrlFetchApp.fetch('https://api.openai.com/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Authorization': 'Bearer ' + apiKey,
                        'Content-Type': 'application/json'
                    },
                    payload: JSON.stringify({
                        model: 'gpt-4o-mini',
                        messages: [
                            {
                                role: 'system',
                                content: 'You are a social media expert for a small organic farm in Pittsburgh. Generate 5 short content ideas (1 sentence each) for Instagram posts. Focus on engagement, authenticity, and seasonal relevance. No hashtags, just ideas.'
                            },
                            {
                                role: 'user',
                                content: `It's ${dayOfWeek} in ${month}. Give me 5 content ideas for today.`
                            }
                        ],
                        temperature: 0.9,
                        max_tokens: 300
                    }),
                    muteHttpExceptions: true
                });

                const result = JSON.parse(response.getContentText());
                if (result.choices && result.choices[0]) {
                    const ideasText = result.choices[0].message.content;
                    const ideas = ideasText.split('\n').filter(line => line.trim().length > 0).map(line =>
                        line.replace(/^\d+\.\s*/, '').trim()
                    );
                    return { success: true, ideas: ideas.slice(0, 5), source: 'ai' };
                }
            } catch (aiError) {
                Logger.log('AI content ideas failed, using templates: ' + aiError.toString());
            }
        }

        // Fallback to template-based ideas
        const templateIdeas = getTemplateContentIdeas(dayOfWeek, month);
        return { success: true, ideas: templateIdeas, source: 'template' };

    } catch (error) {
        return { success: false, error: error.toString() };
    }
}

function getTemplateContentIdeas(dayOfWeek, month) {
    const ideas = [
        'Share a behind-the-scenes look at morning harvest routine',
        'Post a "what\'s in the CSA box this week" preview',
        'Feature a customer testimonial or pickup day moment',
        'Show the journey of a vegetable from seed to harvest',
        'Share a quick tip for storing or preparing seasonal produce',
        'Post a farm team member spotlight',
        'Share what you\'re cooking with this week\'s harvest',
        'Show the sunrise or sunset view from the farm',
        'Feature a comparison: grocery store vs farm fresh',
        'Post about the insects or pollinators helping on the farm'
    ];

    // Return 5 random ideas
    return ideas.sort(() => Math.random() - 0.5).slice(0, 5);
}

/**
 * Send SMS Alert for Urgent Social Actions
 * Notifies owner when there are sales opportunities or crises
 */
function sendSocialBrainAlert(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        const ownerPhone = props.getProperty('OWNER_PHONE') || props.getProperty('ADMIN_PHONE');

        if (!ownerPhone) {
            Logger.log('No owner phone configured for social alerts');
            return { success: false, error: 'No owner phone configured' };
        }

        let message = '🧠 SOCIAL BRAIN ALERT\n\n';

        if (params.status === 'crisis') {
            message += '🚨 CRISIS DETECTED!\nNegative sentiment spike. All posts paused.\n\n';
        }

        if (params.urgentCount > 0) {
            message += `⚡ ${params.urgentCount} URGENT ACTION${params.urgentCount > 1 ? 'S' : ''}\n\n`;

            if (params.topUrgent) {
                if (params.topUrgent.type === 'SALES_OPPORTUNITY') {
                    message += `💰 SALES OPPORTUNITY:\n${params.topUrgent.action}\n\n`;
                } else if (params.topUrgent.type === 'COMPLAINT_RESPONSE') {
                    message += `⚠️ COMPLAINT NEEDS RESPONSE:\n${params.topUrgent.action}\n\n`;
                } else {
                    message += `📌 ${params.topUrgent.type}:\n${params.topUrgent.action}\n\n`;
                }
            }
        }

        message += 'Open Social Intelligence dashboard to respond.';

        return sendSMS({
            to: ownerPhone,
            message: message
        });
    } catch (error) {
        Logger.log('Error sending social brain alert: ' + error.toString());
        return { success: false, error: error.toString() };
    }
}

/**
 * Configure Owner Phone for Social Alerts
 */
function configureOwnerPhone(params) {
    try {
        const props = PropertiesService.getScriptProperties();
        props.setProperty('OWNER_PHONE', params.phone);
        return { success: true, message: 'Owner phone configured for social alerts' };
    } catch (error) {
        return { success: false, error: error.toString() };
    }
}

/**
 * Setup Daily Briefing Trigger
 * Call once to set up automatic morning briefing at 6 AM
 */
function setupDailyBriefingTrigger() {
    // Remove existing triggers
    const triggers = ScriptApp.getProjectTriggers();
    triggers.forEach(trigger => {
        if (trigger.getHandlerFunction() === 'generateDailyBriefing') {
            ScriptApp.deleteTrigger(trigger);
        }
    });

    // Create new trigger for 6 AM daily
    ScriptApp.newTrigger('generateDailyBriefing')
        .timeBased()
        .atHour(6)
        .everyDays(1)
        .inTimezone('America/New_York')
        .create();

    return { success: true, message: 'Daily briefing trigger set for 6 AM EST' };
}

