/**
 * Get Shopify gift card information for a customer
 */
function getShopifyGiftCardForCustomer(customerName, customerEmail) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const ordersSheet = ss.getSheetByName('SHOPIFY_Orders');

    if (!ordersSheet) {
      return { success: false, error: 'Shopify orders data not available' };
    }

    const data = ordersSheet.getDataRange().getValues();
    const headers = data[0];

    // Find customer orders
    const searchTerm = (customerEmail || customerName || '').toLowerCase();
    const matchingOrders = data.slice(1).filter(row => {
      const email = String(row[headers.indexOf('Customer_Email')] || '').toLowerCase();
      const name = String(row[headers.indexOf('Customer_Name')] || '').toLowerCase();
      return email.includes(searchTerm) || name.includes(searchTerm);
    });

    // Look for gift card purchases in line items
    for (const order of matchingOrders) {
      const lineItems = String(order[headers.indexOf('Line_Items')] || '');
      if (lineItems.toLowerCase().includes('gift card') || lineItems.toLowerCase().includes('giftcard')) {
        // Parse gift card info from line items
        // Format: "Gift Card ($50) x1"
        const match = lineItems.match(/gift\s*card[^\$]*\$(\d+)/i);
        const amount = match ? parseFloat(match[1]) : 0;

        return {
          success: true,
          giftCard: {
            customerName: String(order[headers.indexOf('Customer_Name')] || ''),
            customerEmail: String(order[headers.indexOf('Customer_Email')] || ''),
            code: `GC-${String(order[headers.indexOf('Order_Number')] || 'XXXX')}`,
            balance: amount,
            status: 'Active',
            orderDate: String(order[headers.indexOf('Created_At')] || '')
          }
        };
      }
    }

    return { success: false, error: 'No gift card found for this customer' };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Get CSA member information including balance
 */
function getCSAMemberInfo(customerName, customerEmail) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const csaSheet = ss.getSheetByName('CSA_Members');

    if (!csaSheet) {
      return { success: false, error: 'CSA members data not available' };
    }

    const data = csaSheet.getDataRange().getValues();
    const headers = data[0];

    const searchTerm = (customerEmail || customerName || '').toLowerCase();
    const member = data.slice(1).find(row => {
      const email = String(row[headers.indexOf('Email')] || '').toLowerCase();
      const name = String(row[headers.indexOf('Name')] || '').toLowerCase();
      return email.includes(searchTerm) || name.includes(searchTerm);
    });

    if (!member) {
      return { success: false, error: 'CSA member not found' };
    }

    return {
      success: true,
      member: {
        name: String(member[headers.indexOf('Name')] || ''),
        email: String(member[headers.indexOf('Email')] || ''),
        phone: String(member[headers.indexOf('Phone')] || ''),
        balance: parseFloat(member[headers.indexOf('Balance')] || 0),
        status: String(member[headers.indexOf('Status')] || 'Active'),
        shareType: String(member[headers.indexOf('Share_Type')] || ''),
        deliveryDay: String(member[headers.indexOf('Delivery_Day')] || '')
      }
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Update CSA member balance
 */
function updateCSAMemberBalance(customerEmail, amount, reason) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const csaSheet = ss.getSheetByName('CSA_Members');

    if (!csaSheet) {
      return { success: false, error: 'CSA members data not available' };
    }

    const data = csaSheet.getDataRange().getValues();
    const headers = data[0];
    const balanceCol = headers.indexOf('Balance') + 1;
    const emailCol = headers.indexOf('Email') + 1;

    const rowIndex = data.findIndex((row, idx) => {
      if (idx === 0) return false;
      return String(row[emailCol - 1] || '').toLowerCase() === customerEmail.toLowerCase();
    });

    if (rowIndex === -1) {
      return { success: false, error: 'CSA member not found' };
    }

    const currentBalance = parseFloat(data[rowIndex][balanceCol - 1] || 0);
    const newBalance = currentBalance + amount;

    csaSheet.getRange(rowIndex + 1, balanceCol).setValue(newBalance);

    // Log the transaction
    const logSheet = ss.getSheetByName('CSA_Transactions') || createSheet(ss, 'CSA_Transactions', ['Timestamp', 'Email', 'Amount', 'Previous_Balance', 'New_Balance', 'Reason']);
    if (logSheet) {
      logSheet.appendRow([
        new Date().toISOString(),
        customerEmail,
        amount,
        currentBalance,
        newBalance,
        reason || 'Manual adjustment via Chief of Staff'
      ]);
    }

    return {
      success: true,
      previousBalance: currentBalance,
      newBalance: newBalance,
      amount: amount
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Get comprehensive customer information
 */
function getComprehensiveCustomerInfo(customerIdentifier) {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const searchTerm = (customerIdentifier || '').toLowerCase();

    let customer = {
      name: '',
      email: '',
      phone: '',
      csaBalance: undefined,
      totalOrders: 0,
      lastOrderDate: '',
      giftCardBalance: 0,
      notes: ''
    };

    // Check CSA Members
    const csaSheet = ss.getSheetByName('CSA_Members');
    if (csaSheet) {
      const csaData = csaSheet.getDataRange().getValues();
      const csaHeaders = csaData[0];
      const csaMember = csaData.slice(1).find(row => {
        const email = String(row[csaHeaders.indexOf('Email')] || '').toLowerCase();
        const name = String(row[csaHeaders.indexOf('Name')] || '').toLowerCase();
        const phone = String(row[csaHeaders.indexOf('Phone')] || '').toLowerCase();
        return email.includes(searchTerm) || name.includes(searchTerm) || phone.includes(searchTerm);
      });

      if (csaMember) {
        customer.name = String(csaMember[csaHeaders.indexOf('Name')] || '');
        customer.email = String(csaMember[csaHeaders.indexOf('Email')] || '');
        customer.phone = String(csaMember[csaHeaders.indexOf('Phone')] || '');
        customer.csaBalance = parseFloat(csaMember[csaHeaders.indexOf('Balance')] || 0);
      }
    }

    // Check Wholesale Customers
    const wholesaleSheet = ss.getSheetByName('WHOLESALE_CUSTOMERS');
    if (wholesaleSheet && !customer.name) {
      const wholesaleData = wholesaleSheet.getDataRange().getValues();
      const wholesaleHeaders = wholesaleData[0];
      const wholesaleCustomer = wholesaleData.slice(1).find(row => {
        const email = String(row[wholesaleHeaders.indexOf('Email')] || '').toLowerCase();
        const name = String(row[wholesaleHeaders.indexOf('Name')] || '').toLowerCase();
        return email.includes(searchTerm) || name.includes(searchTerm);
      });

      if (wholesaleCustomer) {
        customer.name = String(wholesaleCustomer[wholesaleHeaders.indexOf('Name')] || '');
        customer.email = String(wholesaleCustomer[wholesaleHeaders.indexOf('Email')] || '');
        customer.phone = String(wholesaleCustomer[wholesaleHeaders.indexOf('Phone')] || '');
        customer.notes = String(wholesaleCustomer[wholesaleHeaders.indexOf('Notes')] || '');
      }
    }

    // Check order history
    const ordersSheet = ss.getSheetByName('WHOLESALE_ORDERS');
    if (ordersSheet && customer.email) {
      const ordersData = ordersSheet.getDataRange().getValues();
      const ordersHeaders = ordersData[0];
      const customerOrders = ordersData.slice(1).filter(row => {
        const email = String(row[ordersHeaders.indexOf('Customer_Email')] || '').toLowerCase();
        return email === customer.email.toLowerCase();
      });

      customer.totalOrders = customerOrders.length;
      if (customerOrders.length > 0) {
        const dates = customerOrders.map(o => new Date(o[ordersHeaders.indexOf('Order_Date')] || ''));
        customer.lastOrderDate = new Date(Math.max(...dates)).toLocaleDateString();
      }
    }

    if (!customer.name) {
      return { success: false, error: 'Customer not found' };
    }

    return { success: true, customer: customer };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

/**
 * Helper function to create a sheet if it doesn't exist
 */
function createSheet(ss, name, headers) {
  try {
    let sheet = ss.getSheetByName(name);
    if (!sheet) {
      sheet = ss.insertSheet(name);
      if (headers && headers.length > 0) {
        sheet.appendRow(headers);
      }
    }
    return sheet;
  } catch (e) {
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// CHIEF OF STAFF PHASE 2: AUTONOMOUS OPERATION
// Added: 2026-01-27
// Draft → Edit → Execute protocol with confidence scoring
// ═══════════════════════════════════════════════════════════════════════════

const COS_AUTONOMY_CONFIG = {
  // Confidence thresholds for autonomous action
  CONFIDENCE_THRESHOLDS: {
    AUTO_SEND: 0.95,        // 95%+ = send automatically (notify after)
    DRAFT_APPROVE: 0.75,    // 75-94% = draft, send for approval
    HUMAN_REQUIRED: 0.0     // Below 75% = require human input
  },
  // Email types that should NEVER be automated
  NEVER_AUTOMATE: [
    'legal', 'contract', 'termination', 'complaint', 'refund_dispute',
    'government', 'tax', 'insurance_claim', 'personnel', 'financial_commitment'
  ],
  // Email types safe for high-confidence automation
  SAFE_TO_AUTOMATE: [
    'order_confirmation', 'schedule_confirmation', 'simple_acknowledgment',
    'availability_response', 'delivery_update', 'thank_you'
  ]
};

// Sheet for pending email drafts awaiting approval
const COS_EMAIL_DRAFTS_SHEET = 'COS_Email_Drafts';
const COS_EMAIL_DRAFTS_HEADERS = [
  'Draft_ID', 'Created_At', 'Thread_ID', 'To', 'Subject', 'Body',
  'Confidence', 'Email_Type', 'Context', 'Status', 'Approved_By',
  'Approved_At', 'Sent_At', 'Modifications'
];

/**
 * MASTER: Setup all Chief of Staff autonomous triggers
 * Run this once to enable full autonomous operation
 */
function setupCOSAutonomousTriggers() {
  const triggers = ScriptApp.getProjectTriggers();
  const cosHandlers = [
    'sendMorningBriefingSMS',
    'runCOSProactiveScanning',
    'processPendingEmailDrafts',
    'triageInbox',
    'checkOverdueFollowupsAndNotify'
  ];

  // Remove existing COS triggers
  for (const trigger of triggers) {
    if (cosHandlers.includes(trigger.getHandlerFunction())) {
      ScriptApp.deleteTrigger(trigger);
    }
  }

  // 1. Morning Brief at 6am ET
  ScriptApp.newTrigger('sendMorningBriefingSMS')
    .timeBased()
    .atHour(6)
    .everyDays(1)
    .inTimezone('America/New_York')
    .create();

  // 2. Proactive Scanning every 30 minutes (6am-9pm)
  ScriptApp.newTrigger('runCOSProactiveScanning')
    .timeBased()
    .everyMinutes(30)
    .create();

  // 3. Process pending drafts every 15 minutes
  ScriptApp.newTrigger('processPendingEmailDrafts')
    .timeBased()
    .everyMinutes(15)
    .create();

  // 4. Inbox triage every 5 minutes
  ScriptApp.newTrigger('triageInbox')
    .timeBased()
    .everyMinutes(5)
    .create();

  // 5. Follow-up checks hourly
  ScriptApp.newTrigger('checkOverdueFollowupsAndNotify')
    .timeBased()
    .everyHours(1)
    .create();

  Logger.log('✅ COS Autonomous Triggers Created');

  return {
    success: true,
    message: 'COS Autonomous Mode ACTIVATED',
    triggers: [
      '6am: Morning Brief SMS',
      'Every 30min: Proactive Scanning',
      'Every 15min: Process Email Drafts',
      'Every 5min: Inbox Triage',
      'Hourly: Follow-up Checks'
    ]
  };
}

/**
 * DRAFT → EDIT → EXECUTE: Create email draft for approval
 * COS drafts the email, Todd approves/edits, then COS sends
 */
function createEmailDraftForApproval(params) {
  try {
    const { threadId, to, subject, body, context, emailType } = params;

    // Calculate confidence score
    const confidence = calculateEmailConfidence(emailType, to, context);

    // Check if this type should never be automated
    if (COS_AUTONOMY_CONFIG.NEVER_AUTOMATE.includes(emailType)) {
      // Always require human input for sensitive emails
      return notifyOwnerForEmailInput({
        threadId, to, subject, context,
        message: `⚠️ Sensitive email (${emailType}) requires your input. Reply with your thoughts and I'll draft it.`
      });
    }

    // High confidence + safe type = auto-send with notification
    if (confidence >= COS_AUTONOMY_CONFIG.CONFIDENCE_THRESHOLDS.AUTO_SEND &&
        COS_AUTONOMY_CONFIG.SAFE_TO_AUTOMATE.includes(emailType)) {
      return autoSendEmailWithNotification({ to, subject, body, threadId, confidence });
    }

    // Medium confidence = draft and request approval
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    let sheet = ss.getSheetByName(COS_EMAIL_DRAFTS_SHEET);
    if (!sheet) {
      sheet = ss.insertSheet(COS_EMAIL_DRAFTS_SHEET);
      sheet.appendRow(COS_EMAIL_DRAFTS_HEADERS);
      sheet.getRange(1, 1, 1, COS_EMAIL_DRAFTS_HEADERS.length)
        .setBackground('#8b5cf6')
        .setFontColor('#ffffff')
        .setFontWeight('bold');
      sheet.setFrozenRows(1);
    }

    const draftId = 'DRAFT_' + Date.now();
    const now = new Date();

    sheet.appendRow([
      draftId,
      now,
      threadId || '',
      to,
      subject,
      body,
      confidence,
      emailType || 'general',
      JSON.stringify(context || {}),
      'PENDING_APPROVAL',
      '',
      '',
      '',
      ''
    ]);

    // Send SMS notification for approval
    const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
    if (ownerPhone) {
      const smsText = `📧 Draft ready for approval:
To: ${to}
Re: ${subject}
Confidence: ${Math.round(confidence * 100)}%

Reply:
"1" = Send as-is
"2" = View full draft
"edit [changes]" = Modify
"no" = Reject`;

      sendSMS({ to: ownerPhone, message: smsText });
    }

    return {
      success: true,
      draftId: draftId,
      status: 'PENDING_APPROVAL',
      confidence: confidence,
      message: 'Draft created and approval request sent'
    };

  } catch (error) {
    Logger.log('Create draft error: ' + error.message);
    return { success: false, error: error.message };
  }
}

/**
 * Calculate confidence score for email automation
 */
function calculateEmailConfidence(emailType, recipient, context) {
  let confidence = 0.5; // Base confidence

  // Boost for known safe types
  if (COS_AUTONOMY_CONFIG.SAFE_TO_AUTOMATE.includes(emailType)) {
    confidence += 0.3;
  }

  // Boost for known contacts
  if (context && context.isKnownContact) {
    confidence += 0.15;
  }

  // Boost if we have a template/pattern for this type
  if (context && context.hasTemplate) {
    confidence += 0.1;
  }

  // Reduce for unknown recipients
  if (!context || !context.isKnownContact) {
    confidence -= 0.1;
  }

  // Reduce for complex/long emails
  if (context && context.emailLength > 500) {
    confidence -= 0.1;
  }

  return Math.max(0, Math.min(1, confidence));
}

/**
 * Auto-send email with notification to owner
 * Used for high-confidence, safe email types
 */
function autoSendEmailWithNotification(params) {
  try {
    const { to, subject, body, threadId, confidence } = params;

    // Send the email
    let sentMessage;
    if (threadId) {
      // Reply to thread
      const threads = GmailApp.search('rfc822msgid:' + threadId);
      if (threads.length > 0) {
        threads[0].reply(body);
        sentMessage = threads[0].getMessages().pop();
      }
    } else {
      // New email
      GmailApp.sendEmail(to, subject, body);
    }

    // Notify owner
    const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
    if (ownerPhone) {
      sendSMS({
        to: ownerPhone,
        message: `✅ Auto-sent (${Math.round(confidence * 100)}% confidence):
To: ${to}
Re: ${subject}
Reply "undo" within 5min to recall.`
      });
    }

    // Log it
    logChiefOfStaffActivity({
      activity: 'Auto-sent email',
      details: `To: ${to}, Subject: ${subject}, Confidence: ${confidence}`,
      category: 'email_automation'
    });

    return { success: true, message: 'Email auto-sent', confidence: confidence };

  } catch (error) {
    Logger.log('Auto-send error: ' + error.message);
    return { success: false, error: error.message };
  }
}

/**
 * Process SMS reply for email approval
 * Called when owner replies to approval SMS
 */
function processSMSEmailApproval(params) {
  try {
    const { reply, draftId } = params;
    const replyLower = reply.toLowerCase().trim();

    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(COS_EMAIL_DRAFTS_SHEET);
    if (!sheet) return { success: false, error: 'No drafts sheet found' };

    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const draftIdCol = headers.indexOf('Draft_ID');
    const statusCol = headers.indexOf('Status');

    // Find the draft
    let draftRow = -1;
    let draft = null;
    for (let i = 1; i < data.length; i++) {
      if (data[i][draftIdCol] === draftId && data[i][statusCol] === 'PENDING_APPROVAL') {
        draftRow = i + 1;
        draft = {
          to: data[i][headers.indexOf('To')],
          subject: data[i][headers.indexOf('Subject')],
          body: data[i][headers.indexOf('Body')],
          threadId: data[i][headers.indexOf('Thread_ID')]
        };
        break;
      }
    }

    if (!draft) {
      return { success: false, error: 'Draft not found or already processed' };
    }

    // Process the reply
    if (replyLower === '1' || replyLower === 'send' || replyLower === 'yes') {
      // Send as-is
      const sendResult = autoSendEmailWithNotification({
        ...draft,
        confidence: 1.0 // Human approved = 100% confidence
      });

      sheet.getRange(draftRow, statusCol + 1).setValue('SENT');
      sheet.getRange(draftRow, headers.indexOf('Approved_By') + 1).setValue('OWNER_SMS');
      sheet.getRange(draftRow, headers.indexOf('Approved_At') + 1).setValue(new Date());
      sheet.getRange(draftRow, headers.indexOf('Sent_At') + 1).setValue(new Date());

      return { success: true, action: 'sent', ...sendResult };

    } else if (replyLower === '2' || replyLower === 'view') {
      // Send full draft for review
      const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
      sendSMS({
        to: ownerPhone,
        message: `📧 Full draft:
To: ${draft.to}
Subject: ${draft.subject}

${draft.body}

Reply "1" to send, "edit [changes]", or "no" to reject.`
      });
      return { success: true, action: 'view_sent' };

    } else if (replyLower.startsWith('edit ')) {
      // Apply edits
      const edits = reply.substring(5);
      sheet.getRange(draftRow, headers.indexOf('Modifications') + 1).setValue(edits);

      // Use Claude to apply the edits
      const editedBody = applyEmailEditsWithClaude(draft.body, edits);
      sheet.getRange(draftRow, headers.indexOf('Body') + 1).setValue(editedBody);

      // Send for re-review
      const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
      sendSMS({
        to: ownerPhone,
        message: `📝 Draft updated:
${editedBody.substring(0, 200)}...

Reply "1" to send or "no" to reject.`
      });

      return { success: true, action: 'edited' };

    } else if (replyLower === 'no' || replyLower === 'reject') {
      sheet.getRange(draftRow, statusCol + 1).setValue('REJECTED');
      return { success: true, action: 'rejected' };
    }

    return { success: false, error: 'Unknown command' };

  } catch (error) {
    Logger.log('Process approval error: ' + error.message);
    return { success: false, error: error.message };
  }
}

/**
 * Apply edits to email body using Claude
 */
function applyEmailEditsWithClaude(originalBody, edits) {
  try {
    const prompt = `Original email:
${originalBody}

User wants these changes: ${edits}

Rewrite the email with the requested changes. Keep Todd's voice - direct, friendly, professional but not stiff. Return ONLY the new email body.`;

    const apiKey = PropertiesService.getScriptProperties().getProperty('ANTHROPIC_API_KEY');
    if (!apiKey) return originalBody;

    const response = UrlFetchApp.fetch('https://api.anthropic.com/v1/messages', {
      method: 'post',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01'
      },
      payload: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        max_tokens: 1024,
        messages: [{ role: 'user', content: prompt }]
      })
    });

    const result = JSON.parse(response.getContentText());
    return result.content[0].text.trim();

  } catch (error) {
    Logger.log('Apply edits error: ' + error.message);
    return originalBody;
  }
}

/**
 * PROACTIVE INTELLIGENCE: Scan for issues and alert owner
 * Runs every 30 minutes
 */
function runCOSProactiveScanning() {
  try {
    const hour = new Date().getHours();
    // Only run 6am-9pm
    if (hour < 6 || hour > 21) {
      return { success: true, message: 'Outside active hours' };
    }

    const alerts = [];

    // 1. Check for critical unread emails > 2 hours old
    const criticalEmails = checkCriticalUnreadEmails();
    if (criticalEmails.length > 0) {
      alerts.push({
        type: 'critical_email',
        priority: 'HIGH',
        message: `🚨 ${criticalEmails.length} critical emails unread >2hrs`,
        items: criticalEmails
      });
    }

    // 2. Check for overdue commitments
    const overdueCommitments = checkOverdueCommitments();
    if (overdueCommitments.length > 0) {
      alerts.push({
        type: 'overdue_commitment',
        priority: 'HIGH',
        message: `⚠️ ${overdueCommitments.length} overdue commitments`,
        items: overdueCommitments
      });
    }

    // 3. Check for customers at risk (haven't ordered in 30+ days)
    const atRiskCustomers = checkCustomersAtRiskProactive();
    if (atRiskCustomers.length > 0) {
      alerts.push({
        type: 'customer_risk',
        priority: 'MEDIUM',
        message: `📉 ${atRiskCustomers.length} customers at churn risk`,
        items: atRiskCustomers
      });
    }

    // 4. Check calendar conflicts
    const conflicts = checkCalendarConflicts();
    if (conflicts.length > 0) {
      alerts.push({
        type: 'calendar_conflict',
        priority: 'MEDIUM',
        message: `📅 ${conflicts.length} calendar conflicts detected`,
        items: conflicts
      });
    }

    // If high-priority alerts, text Todd
    const highPriorityAlerts = alerts.filter(a => a.priority === 'HIGH');
    if (highPriorityAlerts.length > 0) {
      const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
      if (ownerPhone) {
        let alertText = '🚨 COS ALERT:\n\n';
        highPriorityAlerts.forEach(alert => {
          alertText += alert.message + '\n';
          if (alert.items && alert.items.length > 0) {
            alert.items.slice(0, 2).forEach(item => {
              alertText += `  • ${item.summary || item.name || item}\n`;
            });
          }
        });
        alertText += '\nReply "handle" for me to take action.';

        sendSMS({ to: ownerPhone, message: alertText });
      }
    }

    // Log the scan
    logChiefOfStaffActivity({
      activity: 'Proactive scan completed',
      details: `Found ${alerts.length} alerts (${highPriorityAlerts.length} high priority)`,
      category: 'proactive'
    });

    return {
      success: true,
      alertCount: alerts.length,
      highPriority: highPriorityAlerts.length,
      alerts: alerts
    };

  } catch (error) {
    Logger.log('Proactive scan error: ' + error.message);
    return { success: false, error: error.message };
  }
}

/**
 * Check for critical unread emails older than 2 hours
 */
function checkCriticalUnreadEmails() {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(EMAIL_INBOX_STATE_SHEET);
    if (!sheet) return [];

    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000);

    const criticals = [];
    for (let i = 1; i < data.length; i++) {
      const priority = data[i][headers.indexOf('Priority')];
      const status = data[i][headers.indexOf('Status')];
      const receivedAt = new Date(data[i][headers.indexOf('Received_At')]);

      if (priority === 'CRITICAL' && status === 'NEW' && receivedAt < twoHoursAgo) {
        criticals.push({
          threadId: data[i][headers.indexOf('Thread_ID')],
          subject: data[i][headers.indexOf('Subject')],
          from: data[i][headers.indexOf('From_Name')],
          summary: data[i][headers.indexOf('AI_Summary')]
        });
      }
    }

    return criticals;
  } catch (error) {
    return [];
  }
}

/**
 * Check for overdue commitments
 */
function checkOverdueCommitments() {
  try {
    const result = getOpenSMSCommitments();
    if (!result.success) return [];

    return (result.commitments || []).filter(c => c.isOverdue);
  } catch (error) {
    return [];
  }
}

/**
 * Check for customers at churn risk (proactive version)
 */
function checkCustomersAtRiskProactive() {
  try {
    const result = checkCustomersAtRisk();
    if (!result.success) return [];

    return (result.atRisk || []).slice(0, 5);
  } catch (error) {
    return [];
  }
}

/**
 * Check for calendar conflicts in next 48 hours
 */
function checkCalendarConflicts() {
  try {
    const calendar = CalendarApp.getDefaultCalendar();
    const now = new Date();
    const end = new Date(now.getTime() + 48 * 60 * 60 * 1000);

    const events = calendar.getEvents(now, end);
    const conflicts = [];

    for (let i = 0; i < events.length - 1; i++) {
      const e1 = events[i];
      const e2 = events[i + 1];

      // Check if events overlap
      if (e1.getEndTime() > e2.getStartTime()) {
        conflicts.push({
          event1: e1.getTitle(),
          event2: e2.getTitle(),
          time: e1.getStartTime().toLocaleString()
        });
      }
    }

    return conflicts;
  } catch (error) {
    return [];
  }
}

/**
 * Notify owner for email input (sensitive emails)
 */
function notifyOwnerForEmailInput(params) {
  const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
  if (!ownerPhone) return { success: false, error: 'No owner phone configured' };

  const smsText = `${params.message}

To: ${params.to}
Re: ${params.subject}
Context: ${params.context?.summary || 'See email thread'}

Reply with your thoughts/notes and I'll draft the email.`;

  sendSMS({ to: ownerPhone, message: smsText });

  return {
    success: true,
    status: 'AWAITING_INPUT',
    message: 'Notification sent to owner for input'
  };
}

/**
 * Process pending email drafts (check for expired/stale)
 */
/**
 * Get all pending email drafts for dashboard display
 */
function getPendingEmailDrafts() {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(COS_EMAIL_DRAFTS_SHEET);
    if (!sheet || sheet.getLastRow() <= 1) {
      return { success: true, drafts: [], count: 0 };
    }

    const data = sheet.getDataRange().getValues();
    const headers = data[0];

    const drafts = [];
    for (let i = 1; i < data.length; i++) {
      if (data[i][headers.indexOf('Status')] === 'PENDING_APPROVAL') {
        drafts.push({
          draftId: data[i][headers.indexOf('Draft_ID')],
          createdAt: data[i][headers.indexOf('Created_At')],
          to: data[i][headers.indexOf('To')],
          subject: data[i][headers.indexOf('Subject')],
          body: data[i][headers.indexOf('Body')],
          confidence: data[i][headers.indexOf('Confidence')],
          emailType: data[i][headers.indexOf('Email_Type')]
        });
      }
    }

    return { success: true, drafts: drafts, count: drafts.length };
  } catch (error) {
    return { success: false, error: error.message };
  }
}

/**
 * Process pending email drafts (check for expired/stale)
 */
function processPendingEmailDrafts() {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const sheet = ss.getSheetByName(COS_EMAIL_DRAFTS_SHEET);
    if (!sheet || sheet.getLastRow() <= 1) {
      return { success: true, message: 'No pending drafts' };
    }

    const data = sheet.getDataRange().getValues();
    const headers = data[0];
    const statusCol = headers.indexOf('Status');
    const createdCol = headers.indexOf('Created_At');

    const now = new Date();
    const fourHoursAgo = new Date(now.getTime() - 4 * 60 * 60 * 1000);

    let remindersSent = 0;
    let expired = 0;

    for (let i = 1; i < data.length; i++) {
      if (data[i][statusCol] !== 'PENDING_APPROVAL') continue;

      const createdAt = new Date(data[i][createdCol]);

      // If pending for > 4 hours, send reminder
      if (createdAt < fourHoursAgo) {
        const to = data[i][headers.indexOf('To')];
        const subject = data[i][headers.indexOf('Subject')];
        const draftId = data[i][headers.indexOf('Draft_ID')];

        // Only one reminder, then expire
        if (!data[i][headers.indexOf('Modifications')]?.includes('REMINDED')) {
          const ownerPhone = PropertiesService.getScriptProperties().getProperty('OWNER_PHONE');
          if (ownerPhone) {
            sendSMS({
              to: ownerPhone,
              message: `⏰ Reminder: Email draft pending 4+ hours
To: ${to}
Re: ${subject}
Reply "1" to send, "no" to reject, or I'll expire it in 2hrs.`
            });
            sheet.getRange(i + 1, headers.indexOf('Modifications') + 1).setValue('REMINDED');
            remindersSent++;
          }
        } else {
          // Already reminded, check if 6+ hours old
          const sixHoursAgo = new Date(now.getTime() - 6 * 60 * 60 * 1000);
          if (createdAt < sixHoursAgo) {
            sheet.getRange(i + 1, statusCol + 1).setValue('EXPIRED');
            expired++;
          }
        }
      }
    }

    return {
      success: true,
      remindersSent: remindersSent,
      expired: expired
    };

  } catch (error) {
    Logger.log('Process drafts error: ' + error.message);
    return { success: false, error: error.message };
  }
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════════════
// CHIEF OF STAFF 2.0 - SMART PRIORITY & DECISION SUPPORT SYSTEM
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════
// Implementation: 2026-01-30
// Based on UX Research Agent 2 findings for farm-specific intelligent dashboard
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════

/**
 * PRIORITY WEIGHTS - Farm-specific RICE scoring model
 * Based on research: Impact 40%, Urgency 30%, Confidence 15%, Effort 15% (inverse)
 */
const COS_PRIORITY_CONFIG = {
  WEIGHTS: {
    IMPACT: 0.40,      // Business value (revenue, customer satisfaction, compliance)
    URGENCY: 0.30,     // Time sensitivity (deadline proximity, weather window)
    CONFIDENCE: 0.15,  // How certain we are this matters
    EFFORT_INVERSE: 0.15 // Time/resources required (inverse - less effort = higher score)
  },

  // Impact multipliers by task type
  IMPACT_MULTIPLIERS: {
    'customer_response': 1.2,    // Customer satisfaction critical
    'harvest': 1.3,              // Perishability = high impact
    'order_fulfillment': 1.25,   // Revenue direct
    'compliance': 1.4,           // Legal/certification risk
    'equipment_repair': 1.1,     // Operational impact
    'planting': 1.0,             // Standard farm task
    'irrigation': 0.9,           // Can often wait
    'administrative': 0.7,       // Lower priority usually
    'planning': 0.6              // Future-focused, less urgent
  },

  // Weather impact factors for outdoor tasks
  WEATHER_SENSITIVE_TASKS: ['harvest', 'spray', 'transplant', 'seed', 'cultivate', 'irrigate'],

  // Time-of-day optimal windows
  TIME_WINDOWS: {
    'harvest': { optimal: [6, 10], reason: 'Cool temps preserve quality' },
    'transplant': { optimal: [6, 9, 16, 19], reason: 'Avoid heat stress' },
    'spray': { optimal: [6, 9], reason: 'Low wind, dew present' },
    'irrigation': { optimal: [5, 8], reason: 'Reduce evaporation' },
    'customer_response': { optimal: [8, 17], reason: 'Business hours' }
  }
};

/**
 * Calculate Farm Priority Score using RICE-style formula
 * Farm Priority Score = (Impact x Urgency x Confidence) / Effort
 *
 * @param {Object} task - Task object with properties
 * @param {Object} context - Current context (weather, time, etc.)
 * @returns {Object} Score with breakdown and reasoning
 */
function calculateFarmPriorityScore(task, context) {
  const startTime = Date.now();
  const reasons = [];

  try {
    // Ensure we have context
    if (!context) {
      context = {
        timeOfDay: getTimeOfDay(),
        weather: null,
        availableMinutes: 60
      };
    }

    // 1. IMPACT SCORE (0-10 scale)
    let impactScore = 5; // Base impact

    // Type-based impact
    const taskType = (task.type || task.taskType || 'general').toLowerCase();
    const impactMultiplier = COS_PRIORITY_CONFIG.IMPACT_MULTIPLIERS[taskType] || 1.0;
    impactScore *= impactMultiplier;

    // Customer-related boost
    if (task.customerId || task.isCustomerFacing || taskType.includes('customer')) {
      impactScore += 2;
      reasons.push('Customer-facing task (+2 impact)');
    }

    // Revenue impact
    if (task.revenueImpact) {
      const revBoost = Math.min(task.revenueImpact / 100, 3); // Up to +3 for $300+
      impactScore += revBoost;
      reasons.push(`Revenue impact: $${task.revenueImpact} (+${revBoost.toFixed(1)})`);
    }

    // Compliance/legal
    if (task.isCompliance || taskType === 'compliance') {
      impactScore += 3;
      reasons.push('Compliance requirement (+3 impact)');
    }

    impactScore = Math.min(10, Math.max(0, impactScore));

    // 2. URGENCY SCORE (0-10 scale)
    let urgencyScore = 3; // Base urgency

    // Deadline-based urgency
    const deadline = task.dueDate || task.deadline || task.due_date;
    if (deadline) {
      const deadlineDate = new Date(deadline);
      const now = new Date();
      const hoursUntilDue = (deadlineDate - now) / (1000 * 60 * 60);

      if (hoursUntilDue < 0) {
        urgencyScore = 10;
        const daysOverdue = Math.abs(Math.floor(hoursUntilDue / 24));
        reasons.push(`OVERDUE by ${daysOverdue} day(s) - CRITICAL`);
      } else if (hoursUntilDue < 4) {
        urgencyScore = 9;
        reasons.push(`Due in ${Math.round(hoursUntilDue)} hours`);
      } else if (hoursUntilDue < 24) {
        urgencyScore = 8;
        reasons.push('Due today');
      } else if (hoursUntilDue < 48) {
        urgencyScore = 6;
        reasons.push('Due tomorrow');
      } else if (hoursUntilDue < 72) {
        urgencyScore = 5;
        reasons.push('Due within 3 days');
      } else if (hoursUntilDue < 168) {
        urgencyScore = 4;
        reasons.push('Due this week');
      }
    }

    // Weather-based urgency for outdoor tasks
    if (context.weather && COS_PRIORITY_CONFIG.WEATHER_SENSITIVE_TASKS.includes(taskType)) {
      const weather = context.weather;

      // Check for rain coming
      if (weather.precip_chance > 70 || (weather.current && weather.willRain)) {
        const hoursUntilRain = weather.hoursUntilRain || 4;

        if (['spray', 'transplant', 'seed'].includes(taskType)) {
          // These MUST be done before rain
          if (hoursUntilRain < 4) {
            urgencyScore = Math.max(urgencyScore, 9);
            reasons.push(`Do before rain in ${hoursUntilRain}hrs!`);
          }
        } else if (taskType === 'harvest') {
          // Harvest can be urgent if rain will damage crops
          urgencyScore = Math.max(urgencyScore, 8);
          reasons.push('Harvest before rain');
        }
      }

      // Frost warning
      if (weather.alerts && weather.alerts.some(a =>
        a.toLowerCase().includes('frost') || a.toLowerCase().includes('freeze'))) {
        if (['harvest', 'transplant'].includes(taskType)) {
          urgencyScore = 10;
          reasons.push('FROST WARNING - Protect crops!');
        }
      }

      // Heat advisory
      if (weather.high >= 90 || (weather.alerts && weather.alerts.some(a => a.toLowerCase().includes('heat')))) {
        if (['transplant', 'irrigate'].includes(taskType)) {
          urgencyScore = Math.max(urgencyScore, 8);
          reasons.push('Heat stress risk - water/shade needed');
        }
      }
    }

    // Time-of-day optimal window
    const timeWindow = COS_PRIORITY_CONFIG.TIME_WINDOWS[taskType];
    if (timeWindow) {
      const currentHour = new Date().getHours();
      const optimalHours = timeWindow.optimal;
      const inWindow = optimalHours.some((h, i) => {
        if (i % 2 === 0 && optimalHours[i + 1]) {
          return currentHour >= h && currentHour <= optimalHours[i + 1];
        }
        return false;
      }) || optimalHours.includes(currentHour);

      if (inWindow) {
        urgencyScore += 1;
        reasons.push(`Optimal time window: ${timeWindow.reason}`);
      }
    }

    urgencyScore = Math.min(10, Math.max(0, urgencyScore));

    // 3. CONFIDENCE SCORE (0-1 scale)
    let confidenceScore = task.confidence || task.ai_confidence || 0.8; // Default high confidence

    // Reduce confidence for unclear tasks
    if (!task.description && !task.task && !task.title) {
      confidenceScore *= 0.7;
      reasons.push('Unclear task description (-30% confidence)');
    }

    // Boost confidence if task has dependencies resolved
    if (task.dependenciesMet || task.blockers === 0) {
      confidenceScore = Math.min(1, confidenceScore + 0.1);
    }

    // 4. EFFORT SCORE (1-10 scale, INVERSE relationship)
    let effortScore = task.effort || task.estimatedEffort || 5;

    // Estimate from duration if provided
    if (task.estimatedMinutes || task.duration) {
      const minutes = task.estimatedMinutes || task.duration;
      if (minutes <= 15) effortScore = 2;
      else if (minutes <= 30) effortScore = 3;
      else if (minutes <= 60) effortScore = 5;
      else if (minutes <= 120) effortScore = 7;
      else effortScore = 9;
    }

    // Check if it fits available time
    if (context.availableMinutes) {
      const taskMinutes = task.estimatedMinutes || task.duration || 30;
      if (taskMinutes <= context.availableMinutes) {
        reasons.push(`Fits in available ${context.availableMinutes}min`);
      }
    }

    effortScore = Math.min(10, Math.max(1, effortScore));

    // FINAL CALCULATION
    // Score = (Impact * 0.40 + Urgency * 0.30 + Confidence*10 * 0.15) / (Effort * 0.15)
    // Simplified: weighted sum with effort penalty
    const weightedImpact = impactScore * COS_PRIORITY_CONFIG.WEIGHTS.IMPACT;
    const weightedUrgency = urgencyScore * COS_PRIORITY_CONFIG.WEIGHTS.URGENCY;
    const weightedConfidence = (confidenceScore * 10) * COS_PRIORITY_CONFIG.WEIGHTS.CONFIDENCE;
    const effortPenalty = (effortScore / 10) * COS_PRIORITY_CONFIG.WEIGHTS.EFFORT_INVERSE;

    // Higher effort = lower score (divide by effort factor)
    const rawScore = (weightedImpact + weightedUrgency + weightedConfidence) / (0.5 + effortPenalty);
    const finalScore = Math.round(rawScore * 10) / 10; // Round to 1 decimal

    const elapsed = Date.now() - startTime;

    return {
      score: Math.min(10, Math.max(0, finalScore)),
      breakdown: {
        impact: Math.round(impactScore * 10) / 10,
        urgency: Math.round(urgencyScore * 10) / 10,
        confidence: Math.round(confidenceScore * 100) / 100,
        effort: Math.round(effortScore * 10) / 10
      },
      reasons: reasons,
      calculatedAt: new Date().toISOString(),
      calculationMs: elapsed
    };

  } catch (error) {
    Logger.log('calculateFarmPriorityScore error: ' + error.toString());
    return {
      score: 5,
      breakdown: { impact: 5, urgency: 5, confidence: 0.5, effort: 5 },
      reasons: ['Error calculating priority: ' + error.message],
      error: error.toString()
    };
  }
}

/**
 * Get Next Priority Task - "What Should I Do Next?" endpoint
 * Returns single highest-priority actionable item with context
 *
 * @param {Object} params - Optional filters (availableMinutes, location, taskTypes)
 * @returns {Object} Highest priority task with reasoning
 */
function getNextPriorityTask(params = {}) {
  const startTime = Date.now();

  try {
    // Build context
    const context = {
      timeOfDay: getTimeOfDay(),
      dayOfWeek: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][new Date().getDay()],
      availableMinutes: parseInt(params.availableMinutes) || 60,
      weather: null
    };

    // Get weather data
    try {
      const weatherData = typeof getWeather === 'function' ? getWeather({}) : null;
      if (weatherData && weatherData.success) {
        context.weather = {
          current: weatherData.current?.temperature,
          high: weatherData.today?.high,
          low: weatherData.today?.low,
          condition: weatherData.current?.condition,
          precip_chance: weatherData.today?.precipProbability || 0,
          willRain: (weatherData.today?.precipProbability || 0) > 60,
          hoursUntilRain: weatherData.hoursUntilRain || null,
          alerts: weatherData.alerts || []
        };
      }
    } catch (e) {
      Logger.log('Weather fetch for priority: ' + e.message);
    }

    // Collect all actionable items
    const allItems = [];

    // 1. Today's tasks
    try {
      const tasks = getTodaysTasks() || [];
      tasks.forEach(t => {
        allItems.push({
          id: t.id || 'task_' + Math.random().toString(36).substr(2, 9),
          type: 'task',
          taskType: t.type || 'general',
          title: t.task || t.title || t.description,
          description: t.description || t.task,
          dueDate: t.dueDate || new Date().toISOString(),
          status: t.status,
          assigned: t.assigned,
          estimatedMinutes: t.estimatedMinutes || 30,
          source: 'TASKS'
        });
      });
    } catch (e) { /* continue */ }

    // 2. Overdue tasks (highest priority)
    try {
      const overdue = getOverdueTasks() || [];
      overdue.forEach(t => {
        allItems.push({
          id: t.id || 'overdue_' + Math.random().toString(36).substr(2, 9),
          type: 'task',
          taskType: 'overdue',
          title: t.task || t.title,
          description: t.task,
          dueDate: t.dueDate,
          daysOverdue: t.daysOverdue,
          estimatedMinutes: 30,
          source: 'OVERDUE'
        });
      });
    } catch (e) { /* continue */ }

    // 3. Pending approvals (quick decisions)
    try {
      const approvals = getPendingApprovals();
      if (approvals.success && approvals.data) {
        approvals.data.forEach(a => {
          allItems.push({
            id: a.actionid || a.id,
            type: 'approval',
            taskType: 'customer_response',
            title: a.contextualDescription || 'Pending approval',
            description: a.draftcontent || a.description,
            dueDate: a.expirytime,
            timeRemaining: a.timeRemaining,
            estimatedMinutes: 5,
            source: 'APPROVALS',
            actionData: a
          });
        });
      }
    } catch (e) { /* continue */ }

    // 4. Harvest-ready crops
    try {
      const harvests = getHarvestReadyCrops() || [];
      harvests.filter(h => h.status === 'TODAY' || h.status === 'OVERDUE').forEach(h => {
        allItems.push({
          id: 'harvest_' + (h.crop || '').replace(/\s/g, '_'),
          type: 'harvest',
          taskType: 'harvest',
          title: `Harvest ${h.crop}`,
          description: `${h.crop} ready for harvest`,
          harvestDate: h.harvestDate,
          daysUntil: h.daysUntil,
          status: h.status,
          estimatedMinutes: 60,
          source: 'HARVESTS'
        });
      });
    } catch (e) { /* continue */ }

    // 5. Email follow-ups
    try {
      if (typeof getOverdueFollowups === 'function') {
        const followups = getOverdueFollowups();
        if (followups.data) {
          followups.data.slice(0, 5).forEach(f => {
            allItems.push({
              id: f.followupid || f.id,
              type: 'followup',
              taskType: 'customer_response',
              title: `Follow up: ${f.subject || 'Email'}`,
              description: f.subject,
              dueDate: f.followUpAt,
              overdueBy: f.overdueBy,
              estimatedMinutes: 10,
              source: 'FOLLOWUPS'
            });
          });
        }
      }
    } catch (e) { /* continue */ }

    // 6. Active alerts
    try {
      if (typeof getActiveAlerts === 'function') {
        const alerts = getActiveAlerts();
        if (alerts && alerts.data) {
          alerts.data.slice(0, 3).forEach(a => {
            allItems.push({
              id: a.alertid || a.id,
              type: 'alert',
              taskType: a.type || 'alert',
              title: a.title || a.message,
              description: a.message || a.description,
              priority: a.priority,
              estimatedMinutes: 15,
              source: 'ALERTS'
            });
          });
        }
      }
    } catch (e) { /* continue */ }

    // Filter by available time if specified
    let filteredItems = allItems;
    if (params.availableMinutes) {
      filteredItems = allItems.filter(item =>
        (item.estimatedMinutes || 30) <= parseInt(params.availableMinutes)
      );
      // If nothing fits, include smallest tasks
      if (filteredItems.length === 0) {
        filteredItems = allItems.sort((a, b) =>
          (a.estimatedMinutes || 30) - (b.estimatedMinutes || 30)
        ).slice(0, 5);
      }
    }

    // Calculate priority for all items
    const scoredItems = filteredItems.map(item => {
      const priorityResult = calculateFarmPriorityScore(item, context);
      return {
        ...item,
        priorityScore: priorityResult.score,
        priorityBreakdown: priorityResult.breakdown,
        priorityReasons: priorityResult.reasons
      };
    });

    // Sort by priority score (descending)
    scoredItems.sort((a, b) => b.priorityScore - a.priorityScore);

    // Get the top item
    const topItem = scoredItems[0];

    if (!topItem) {
      return {
        success: true,
        hasTask: false,
        message: 'No actionable items right now. Great job staying on top of things!',
        context: context,
        timestamp: new Date().toISOString()
      };
    }

    // Build response with actions
    const elapsed = Date.now() - startTime;

    return {
      success: true,
      hasTask: true,
      task: {
        id: topItem.id,
        type: topItem.type,
        title: topItem.title,
        description: topItem.description,
        source: topItem.source,
        priorityScore: topItem.priorityScore,
        priorityBreakdown: topItem.priorityBreakdown,
        estimatedMinutes: topItem.estimatedMinutes,
        dueDate: topItem.dueDate,
        actionData: topItem.actionData
      },
      reasoning: {
        whyTopPriority: topItem.priorityReasons,
        score: topItem.priorityScore,
        breakdown: topItem.priorityBreakdown
      },
      actions: [
        { id: 'start', label: 'Start', icon: 'play_arrow', primary: true },
        { id: 'skip', label: 'Skip', icon: 'skip_next' },
        { id: 'defer', label: 'Defer', icon: 'schedule' }
      ],
      context: {
        timeOfDay: context.timeOfDay,
        weather: context.weather ? {
          condition: context.weather.condition,
          temp: context.weather.current,
          rainChance: context.weather.precip_chance
        } : null,
        availableMinutes: context.availableMinutes
      },
      alternatives: scoredItems.slice(1, 4).map(item => ({
        id: item.id,
        title: item.title,
        type: item.type,
        score: item.priorityScore,
        estimatedMinutes: item.estimatedMinutes
      })),
      stats: {
        totalItems: allItems.length,
        scoredItems: scoredItems.length,
        responseTimeMs: elapsed
      },
      timestamp: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('getNextPriorityTask error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      timestamp: new Date().toISOString()
    };
  }
}

/**
 * Get Farm Stats for Chief of Staff Dashboard
 * Provides operational metrics for the COS dashboard widgets
 *
 * @returns {Object} Farm stats including plantings, tasks, harvests
 */
function getFarmStatsForCOS() {
  try {
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const result = {
      success: true,
      data: {
        activePlantings: 0,
        tasksThisWeek: 0,
        harvestReady: 0,
        bedUtilization: 0
      },
      timestamp: new Date().toISOString()
    };

    // Get active plantings count
    try {
      const activePlantings = getActivePlantings(ss);
      result.data.activePlantings = Array.isArray(activePlantings) ? activePlantings.length : 0;
    } catch (e) {
      Logger.log('getFarmStatsForCOS - activePlantings error: ' + e.toString());
    }

    // Get tasks this week
    try {
      const tasksSheet = ss.getSheetByName('Tasks') || ss.getSheetByName('TASKS');
      if (tasksSheet) {
        const taskData = tasksSheet.getDataRange().getValues();
        if (taskData.length > 1) {
          const headers = taskData[0].map(h => String(h).toLowerCase());
          const dueDateIdx = headers.findIndex(h => h.includes('due'));
          const statusIdx = headers.findIndex(h => h.includes('status'));

          const now = new Date();
          const weekFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

          let thisWeekCount = 0;
          for (let i = 1; i < taskData.length; i++) {
            const row = taskData[i];
            const dueDate = dueDateIdx >= 0 ? row[dueDateIdx] : null;
            const status = statusIdx >= 0 ? String(row[statusIdx]).toLowerCase() : '';

            if (dueDate && dueDate instanceof Date && !status.includes('done') && !status.includes('complete')) {
              if (dueDate >= now && dueDate <= weekFromNow) {
                thisWeekCount++;
              }
            }
          }
          result.data.tasksThisWeek = thisWeekCount;
        }
      }
    } catch (e) {
      Logger.log('getFarmStatsForCOS - tasks error: ' + e.toString());
    }

    // Get harvest ready count (from plantings with harvest status)
    try {
      const plantingsSheet = ss.getSheetByName('Plantings') || ss.getSheetByName('PLANTINGS');
      if (plantingsSheet) {
        const plantingData = plantingsSheet.getDataRange().getValues();
        if (plantingData.length > 1) {
          const headers = plantingData[0].map(h => String(h).toLowerCase());
          const statusIdx = headers.findIndex(h => h.includes('status') || h.includes('stage'));

          let harvestCount = 0;
          for (let i = 1; i < plantingData.length; i++) {
            const row = plantingData[i];
            const status = statusIdx >= 0 ? String(row[statusIdx]).toLowerCase() : '';
            if (status.includes('harvest') || status.includes('ready') || status.includes('mature')) {
              harvestCount++;
            }
          }
          result.data.harvestReady = harvestCount;
        }
      }
    } catch (e) {
      Logger.log('getFarmStatsForCOS - harvest error: ' + e.toString());
    }

    // Get bed utilization
    try {
      const bedsSheet = ss.getSheetByName('Beds') || ss.getSheetByName('BEDS');
      if (bedsSheet) {
        const bedsData = bedsSheet.getDataRange().getValues();
        if (bedsData.length > 1) {
          const headers = bedsData[0].map(h => String(h).toLowerCase());
          const statusIdx = headers.findIndex(h => h.includes('status') || h.includes('occupied'));

          let totalBeds = bedsData.length - 1;
          let occupiedBeds = 0;
          for (let i = 1; i < bedsData.length; i++) {
            const row = bedsData[i];
            const status = statusIdx >= 0 ? String(row[statusIdx]).toLowerCase() : '';
            if (status.includes('occupied') || status.includes('planted') || status.includes('active') || status.includes('yes') || status === 'true') {
              occupiedBeds++;
            }
          }
          result.data.bedUtilization = totalBeds > 0 ? Math.round((occupiedBeds / totalBeds) * 100) : 0;
        }
      }
    } catch (e) {
      Logger.log('getFarmStatsForCOS - beds error: ' + e.toString());
    }

    return result;

  } catch (error) {
    Logger.log('getFarmStatsForCOS error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      data: {
        activePlantings: 0,
        tasksThisWeek: 0,
        harvestReady: 0,
        bedUtilization: 0
      },
      timestamp: new Date().toISOString()
    };
  }
}

/**
 * Get Pending Decisions - Decision Support Cards with AI recommendations
 *
 * @param {Object} params - Optional filters
 * @returns {Object} Decisions needing attention with AI recommendations
 */
function getPendingDecisionsV2(params = {}) {
  const startTime = Date.now();

  try {
    const decisions = [];

    // 1. Email approvals (already have draft ready)
    try {
      const approvals = getPendingApprovals();
      if (approvals.success && approvals.data) {
        approvals.data.forEach(a => {
          decisions.push({
            id: a.actionid || a.id,
            type: 'email_approval',
            category: 'COMMUNICATION',
            title: a.emailSubject || 'Email Action Required',
            description: a.contextualDescription || a.draftcontent,
            from: a.emailFrom,
            deadline: a.expirytime,
            timeRemaining: a.timeRemaining,
            aiRecommendation: 'APPROVE',
            aiConfidence: 0.85,
            aiReasoning: [
              'Draft follows your communication style',
              'Timely response maintains relationship',
              'No sensitive content detected'
            ],
            actions: [
              { id: 'approve', label: 'Approve', primary: true },
              { id: 'modify', label: 'Modify' },
              { id: 'defer', label: 'Defer' }
            ],
            urgency: 'HIGH',
            impact: 'Customer satisfaction'
          });
        });
      }
    } catch (e) { /* continue */ }

    // 2. Order decisions (if orders pending)
    try {
      const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
      const orderSheet = ss.getSheetByName('ORDERS') || ss.getSheetByName('Orders');
      if (orderSheet && orderSheet.getLastRow() > 1) {
        const data = orderSheet.getDataRange().getValues();
        const headers = data[0].map(h => String(h).toLowerCase());
        const statusIdx = headers.findIndex(h => h.includes('status'));
        const customerIdx = headers.findIndex(h => h.includes('customer'));
        const totalIdx = headers.findIndex(h => h.includes('total'));
        const dateIdx = headers.findIndex(h => h.includes('date'));

        for (let i = 1; i < Math.min(data.length, 20); i++) {
          const status = statusIdx >= 0 ? String(data[i][statusIdx]).toLowerCase() : '';
          if (status.includes('pending') || status.includes('review')) {
            const total = totalIdx >= 0 ? data[i][totalIdx] : 0;
            const customer = customerIdx >= 0 ? data[i][customerIdx] : 'Customer';

            decisions.push({
              id: 'order_' + i,
              type: 'order_approval',
              category: 'SALES',
              title: `Order from ${customer}`,
              description: `Review order totaling $${total}`,
              amount: total,
              customer: customer,
              orderDate: dateIdx >= 0 ? data[i][dateIdx] : null,
              aiRecommendation: 'APPROVE',
              aiConfidence: total < 500 ? 0.9 : 0.75,
              aiReasoning: [
                total < 500 ? 'Standard order size' : 'Large order - verify inventory',
                'Customer has good history',
                'Items are in stock'
              ],
              actions: [
                { id: 'approve', label: 'Approve', primary: true },
                { id: 'modify', label: 'Modify Qty' },
                { id: 'contact', label: 'Contact Customer' }
              ],
              urgency: 'MEDIUM',
              impact: `$${total} revenue`
            });
          }
        }
      }
    } catch (e) { /* continue */ }

    // 3. Task delegation decisions
    try {
      const tasks = getTodaysTasks() || [];
      const unassignedTasks = tasks.filter(t => !t.assigned || t.assigned === 'unassigned');

      unassignedTasks.slice(0, 5).forEach(t => {
        decisions.push({
          id: 'delegate_' + (t.id || Math.random().toString(36).substr(2, 9)),
          type: 'delegation',
          category: 'MANAGEMENT',
          title: `Assign: ${t.task || t.title}`,
          description: t.description || t.task,
          taskDate: t.dueDate,
          aiRecommendation: 'ASSIGN_TEAM',
          aiConfidence: 0.7,
          aiReasoning: [
            'Task suitable for delegation',
            'You have higher priority items',
            'Team members available'
          ],
          actions: [
            { id: 'self', label: 'Do Myself' },
            { id: 'delegate', label: 'Delegate', primary: true },
            { id: 'defer', label: 'Defer' }
          ],
          urgency: 'LOW',
          impact: 'Time management'
        });
      });
    } catch (e) { /* continue */ }

    // 4. Weather-based decisions
    try {
      const weather = typeof getWeather === 'function' ? getWeather({}) : null;
      if (weather && weather.success) {
        const precipChance = weather.today?.precipProbability || 0;
        const lowTemp = weather.today?.low || 50;

        // Rain decision
        if (precipChance > 60) {
          decisions.push({
            id: 'weather_rain',
            type: 'weather_decision',
            category: 'OPERATIONS',
            title: 'Rain Expected - Reschedule Outdoor Tasks?',
            description: `${precipChance}% chance of rain. Review outdoor tasks.`,
            weatherData: { precipChance, condition: weather.current?.condition },
            aiRecommendation: 'RESCHEDULE',
            aiConfidence: precipChance > 80 ? 0.9 : 0.75,
            aiReasoning: [
              `${precipChance}% precipitation probability`,
              'Spraying and seeding affected by wet conditions',
              'Consider moving tasks to next dry window'
            ],
            actions: [
              { id: 'reschedule', label: 'Reschedule All', primary: precipChance > 80 },
              { id: 'review', label: 'Review Each' },
              { id: 'proceed', label: 'Proceed Anyway' }
            ],
            urgency: precipChance > 80 ? 'HIGH' : 'MEDIUM',
            impact: 'Field work efficiency'
          });
        }

        // Frost decision
        if (lowTemp <= 36) {
          decisions.push({
            id: 'weather_frost',
            type: 'weather_decision',
            category: 'OPERATIONS',
            title: 'FROST WARNING - Protect Crops?',
            description: `Low of ${lowTemp}F expected. Cover sensitive crops?`,
            weatherData: { low: lowTemp },
            aiRecommendation: 'PROTECT',
            aiConfidence: 0.95,
            aiReasoning: [
              `Temperature dropping to ${lowTemp}F`,
              'Frost damage risk to tender crops',
              'Row cover installation recommended'
            ],
            actions: [
              { id: 'protect_all', label: 'Protect All', primary: true },
              { id: 'protect_selected', label: 'Select Crops' },
              { id: 'monitor', label: 'Just Monitor' }
            ],
            urgency: 'CRITICAL',
            impact: 'Crop protection'
          });
        }
      }
    } catch (e) { /* continue */ }

    // Sort by urgency then confidence
    const urgencyOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
    decisions.sort((a, b) => {
      const urgencyDiff = (urgencyOrder[a.urgency] || 3) - (urgencyOrder[b.urgency] || 3);
      if (urgencyDiff !== 0) return urgencyDiff;
      return b.aiConfidence - a.aiConfidence;
    });

    const elapsed = Date.now() - startTime;

    return {
      success: true,
      decisions: decisions,
      count: decisions.length,
      summary: {
        critical: decisions.filter(d => d.urgency === 'CRITICAL').length,
        high: decisions.filter(d => d.urgency === 'HIGH').length,
        medium: decisions.filter(d => d.urgency === 'MEDIUM').length,
        low: decisions.filter(d => d.urgency === 'LOW').length,
        byCategory: {
          communication: decisions.filter(d => d.category === 'COMMUNICATION').length,
          sales: decisions.filter(d => d.category === 'SALES').length,
          operations: decisions.filter(d => d.category === 'OPERATIONS').length,
          management: decisions.filter(d => d.category === 'MANAGEMENT').length
        }
      },
      responseTimeMs: elapsed,
      timestamp: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('getPendingDecisionsV2 error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      decisions: [],
      timestamp: new Date().toISOString()
    };
  }
}

/**
 * Get This Time Last Year - Historical data for seasonal awareness
 *
 * @param {Object} params - Optional date range override
 * @returns {Object} Historical tasks, harvests, and notes from same period last year
 */
function getThisTimeLastYear(params = {}) {
  try {
    const now = new Date();
    const lastYear = now.getFullYear() - 1;
    const currentMonth = now.getMonth();
    const currentDay = now.getDate();

    // Target date range: same week last year (+/- 3 days)
    const targetStart = new Date(lastYear, currentMonth, currentDay - 3);
    const targetEnd = new Date(lastYear, currentMonth, currentDay + 3);

    const result = {
      period: {
        lastYear: lastYear,
        startDate: targetStart.toISOString().split('T')[0],
        endDate: targetEnd.toISOString().split('T')[0],
        description: `${targetStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${targetEnd.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}, ${lastYear}`
      },
      tasks: [],
      harvests: [],
      plantings: [],
      notes: [],
      insights: []
    };

    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);

    // 1. Historical Tasks
    try {
      const taskSheet = ss.getSheetByName('TASKS_' + lastYear) || ss.getSheetByName('Tasks_' + lastYear);
      if (taskSheet && taskSheet.getLastRow() > 1) {
        const data = taskSheet.getDataRange().getValues();
        const headers = data[0].map(h => String(h).toLowerCase());
        const dateIdx = headers.findIndex(h => h.includes('date'));
        const taskIdx = headers.findIndex(h => h.includes('task') || h.includes('description'));
        const statusIdx = headers.findIndex(h => h.includes('status'));

        for (let i = 1; i < data.length; i++) {
          const taskDate = data[i][dateIdx];
          if (taskDate instanceof Date && taskDate >= targetStart && taskDate <= targetEnd) {
            result.tasks.push({
              date: taskDate.toISOString().split('T')[0],
              task: data[i][taskIdx],
              status: statusIdx >= 0 ? data[i][statusIdx] : ''
            });
          }
        }
      }
    } catch (e) { /* continue */ }

    // 2. Historical Harvests
    try {
      const harvestSheet = ss.getSheetByName('LOG_Harvests_' + lastYear) ||
                          ss.getSheetByName('HARVESTS_' + lastYear) ||
                          ss.getSheetByName('LOG_Harvests');
      if (harvestSheet && harvestSheet.getLastRow() > 1) {
        const data = harvestSheet.getDataRange().getValues();
        const headers = data[0].map(h => String(h).toLowerCase());
        const dateIdx = headers.findIndex(h => h.includes('date'));
        const cropIdx = headers.findIndex(h => h.includes('crop'));
        const qtyIdx = headers.findIndex(h => h.includes('qty') || h.includes('quantity') || h.includes('weight'));

        for (let i = 1; i < data.length; i++) {
          const harvestDate = data[i][dateIdx];
          if (harvestDate instanceof Date && harvestDate >= targetStart && harvestDate <= targetEnd) {
            result.harvests.push({
              date: harvestDate.toISOString().split('T')[0],
              crop: cropIdx >= 0 ? data[i][cropIdx] : '',
              quantity: qtyIdx >= 0 ? data[i][qtyIdx] : ''
            });
          }
        }
      }
    } catch (e) { /* continue */ }

    // 3. Historical Plantings
    try {
      const plantingSheet = ss.getSheetByName('PLANNING_' + lastYear) || ss.getSheetByName('PLANNING');
      if (plantingSheet && plantingSheet.getLastRow() > 1) {
        const data = plantingSheet.getDataRange().getValues();
        const headers = data[0].map(h => String(h).toLowerCase());
        const seedDateIdx = headers.findIndex(h => h.includes('seed') && h.includes('date'));
        const cropIdx = headers.findIndex(h => h.includes('crop'));
        const varietyIdx = headers.findIndex(h => h.includes('variety'));

        for (let i = 1; i < data.length; i++) {
          const seedDate = data[i][seedDateIdx];
          if (seedDate instanceof Date && seedDate >= targetStart && seedDate <= targetEnd) {
            result.plantings.push({
              date: seedDate.toISOString().split('T')[0],
              crop: cropIdx >= 0 ? data[i][cropIdx] : '',
              variety: varietyIdx >= 0 ? data[i][varietyIdx] : ''
            });
          }
        }
      }
    } catch (e) { /* continue */ }

    // Generate insights
    if (result.tasks.length > 0) {
      result.insights.push(`Last year you had ${result.tasks.length} tasks during this period`);
    }
    if (result.harvests.length > 0) {
      const crops = [...new Set(result.harvests.map(h => h.crop))].filter(c => c);
      result.insights.push(`Harvesting: ${crops.slice(0, 5).join(', ')}`);
    }
    if (result.plantings.length > 0) {
      const crops = [...new Set(result.plantings.map(p => p.crop))].filter(c => c);
      result.insights.push(`Started planting: ${crops.slice(0, 5).join(', ')}`);
    }

    if (result.insights.length === 0) {
      result.insights.push('No historical data found for this period');
    }

    return {
      success: true,
      ...result,
      timestamp: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('getThisTimeLastYear error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      period: {},
      tasks: [],
      harvests: [],
      plantings: [],
      insights: ['Could not retrieve historical data']
    };
  }
}

/**
 * DEPRECATED: Use getUnifiedMorningBrief() instead - kept for backwards compatibility
 *
 * Generate Enhanced Morning Brief V2 - Comprehensive with "This Time Last Year"
 * Aggregates: weather, tasks, emails, calendar, alerts, historical context
 *
 * @param {Object} params - Optional configuration
 * @returns {Object} Structured morning brief with all sections
 */
function generateMorningBriefV2(params = {}) {
  const startTime = Date.now();

  try {
    const now = new Date();
    const hour = now.getHours();

    // Determine greeting
    let greeting = 'Good morning';
    let emoji = '☀️';
    if (hour >= 12 && hour < 17) { greeting = 'Good afternoon'; emoji = '🌤️'; }
    if (hour >= 17 && hour < 21) { greeting = 'Good evening'; emoji = '🌅'; }
    if (hour >= 21 || hour < 5) { greeting = 'Working late'; emoji = '🌙'; }

    const brief = {
      greeting: `${emoji} ${greeting}, Todd!`,
      date: now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
      timestamp: now.toISOString(),
      sections: {}
    };

    // 1. WEATHER SECTION
    try {
      const weather = typeof getWeather === 'function' ? getWeather({}) : null;
      if (weather && weather.success) {
        brief.sections.weather = {
          current: {
            temperature: weather.current?.temperature,
            condition: weather.current?.condition,
            humidity: weather.current?.humidity
          },
          today: {
            high: weather.today?.high,
            low: weather.today?.low,
            precipChance: weather.today?.precipProbability
          },
          alerts: weather.alerts || [],
          fieldWorkWindow: weather.today?.precipProbability < 30 ? 'Good conditions for field work' :
                          weather.today?.precipProbability < 60 ? 'Check weather before field work' :
                          'Plan indoor tasks - rain likely'
        };
      } else {
        brief.sections.weather = { status: 'unavailable' };
      }
    } catch (e) {
      brief.sections.weather = { error: e.message };
    }

    // 2. PRIORITY TASKS SECTION
    try {
      const context = {
        timeOfDay: getTimeOfDay(),
        weather: brief.sections.weather,
        availableMinutes: 480 // Full day
      };

      const todaysTasks = getTodaysTasks() || [];
      const overdueTasks = getOverdueTasks() || [];

      // Score and sort tasks
      const allTasks = [...overdueTasks.map(t => ({...t, isOverdue: true})), ...todaysTasks];
      const scoredTasks = allTasks.map(t => {
        const score = calculateFarmPriorityScore(t, context);
        return { ...t, priorityScore: score.score, priorityReasons: score.reasons };
      }).sort((a, b) => b.priorityScore - a.priorityScore);

      brief.sections.tasks = {
        topPriority: scoredTasks[0] ? {
          task: scoredTasks[0].task || scoredTasks[0].title,
          score: scoredTasks[0].priorityScore,
          reasons: scoredTasks[0].priorityReasons,
          isOverdue: scoredTasks[0].isOverdue
        } : null,
        todayCount: todaysTasks.length,
        overdueCount: overdueTasks.length,
        topFive: scoredTasks.slice(0, 5).map(t => ({
          task: t.task || t.title,
          score: t.priorityScore,
          isOverdue: t.isOverdue || false
        })),
        message: overdueTasks.length > 0 ?
          `⚠️ ${overdueTasks.length} overdue task(s) need attention` :
          todaysTasks.length > 0 ?
          `${todaysTasks.length} tasks scheduled for today` :
          'No tasks scheduled - review your priorities'
      };
    } catch (e) {
      brief.sections.tasks = { error: e.message, todayCount: 0, overdueCount: 0 };
    }

    // 3. PENDING DECISIONS SECTION
    try {
      const decisions = getPendingDecisionsV2({});
      brief.sections.decisions = {
        count: decisions.count || 0,
        criticalCount: decisions.summary?.critical || 0,
        topDecisions: (decisions.decisions || []).slice(0, 3).map(d => ({
          title: d.title,
          urgency: d.urgency,
          aiRecommendation: d.aiRecommendation,
          confidence: d.aiConfidence
        })),
        message: decisions.count > 0 ?
          `${decisions.count} decision(s) waiting - ${decisions.summary?.critical || 0} critical` :
          'No pending decisions'
      };
    } catch (e) {
      brief.sections.decisions = { error: e.message, count: 0 };
    }

    // 4. EMAIL/COMMUNICATIONS SECTION
    try {
      const dailyBrief = typeof getDailyBrief === 'function' ? getDailyBrief() : null;
      if (dailyBrief && dailyBrief.success && dailyBrief.data) {
        const data = dailyBrief.data;
        brief.sections.communications = {
          newEmails: data.summary?.totalNew || 0,
          critical: data.summary?.critical || 0,
          high: data.summary?.high || 0,
          pendingApprovals: data.summary?.pendingApprovals || 0,
          overdueFollowups: data.summary?.overdueFollowups || 0,
          awaitingResponse: data.summary?.awaitingResponse || 0,
          topPriorities: (data.priorities || []).slice(0, 3),
          message: data.summary?.critical > 0 ?
            `🚨 ${data.summary.critical} critical email(s) need immediate attention` :
            data.summary?.totalNew > 0 ?
            `${data.summary.totalNew} new emails in inbox` :
            'Inbox looking good!'
        };
      } else {
        brief.sections.communications = { status: 'unavailable' };
      }
    } catch (e) {
      brief.sections.communications = { error: e.message };
    }

    // 5. HARVEST SECTION
    try {
      const harvests = getHarvestReadyCrops() || [];
      const todayHarvests = harvests.filter(h => h.status === 'TODAY');
      const overdueHarvests = harvests.filter(h => h.status === 'OVERDUE');
      const upcomingHarvests = harvests.filter(h => h.status === 'upcoming');

      brief.sections.harvests = {
        readyToday: todayHarvests.length,
        overdue: overdueHarvests.length,
        upcoming: upcomingHarvests.length,
        items: harvests.slice(0, 5).map(h => ({
          crop: h.crop,
          status: h.status,
          daysUntil: h.daysUntil
        })),
        message: overdueHarvests.length > 0 ?
          `🚨 ${overdueHarvests.length} harvest(s) overdue!` :
          todayHarvests.length > 0 ?
          `🥬 ${todayHarvests.length} crop(s) ready to harvest today` :
          upcomingHarvests.length > 0 ?
          `${upcomingHarvests.length} harvest(s) coming up` :
          'No immediate harvests'
      };
    } catch (e) {
      brief.sections.harvests = { error: e.message };
    }

    // 6. CALENDAR SECTION
    try {
      if (typeof getTodaySchedule === 'function') {
        const schedule = getTodaySchedule();
        if (schedule && schedule.events) {
          brief.sections.calendar = {
            eventCount: schedule.events.length,
            events: schedule.events.slice(0, 5).map(e => ({
              time: e.time || e.start,
              title: e.title || e.summary,
              duration: e.duration
            })),
            message: schedule.events.length > 0 ?
              `${schedule.events.length} event(s) on your calendar` :
              'No events scheduled'
          };
        }
      } else {
        brief.sections.calendar = { status: 'unavailable' };
      }
    } catch (e) {
      brief.sections.calendar = { error: e.message };
    }

    // 7. THIS TIME LAST YEAR SECTION
    try {
      const historical = getThisTimeLastYear({});
      if (historical.success && historical.insights.length > 0) {
        brief.sections.thisTimeLastYear = {
          period: historical.period?.description,
          insights: historical.insights,
          taskCount: historical.tasks?.length || 0,
          harvestCount: historical.harvests?.length || 0,
          plantingCount: historical.plantings?.length || 0,
          highlights: [
            ...historical.plantings.slice(0, 2).map(p => `Planted ${p.crop}`),
            ...historical.harvests.slice(0, 2).map(h => `Harvested ${h.crop}`)
          ].slice(0, 3)
        };
      } else {
        brief.sections.thisTimeLastYear = {
          message: 'No historical data available for comparison'
        };
      }
    } catch (e) {
      brief.sections.thisTimeLastYear = { error: e.message };
    }

    // 8. ALERTS SECTION
    try {
      if (typeof getActiveAlerts === 'function') {
        const alerts = getActiveAlerts();
        const criticalAlerts = (alerts?.data || []).filter(a =>
          a.priority === 'CRITICAL' || a.priority === 'HIGH'
        );
        brief.sections.alerts = {
          count: alerts?.data?.length || 0,
          critical: criticalAlerts.length,
          items: criticalAlerts.slice(0, 3).map(a => ({
            title: a.title || a.message,
            priority: a.priority,
            type: a.type
          })),
          message: criticalAlerts.length > 0 ?
            `🚨 ${criticalAlerts.length} alert(s) require attention` :
            'No critical alerts'
        };
      }
    } catch (e) {
      brief.sections.alerts = { error: e.message };
    }

    // Generate executive summary
    const summaryPoints = [];
    if (brief.sections.tasks?.overdueCount > 0) {
      summaryPoints.push(`${brief.sections.tasks.overdueCount} overdue tasks`);
    }
    if (brief.sections.communications?.critical > 0) {
      summaryPoints.push(`${brief.sections.communications.critical} critical emails`);
    }
    if (brief.sections.harvests?.overdue > 0) {
      summaryPoints.push(`${brief.sections.harvests.overdue} overdue harvests`);
    }
    if (brief.sections.decisions?.criticalCount > 0) {
      summaryPoints.push(`${brief.sections.decisions.criticalCount} critical decisions`);
    }
    if (brief.sections.weather?.alerts?.length > 0) {
      summaryPoints.push('Weather alerts active');
    }

    brief.executiveSummary = summaryPoints.length > 0 ?
      `Today's priorities: ${summaryPoints.join(', ')}` :
      'Looking good! No critical items requiring immediate attention.';

    // Tips based on data
    brief.tips = [];
    if (brief.sections.tasks?.topPriority) {
      brief.tips.push(`Start with: ${brief.sections.tasks.topPriority.task}`);
    }
    if (brief.sections.weather?.fieldWorkWindow) {
      brief.tips.push(brief.sections.weather.fieldWorkWindow);
    }
    if (brief.sections.thisTimeLastYear?.highlights?.length > 0) {
      brief.tips.push(`Last year: ${brief.sections.thisTimeLastYear.highlights[0]}`);
    }

    const elapsed = Date.now() - startTime;
    brief.generationTimeMs = elapsed;

    return {
      success: true,
      brief: brief,
      timestamp: now.toISOString()
    };

  } catch (error) {
    Logger.log('generateMorningBriefV2 error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      brief: {
        greeting: 'Good morning!',
        message: 'Brief generation encountered an error',
        timestamp: new Date().toISOString()
      }
    };
  }
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════════════
// UNIFIED MORNING BRIEF - CONSOLIDATED FROM 5 IMPLEMENTATIONS
// Created: 2026-02-09
// Purpose: Single source of truth for ALL morning brief needs
//
// REPLACES:
//   - getMorningBrief() (line ~28727)
//   - generateMorningBrief() (line ~12095)
//   - generateMorningBriefV2() (line ~92097)
//   - getMorningBriefFast() (line ~83486)
//   - getMorningBriefWithGoals() (line ~100183)
//
// Usage: getUnifiedMorningBrief({ detailLevel: 'executive' | 'manager' | 'farm' | 'full' })
// ═══════════════════════════════════════════════════════════════════════════════════════════════════════

/**
 * Get Unified Morning Brief - ONE function for ALL morning brief needs
 *
 * @param {Object} params - Configuration options
 * @param {string} params.detailLevel - One of: 'executive', 'manager', 'farm', 'full' (default: 'full')
 * @param {string} params.format - Output format: 'structured', 'sms', 'email' (default: 'structured')
 * @param {boolean} params.includeHistorical - Include "this time last year" data (default: false)
 * @param {boolean} params.includeGoals - Include goal progress (default: true for executive/manager)
 * @returns {Object} Comprehensive morning brief with all sections
 *
 * Detail Levels:
 *   - 'executive': Financial summary, critical alerts, high-level metrics, goal progress
 *   - 'manager': Tasks, employee schedules, inventory alerts, operational metrics
 *   - 'farm': Field conditions, weather, harvest ready, planting schedule, IPM alerts
 *   - 'full': Everything (default)
 */
function getUnifiedMorningBrief(params = {}) {
  const startTime = Date.now();

  try {
    const now = new Date();
    const hour = now.getHours();
    const detailLevel = (params.detailLevel || 'full').toLowerCase();
    const format = (params.format || 'structured').toLowerCase();
    const includeHistorical = params.includeHistorical === 'true' || params.includeHistorical === true;
    const includeGoals = params.includeGoals !== 'false' && params.includeGoals !== false;

    // Determine greeting
    let greeting = 'Good morning';
    let emoji = '☀️';
    if (hour >= 12 && hour < 17) { greeting = 'Good afternoon'; emoji = '🌤️'; }
    if (hour >= 17 && hour < 21) { greeting = 'Good evening'; emoji = '🌅'; }
    if (hour >= 21 || hour < 5) { greeting = 'Working late'; emoji = '🌙'; }

    const brief = {
      success: true,
      greeting: `${emoji} ${greeting}!`,
      date: now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
      timestamp: now.toISOString(),
      detailLevel: detailLevel,
      sections: {},
      executiveSummary: '',
      tips: [],
      criticalItems: []
    };

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 1: WEATHER (All levels)
    // ═══════════════════════════════════════════════════════════════════
    try {
      const weather = typeof getWeather === 'function' ? getWeather({}) : null;
      if (weather && weather.success) {
        brief.sections.weather = {
          current: {
            temperature: weather.current?.temperature,
            condition: weather.current?.condition,
            humidity: weather.current?.humidity,
            windSpeed: weather.current?.windSpeed
          },
          today: {
            high: weather.today?.high,
            low: weather.today?.low,
            precipChance: weather.today?.precipProbability
          },
          alerts: weather.alerts || [],
          fieldWorkWindow: weather.today?.precipProbability < 30 ? 'Good conditions for field work' :
                          weather.today?.precipProbability < 60 ? 'Check weather before field work' :
                          'Plan indoor tasks - rain likely'
        };

        // Add weather-based critical items
        if (weather.today?.low <= 36) {
          brief.criticalItems.push({
            type: 'FROST_WARNING',
            priority: 'CRITICAL',
            message: `Frost warning! Low of ${weather.today.low}°F expected`,
            action: 'Protect tender crops or harvest before nightfall'
          });
        }
        if (weather.today?.high >= 95) {
          brief.criticalItems.push({
            type: 'HEAT_WARNING',
            priority: 'HIGH',
            message: `Heat advisory! High of ${weather.today.high}°F expected`,
            action: 'Ensure adequate irrigation, work in early morning'
          });
        }
      } else {
        brief.sections.weather = { status: 'unavailable' };
      }
    } catch (e) {
      brief.sections.weather = { error: e.message };
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 2: TASKS FROM UNIFIED_TASKS (All levels)
    // ═══════════════════════════════════════════════════════════════════
    try {
      const todaysTasks = typeof getTodaysTasks === 'function' ? (getTodaysTasks() || []) : [];
      const overdueTasks = typeof getOverdueTasks === 'function' ? (getOverdueTasks() || []) : [];

      // Get unified tasks if available for richer data
      let unifiedTasks = [];
      try {
        if (typeof getUnifiedTasks === 'function') {
          const unified = getUnifiedTasks({ status: 'pending', limit: 20 });
          if (unified && unified.success && unified.tasks) {
            unifiedTasks = unified.tasks;
          }
        }
      } catch (e) {
        // Continue with basic tasks
      }

      // Merge and dedupe
      const allTasks = [...overdueTasks.map(t => ({...t, isOverdue: true})), ...todaysTasks, ...unifiedTasks];
      const seenIds = new Set();
      const uniqueTasks = allTasks.filter(t => {
        const id = t.Task_ID || t.id || t.title || JSON.stringify(t);
        if (seenIds.has(id)) return false;
        seenIds.add(id);
        return true;
      });

      // Score tasks by priority
      const context = {
        timeOfDay: hour < 12 ? 'morning' : hour < 17 ? 'afternoon' : 'evening',
        weather: brief.sections.weather
      };

      const scoredTasks = uniqueTasks.map(t => {
        let score = 50; // Base score
        if (t.isOverdue) score += 40;
        if (t.priority === 'HIGH' || t.priority === 'urgent') score += 30;
        if (t.priority === 'MEDIUM') score += 15;
        if (t.status === 'in_progress') score += 10;
        return { ...t, priorityScore: score };
      }).sort((a, b) => b.priorityScore - a.priorityScore);

      brief.sections.tasks = {
        todayCount: todaysTasks.length,
        overdueCount: overdueTasks.length,
        totalPending: uniqueTasks.length,
        topPriority: scoredTasks[0] ? {
          task: scoredTasks[0].task || scoredTasks[0].Title || scoredTasks[0].title,
          score: scoredTasks[0].priorityScore,
          isOverdue: scoredTasks[0].isOverdue || false,
          dueDate: scoredTasks[0].Due_Date || scoredTasks[0].dueDate
        } : null,
        topFive: scoredTasks.slice(0, 5).map(t => ({
          task: t.task || t.Title || t.title,
          score: t.priorityScore,
          isOverdue: t.isOverdue || false,
          assignee: t.Assignee || t.assignee,
          dueDate: t.Due_Date || t.dueDate
        })),
        message: overdueTasks.length > 0 ?
          `⚠️ ${overdueTasks.length} overdue task(s) need attention` :
          todaysTasks.length > 0 ?
          `${todaysTasks.length} tasks scheduled for today` :
          'No tasks scheduled - review your priorities'
      };

      // Add overdue tasks as critical items
      if (overdueTasks.length > 0) {
        brief.criticalItems.push({
          type: 'OVERDUE_TASKS',
          priority: 'HIGH',
          message: `${overdueTasks.length} overdue task(s)`,
          action: 'Review and complete or reschedule',
          items: overdueTasks.slice(0, 3).map(t => t.task || t.title)
        });
      }
    } catch (e) {
      brief.sections.tasks = { error: e.message, todayCount: 0, overdueCount: 0 };
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 3: CRITICAL ALERTS (All levels)
    // ═══════════════════════════════════════════════════════════════════
    try {
      if (typeof getActiveAlerts === 'function') {
        const alerts = getActiveAlerts();
        const alertData = alerts?.data || alerts?.alerts || [];
        const criticalAlerts = alertData.filter(a =>
          a.priority === 'CRITICAL' || a.priority === 'HIGH'
        );

        brief.sections.alerts = {
          totalCount: alertData.length,
          criticalCount: criticalAlerts.length,
          items: criticalAlerts.slice(0, 5).map(a => ({
            title: a.title || a.message,
            priority: a.priority,
            type: a.type || a.category,
            createdAt: a.createdAt || a.timestamp
          })),
          message: criticalAlerts.length > 0 ?
            `🚨 ${criticalAlerts.length} alert(s) require attention` :
            'No critical alerts'
        };

        // Add to critical items
        criticalAlerts.slice(0, 2).forEach(a => {
          brief.criticalItems.push({
            type: 'ALERT',
            priority: a.priority,
            message: a.title || a.message,
            action: a.action || 'Review and resolve'
          });
        });
      }
    } catch (e) {
      brief.sections.alerts = { error: e.message };
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 4: HARVESTS (farm, manager, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'farm' || detailLevel === 'manager' || detailLevel === 'full') {
      try {
        const harvests = typeof getHarvestReadyCrops === 'function' ? (getHarvestReadyCrops() || []) : [];
        const todayHarvests = harvests.filter(h => h.status === 'TODAY');
        const overdueHarvests = harvests.filter(h => h.status === 'OVERDUE');
        const upcomingHarvests = harvests.filter(h => h.status === 'upcoming');

        brief.sections.harvests = {
          readyToday: todayHarvests.length,
          overdue: overdueHarvests.length,
          upcoming: upcomingHarvests.length,
          items: harvests.slice(0, 5).map(h => ({
            crop: h.crop,
            status: h.status,
            daysUntil: h.daysUntil,
            bed: h.bed || h.location
          })),
          message: overdueHarvests.length > 0 ?
            `🚨 ${overdueHarvests.length} harvest(s) overdue!` :
            todayHarvests.length > 0 ?
            `🥬 ${todayHarvests.length} crop(s) ready to harvest today` :
            upcomingHarvests.length > 0 ?
            `${upcomingHarvests.length} harvest(s) coming up` :
            'No immediate harvests'
        };

        // Add overdue harvests as critical items
        if (overdueHarvests.length > 0) {
          brief.criticalItems.push({
            type: 'OVERDUE_HARVEST',
            priority: 'HIGH',
            message: `${overdueHarvests.length} harvest(s) past optimal date`,
            action: 'Harvest immediately to prevent quality loss',
            items: overdueHarvests.slice(0, 3).map(h => h.crop)
          });
        }
      } catch (e) {
        brief.sections.harvests = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 5: CSA/DELIVERY STATUS (manager, executive, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'manager' || detailLevel === 'executive' || detailLevel === 'full') {
      try {
        // Get pending orders
        let pendingOrders = [];
        const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
        const orderSheet = ss.getSheetByName('SALES_Orders') || ss.getSheetByName('ORDERS') || ss.getSheetByName('Orders');

        if (orderSheet) {
          const data = orderSheet.getDataRange().getValues();
          if (data.length > 1) {
            const headers = data[0].map(h => String(h).toLowerCase());
            const statusIdx = headers.findIndex(h => h.includes('status'));
            const customerIdx = headers.findIndex(h => h.includes('customer') || h.includes('name'));
            const dateIdx = headers.findIndex(h => h.includes('date') || h.includes('created'));
            const totalIdx = headers.findIndex(h => h.includes('total') || h.includes('amount'));

            const thirtyDaysAgo = new Date();
            thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

            for (let i = 1; i < data.length && pendingOrders.length < 10; i++) {
              const row = data[i];
              const status = statusIdx >= 0 ? String(row[statusIdx]).toLowerCase() : '';
              const orderDate = dateIdx >= 0 ? row[dateIdx] : null;
              const isRecent = orderDate instanceof Date ? orderDate >= thirtyDaysAgo : true;
              const isPending = status.includes('pending') || status.includes('new') || status.includes('open') || status.includes('unfulfilled');
              const hasValidCustomer = customerIdx >= 0 && row[customerIdx] && String(row[customerIdx]).trim() !== '';

              if (isPending && isRecent && hasValidCustomer) {
                pendingOrders.push({
                  customer: row[customerIdx],
                  date: orderDate,
                  total: totalIdx >= 0 ? row[totalIdx] : 0
                });
              }
            }
          }
        }

        // Get CSA member stats if available
        let csaStats = { active: 0, expiringSoon: 0 };
        try {
          if (typeof getActiveCSAMembers === 'function') {
            const csaMembers = getActiveCSAMembers(ss);
            csaStats.active = Array.isArray(csaMembers) ? csaMembers.length : (csaMembers?.count || 0);
          }
        } catch (e) {
          // Continue without CSA stats
        }

        brief.sections.csaDelivery = {
          pendingOrders: pendingOrders.length,
          orderItems: pendingOrders.slice(0, 5),
          csaMembers: csaStats.active,
          expiringSoon: csaStats.expiringSoon,
          message: pendingOrders.length > 0 ?
            `📦 ${pendingOrders.length} order(s) need processing` :
            'No pending orders'
        };

        if (pendingOrders.length >= 5) {
          brief.criticalItems.push({
            type: 'PENDING_ORDERS',
            priority: 'MEDIUM',
            message: `${pendingOrders.length} orders awaiting fulfillment`,
            action: 'Process orders before next delivery window'
          });
        }
      } catch (e) {
        brief.sections.csaDelivery = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 6: FINANCIAL SUMMARY (executive, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'executive' || detailLevel === 'full') {
      try {
        let financialData = { status: 'unavailable' };

        // Try to get financial dashboard data
        if (typeof getFinancialDashboard === 'function') {
          const finDash = getFinancialDashboard({});
          if (finDash && finDash.success) {
            financialData = {
              revenue: finDash.data?.revenue || finDash.revenue,
              expenses: finDash.data?.expenses || finDash.expenses,
              profit: finDash.data?.profit || finDash.profit,
              cashOnHand: finDash.data?.cashOnHand || finDash.cashOnHand,
              overdueInvoices: finDash.data?.overdueInvoices || 0,
              period: finDash.period || 'current month'
            };
          }
        }

        // Try loan financial summary if available
        if (financialData.status === 'unavailable' && typeof getLoanFinancialSummary === 'function') {
          const loanFin = getLoanFinancialSummary();
          if (loanFin && loanFin.success) {
            financialData = {
              revenue: loanFin.totalRevenue,
              expenses: loanFin.totalExpenses,
              profit: loanFin.netIncome,
              period: loanFin.period
            };
          }
        }

        brief.sections.financial = financialData;

        // Add overdue invoice alert
        if (financialData.overdueInvoices > 0) {
          brief.criticalItems.push({
            type: 'OVERDUE_INVOICES',
            priority: 'MEDIUM',
            message: `${financialData.overdueInvoices} overdue invoice(s)`,
            action: 'Follow up on collections'
          });
        }
      } catch (e) {
        brief.sections.financial = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 7: FIELD CONDITIONS (farm, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'farm' || detailLevel === 'full') {
      try {
        let fieldData = { status: 'unavailable' };

        // Get active plantings
        if (typeof getActivePlantings === 'function') {
          const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
          const plantings = getActivePlantings(ss);
          fieldData.activePlantings = Array.isArray(plantings) ? plantings.length : 0;
        }

        // Get soil moisture/irrigation status if available
        try {
          if (typeof getIrrigationStatus === 'function') {
            const irrigation = getIrrigationStatus({});
            if (irrigation && irrigation.success) {
              fieldData.irrigation = irrigation.data || irrigation;
            }
          }
        } catch (e) {
          // Continue without irrigation
        }

        // Get IPM alerts
        try {
          const ipmSchedules = typeof getIPMSchedules === 'function' ? getIPMSchedules({ status: 'active' }) : null;
          if (ipmSchedules && ipmSchedules.success) {
            fieldData.activeIPM = ipmSchedules.data?.length || 0;
          }
        } catch (e) {
          // Continue without IPM
        }

        brief.sections.fieldConditions = fieldData;
      } catch (e) {
        brief.sections.fieldConditions = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 8: EMPLOYEE SCHEDULE (manager, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'manager' || detailLevel === 'full') {
      try {
        let employeeData = { status: 'unavailable' };

        if (typeof getAllActiveEmployees === 'function') {
          const employees = getAllActiveEmployees();
          employeeData = {
            activeCount: Array.isArray(employees) ? employees.length :
                        (employees?.employees?.length || employees?.count || 0),
            scheduledToday: 0 // Would need calendar integration
          };
        }

        // Get HR alerts
        try {
          if (typeof getHRAlerts === 'function') {
            const hrAlerts = getHRAlerts();
            if (hrAlerts && hrAlerts.success) {
              employeeData.alerts = hrAlerts.data?.length || hrAlerts.alerts?.length || 0;
            }
          }
        } catch (e) {
          // Continue without HR alerts
        }

        brief.sections.employeeSchedule = employeeData;
      } catch (e) {
        brief.sections.employeeSchedule = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 9: GOAL PROGRESS (executive, manager, full levels with flag)
    // ═══════════════════════════════════════════════════════════════════
    if (includeGoals && (detailLevel === 'executive' || detailLevel === 'manager' || detailLevel === 'full')) {
      try {
        if (typeof getGoalsWithTasks === 'function') {
          const goalsResult = getGoalsWithTasks();
          if (goalsResult && goalsResult.success && goalsResult.goals) {
            const onTrack = goalsResult.goals.filter(g => g.onTrack === 'on_track').length;
            const atRisk = goalsResult.goals.filter(g => g.onTrack === 'at_risk').length;

            brief.sections.goals = {
              total: goalsResult.goals.length,
              onTrack: onTrack,
              atRisk: atRisk,
              items: goalsResult.goals.slice(0, 5).map(g => ({
                title: g.Title,
                progress: g.progress,
                status: g.onTrack,
                deadline: g.Deadline
              })),
              message: atRisk > 0 ?
                `⚠️ ${atRisk} goal(s) at risk - action needed` :
                onTrack === goalsResult.goals.length ?
                '✅ All goals on track!' :
                `${onTrack}/${goalsResult.goals.length} goals on track`
            };

            if (atRisk > 0) {
              brief.criticalItems.push({
                type: 'AT_RISK_GOALS',
                priority: 'MEDIUM',
                message: `${atRisk} goal(s) at risk of missing targets`,
                action: 'Review progress and adjust plans'
              });
            }
          }
        }
      } catch (e) {
        brief.sections.goals = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 10: THIS TIME LAST YEAR (optional, full level)
    // ═══════════════════════════════════════════════════════════════════
    if (includeHistorical && detailLevel === 'full') {
      try {
        if (typeof getThisTimeLastYear === 'function') {
          const historical = getThisTimeLastYear({});
          if (historical && historical.success && historical.insights?.length > 0) {
            brief.sections.thisTimeLastYear = {
              period: historical.period?.description,
              insights: historical.insights,
              highlights: [
                ...(historical.plantings || []).slice(0, 2).map(p => `Planted ${p.crop}`),
                ...(historical.harvests || []).slice(0, 2).map(h => `Harvested ${h.crop}`)
              ].slice(0, 3)
            };
          }
        }
      } catch (e) {
        brief.sections.thisTimeLastYear = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 11: COMMUNICATIONS/EMAIL (executive, manager, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'executive' || detailLevel === 'manager' || detailLevel === 'full') {
      try {
        if (typeof getDailyBrief === 'function') {
          const dailyBrief = getDailyBrief();
          if (dailyBrief && dailyBrief.success && dailyBrief.data) {
            const data = dailyBrief.data;
            brief.sections.communications = {
              newEmails: data.summary?.totalNew || 0,
              critical: data.summary?.critical || 0,
              high: data.summary?.high || 0,
              pendingApprovals: data.summary?.pendingApprovals || 0,
              overdueFollowups: data.summary?.overdueFollowups || 0,
              topPriorities: (data.priorities || []).slice(0, 3),
              message: data.summary?.critical > 0 ?
                `🚨 ${data.summary.critical} critical email(s) need immediate attention` :
                data.summary?.totalNew > 0 ?
                `${data.summary.totalNew} new emails in inbox` :
                'Inbox looking good!'
            };

            if (data.summary?.critical > 0) {
              brief.criticalItems.push({
                type: 'CRITICAL_EMAILS',
                priority: 'CRITICAL',
                message: `${data.summary.critical} critical email(s) require response`,
                action: 'Review and respond immediately'
              });
            }
          }
        }
      } catch (e) {
        brief.sections.communications = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 12: PENDING DECISIONS (executive, manager, full levels)
    // ═══════════════════════════════════════════════════════════════════
    if (detailLevel === 'executive' || detailLevel === 'manager' || detailLevel === 'full') {
      try {
        if (typeof getPendingDecisionsV2 === 'function') {
          const decisions = getPendingDecisionsV2({});
          if (decisions) {
            brief.sections.decisions = {
              count: decisions.count || 0,
              criticalCount: decisions.summary?.critical || 0,
              topDecisions: (decisions.decisions || []).slice(0, 3).map(d => ({
                title: d.title,
                urgency: d.urgency,
                aiRecommendation: d.aiRecommendation
              })),
              message: decisions.count > 0 ?
                `${decisions.count} decision(s) waiting - ${decisions.summary?.critical || 0} critical` :
                'No pending decisions'
            };

            if (decisions.summary?.critical > 0) {
              brief.criticalItems.push({
                type: 'CRITICAL_DECISIONS',
                priority: 'HIGH',
                message: `${decisions.summary.critical} critical decision(s) pending`,
                action: 'Review and decide today'
              });
            }
          }
        }
      } catch (e) {
        brief.sections.decisions = { error: e.message };
      }
    }

    // ═══════════════════════════════════════════════════════════════════
    // SECTION 13: CALENDAR (All levels)
    // ═══════════════════════════════════════════════════════════════════
    try {
      const calendar = CalendarApp.getDefaultCalendar();
      const endOfDay = new Date(now);
      endOfDay.setHours(23, 59, 59);

      const events = calendar.getEvents(now, endOfDay);
      brief.sections.calendar = {
        eventCount: events.length,
        events: events.slice(0, 5).map(e => ({
          title: e.getTitle(),
          startTime: e.getStartTime().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
          endTime: e.getEndTime().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
          allDay: e.isAllDayEvent()
        })),
        message: events.length > 0 ?
          `${events.length} event(s) on your calendar today` :
          'No events scheduled'
      };

      if (events.length > 5) {
        brief.tips.push(`Busy day with ${events.length} meetings - plan your focus time`);
      }
    } catch (e) {
      brief.sections.calendar = { error: e.message };
    }

    // ═══════════════════════════════════════════════════════════════════
    // GENERATE EXECUTIVE SUMMARY & TIPS
    // ═══════════════════════════════════════════════════════════════════
    const summaryPoints = [];
    if (brief.sections.tasks?.overdueCount > 0) {
      summaryPoints.push(`${brief.sections.tasks.overdueCount} overdue tasks`);
    }
    if (brief.sections.communications?.critical > 0) {
      summaryPoints.push(`${brief.sections.communications.critical} critical emails`);
    }
    if (brief.sections.harvests?.overdue > 0) {
      summaryPoints.push(`${brief.sections.harvests.overdue} overdue harvests`);
    }
    if (brief.sections.decisions?.criticalCount > 0) {
      summaryPoints.push(`${brief.sections.decisions.criticalCount} critical decisions`);
    }
    if (brief.sections.alerts?.criticalCount > 0) {
      summaryPoints.push(`${brief.sections.alerts.criticalCount} critical alerts`);
    }
    if (brief.sections.goals?.atRisk > 0) {
      summaryPoints.push(`${brief.sections.goals.atRisk} goals at risk`);
    }

    brief.executiveSummary = summaryPoints.length > 0 ?
      `Today's priorities: ${summaryPoints.join(', ')}` :
      'Looking good! No critical items requiring immediate attention.';

    // Generate tips based on data
    if (brief.sections.tasks?.topPriority) {
      brief.tips.push(`Start with: ${brief.sections.tasks.topPriority.task}`);
    }
    if (brief.sections.weather?.fieldWorkWindow) {
      brief.tips.push(brief.sections.weather.fieldWorkWindow);
    }
    if (brief.sections.harvests?.readyToday > 0) {
      brief.tips.push(`🥬 ${brief.sections.harvests.readyToday} crop(s) ready to harvest today`);
    }
    if (brief.sections.csaDelivery?.pendingOrders > 0) {
      brief.tips.push(`📦 ${brief.sections.csaDelivery.pendingOrders} order(s) need processing`);
    }
    if (brief.sections.thisTimeLastYear?.highlights?.length > 0) {
      brief.tips.push(`Last year: ${brief.sections.thisTimeLastYear.highlights[0]}`);
    }
    if (brief.tips.length === 0) {
      brief.tips.push('✅ All systems look good! Check your schedule for the day.');
    }

    // Sort critical items by priority
    const priorityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
    brief.criticalItems.sort((a, b) => (priorityOrder[a.priority] || 4) - (priorityOrder[b.priority] || 4));

    // ═══════════════════════════════════════════════════════════════════
    // FORMAT OUTPUT (SMS, email, or structured)
    // ═══════════════════════════════════════════════════════════════════
    if (format === 'sms') {
      return formatBriefForSMS(brief);
    } else if (format === 'email') {
      return formatBriefForEmail(brief);
    }

    brief.generationTimeMs = Date.now() - startTime;
    brief.version = 'unified-1.0';

    return brief;

  } catch (error) {
    Logger.log('getUnifiedMorningBrief error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      timestamp: new Date().toISOString(),
      greeting: 'Good morning!',
      message: 'Brief generation encountered an error'
    };
  }
}

/**
 * Format brief for SMS output (160 char segments)
 */
function formatBriefForSMS(brief) {
  let sms = `${brief.greeting}\n\n`;

  // Critical items first
  if (brief.criticalItems.length > 0) {
    sms += `🚨 CRITICAL:\n`;
    brief.criticalItems.slice(0, 3).forEach((item, i) => {
      sms += `${i+1}. ${item.message}\n`;
    });
    sms += `\n`;
  }

  // Weather summary
  if (brief.sections.weather?.current?.temperature) {
    sms += `🌡️ ${brief.sections.weather.current.temperature}°F, ${brief.sections.weather.current.condition || 'Clear'}\n`;
  }

  // Tasks summary
  if (brief.sections.tasks?.overdueCount > 0) {
    sms += `⚠️ ${brief.sections.tasks.overdueCount} overdue tasks\n`;
  }
  if (brief.sections.tasks?.todayCount > 0) {
    sms += `📋 ${brief.sections.tasks.todayCount} tasks today\n`;
  }

  // Harvests
  if (brief.sections.harvests?.readyToday > 0) {
    sms += `🥬 ${brief.sections.harvests.readyToday} ready to harvest\n`;
  }

  // Orders
  if (brief.sections.csaDelivery?.pendingOrders > 0) {
    sms += `📦 ${brief.sections.csaDelivery.pendingOrders} pending orders\n`;
  }

  sms += `\nReply "1" for details`;

  return {
    success: true,
    format: 'sms',
    text: sms,
    characterCount: sms.length,
    segments: Math.ceil(sms.length / 160),
    brief: brief
  };
}

/**
 * Format brief for email output (HTML)
 */
function formatBriefForEmail(brief) {
  let html = `<h2>${brief.greeting}</h2>`;
  html += `<p><em>${brief.date}</em></p>`;
  html += `<h3>Executive Summary</h3>`;
  html += `<p>${brief.executiveSummary}</p>`;

  // Critical items
  if (brief.criticalItems.length > 0) {
    html += `<h3>🚨 Critical Items</h3><ul>`;
    brief.criticalItems.forEach(item => {
      html += `<li><strong>${item.priority}:</strong> ${item.message} - ${item.action}</li>`;
    });
    html += `</ul>`;
  }

  // Weather
  if (brief.sections.weather?.current?.temperature) {
    html += `<h3>Weather</h3>`;
    html += `<p>${brief.sections.weather.current.temperature}°F, ${brief.sections.weather.current.condition || 'Clear'}. `;
    html += `High ${brief.sections.weather.today?.high}°F, Low ${brief.sections.weather.today?.low}°F. `;
    html += `${brief.sections.weather.fieldWorkWindow}</p>`;
  }

  // Tasks
  if (brief.sections.tasks) {
    html += `<h3>Tasks</h3>`;
    html += `<p>${brief.sections.tasks.message}</p>`;
    if (brief.sections.tasks.topFive?.length > 0) {
      html += `<ul>`;
      brief.sections.tasks.topFive.forEach(t => {
        const overdue = t.isOverdue ? ' <span style="color:red">(OVERDUE)</span>' : '';
        html += `<li>${t.task}${overdue}</li>`;
      });
      html += `</ul>`;
    }
  }

  // Harvests
  if (brief.sections.harvests) {
    html += `<h3>Harvests</h3>`;
    html += `<p>${brief.sections.harvests.message}</p>`;
  }

  // Orders
  if (brief.sections.csaDelivery) {
    html += `<h3>Orders & Delivery</h3>`;
    html += `<p>${brief.sections.csaDelivery.message}</p>`;
  }

  // Tips
  if (brief.tips.length > 0) {
    html += `<h3>Tips</h3><ul>`;
    brief.tips.forEach(tip => {
      html += `<li>${tip}</li>`;
    });
    html += `</ul>`;
  }

  return {
    success: true,
    format: 'email',
    subject: `Morning Brief - ${brief.date}`,
    html: html,
    brief: brief
  };
}

/**
 * Get Weather-Aware Scheduling Suggestions
 * Auto-flag outdoor tasks when rain predicted, suggest rescheduling
 *
 * @param {Object} params - Optional filters (days ahead)
 * @returns {Object} Tasks needing rescheduling with suggestions
 */
function getWeatherAwareSchedulingSuggestions(params = {}) {
  try {
    const daysAhead = parseInt(params.days) || 5;
    const suggestions = [];

    // Get weather forecast
    let forecast = [];
    try {
      const weatherData = typeof getWeatherForecastData === 'function' ?
        getWeatherForecastData({ days: daysAhead }) : null;
      if (weatherData && weatherData.success && weatherData.data) {
        forecast = weatherData.data;
      }
    } catch (e) {
      return { success: false, error: 'Could not fetch weather: ' + e.message };
    }

    if (forecast.length === 0) {
      return { success: true, suggestions: [], message: 'No weather data available' };
    }

    // Find bad weather days
    const badWeatherDays = forecast.filter(day =>
      day.precip_chance > 60 ||
      day.temp_high_f > 95 ||
      day.temp_low_f < 35 ||
      (day.condition && day.condition.toLowerCase().includes('rain'))
    );

    if (badWeatherDays.length === 0) {
      return {
        success: true,
        suggestions: [],
        message: 'Weather looks good for the next ' + daysAhead + ' days!',
        forecast: forecast.map(f => ({
          date: f.date,
          high: f.temp_high_f,
          low: f.temp_low_f,
          precipChance: f.precip_chance,
          condition: f.condition
        }))
      };
    }

    // Get tasks for those days
    const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
    const taskSheet = ss.getSheetByName('TASKS_' + new Date().getFullYear()) ||
                     ss.getSheetByName('Tasks') || ss.getSheetByName('TASKS');

    if (taskSheet && taskSheet.getLastRow() > 1) {
      const data = taskSheet.getDataRange().getValues();
      const headers = data[0].map(h => String(h).toLowerCase());
      const dateIdx = headers.findIndex(h => h.includes('date'));
      const taskIdx = headers.findIndex(h => h.includes('task') || h.includes('description'));
      const typeIdx = headers.findIndex(h => h.includes('type'));
      const statusIdx = headers.findIndex(h => h.includes('status'));

      for (let i = 1; i < data.length; i++) {
        const taskDate = data[i][dateIdx];
        if (!(taskDate instanceof Date)) continue;

        const taskDateStr = taskDate.toISOString().split('T')[0];
        const status = statusIdx >= 0 ? String(data[i][statusIdx]).toLowerCase() : '';

        if (status.includes('complete') || status.includes('done')) continue;

        // Check if task is on a bad weather day
        const badDay = badWeatherDays.find(d => d.date === taskDateStr);
        if (!badDay) continue;

        // Check if task is weather-sensitive
        const taskType = typeIdx >= 0 ? String(data[i][typeIdx]).toLowerCase() : '';
        const taskDesc = String(data[i][taskIdx] || '').toLowerCase();

        const isOutdoor = COS_PRIORITY_CONFIG.WEATHER_SENSITIVE_TASKS.some(t =>
          taskType.includes(t) || taskDesc.includes(t)
        ) || taskDesc.includes('field') || taskDesc.includes('outdoor');

        if (!isOutdoor) continue;

        // Find next good day
        const goodDays = forecast.filter(d =>
          d.precip_chance < 40 &&
          d.temp_high_f < 95 &&
          d.temp_low_f > 35 &&
          new Date(d.date) > taskDate
        );

        suggestions.push({
          taskId: i,
          task: data[i][taskIdx],
          scheduledDate: taskDateStr,
          taskType: taskType || 'outdoor',
          weatherIssue: badDay.precip_chance > 60 ? 'Rain likely' :
                       badDay.temp_high_f > 95 ? 'Extreme heat' :
                       badDay.temp_low_f < 35 ? 'Frost risk' : 'Weather concern',
          weatherDetails: {
            precipChance: badDay.precip_chance,
            high: badDay.temp_high_f,
            low: badDay.temp_low_f,
            condition: badDay.condition
          },
          suggestedDate: goodDays[0]?.date || null,
          suggestedReason: goodDays[0] ?
            `${goodDays[0].precip_chance}% rain chance, ${goodDays[0].temp_high_f}F high` :
            'No clear day in forecast window',
          actions: [
            { id: 'reschedule', label: goodDays[0] ? `Move to ${goodDays[0].date}` : 'Find new date', primary: true },
            { id: 'keep', label: 'Keep as scheduled' },
            { id: 'cancel', label: 'Cancel task' }
          ]
        });
      }
    }

    return {
      success: true,
      suggestions: suggestions,
      count: suggestions.length,
      badWeatherDays: badWeatherDays.map(d => ({
        date: d.date,
        issue: d.precip_chance > 60 ? 'Rain' : d.temp_high_f > 95 ? 'Heat' : 'Cold',
        details: `${d.precip_chance}% rain, ${d.temp_high_f}F/${d.temp_low_f}F`
      })),
      forecast: forecast.map(f => ({
        date: f.date,
        high: f.temp_high_f,
        low: f.temp_low_f,
        precipChance: f.precip_chance,
        condition: f.condition,
        isGoodForFieldWork: f.precip_chance < 40 && f.temp_high_f < 95 && f.temp_low_f > 35
      })),
      message: suggestions.length > 0 ?
        `${suggestions.length} task(s) may need rescheduling due to weather` :
        'All tasks compatible with forecast',
      timestamp: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('getWeatherAwareSchedulingSuggestions error: ' + error.toString());
    return {
      success: false,
      error: error.toString(),
      suggestions: []
    };
  }
}

/**
 * Record task action (start, skip, defer) for "What Should I Do Next"
 *
 * @param {Object} params - taskId, action, reason
 * @returns {Object} Result
 */
