/**
 * Internal: Round to specified decimal places
 */
function roundToDecimal(num, decimals) {
  if (num === null || num === undefined || isNaN(num)) return 0;
  return Math.round(num * Math.pow(10, decimals)) / Math.pow(10, decimals);
}


