/**
 * Get Instagram follower counts for all configured accounts
 * Uses Meta Graph API directly with stored tokens
 */
function getInstagramFollowerCounts() {
  try {
    const props = PropertiesService.getScriptProperties();
    const accounts = JSON.parse(props.getProperty('instagram_accounts') || '[]');

    if (accounts.length === 0) {
      return { success: false, error: 'No Instagram accounts configured' };
    }

    const results = [];
    const errors = [];

    for (let i = 0; i < accounts.length; i++) {
      const account = accounts[i];
      const accessToken = props.getProperty(`ig_token_${i}`);

      if (!accessToken) {
        errors.push({ account: account.name, error: 'No access token' });
        continue;
      }

      if (!account.igUserId) {
        errors.push({ account: account.name, error: 'No Instagram User ID' });
        continue;
      }

      try {
        // Use correct base URL based on token type (matches postToInstagram logic)
        const baseUrl = accessToken.startsWith('IGAA') ? 'https://graph.instagram.com' : 'https://graph.facebook.com/v24.0';
        const url = `${baseUrl}/${account.igUserId}?fields=id,username,followers_count,media_count,profile_picture_url&access_token=${accessToken}`;
        const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
        const data = JSON.parse(response.getContentText());

        if (data.error) {
          errors.push({
            account: account.name,
            error: data.error.message,
            code: data.error.code
          });
        } else {
          results.push({
            index: i,
            name: account.name,
            handle: data.username || account.name,
            followers: data.followers_count || 0,
            posts: data.media_count || 0,
            profilePic: data.profile_picture_url || null
          });
        }
      } catch (apiError) {
        errors.push({ account: account.name, error: apiError.toString() });
      }
    }

    return {
      success: true,
      accounts: results,
      errors: errors.length > 0 ? errors : undefined,
      totalAccounts: accounts.length,
      fetchedAt: new Date().toISOString()
    };
  } catch (error) {
    Logger.log('Error getting Instagram follower counts: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Get Instagram post history for voice learning
 * Fetches recent posts with captions from all configured accounts
 * Used by the "Learn My Voice" feature in Marketing Command Center
 */
function getInstagramPostHistory(params) {
  try {
    const props = PropertiesService.getScriptProperties();
    const accounts = JSON.parse(props.getProperty('instagram_accounts') || '[]');
    const limit = params.limit || 25; // Posts per account

    if (accounts.length === 0) {
      return { success: false, error: 'No Instagram accounts configured' };
    }

    // Map account index to normalized names expected by frontend
    const accountNameMap = ['farm', 'fleurs', 'fungi'];

    const allPosts = [];
    const errors = [];

    for (let i = 0; i < accounts.length; i++) {
      const account = accounts[i];
      const accessToken = props.getProperty(`ig_token_${i}`);
      const normalizedAccountName = accountNameMap[i] || 'farm';

      if (!accessToken || !account.igUserId) {
        errors.push({ account: account.name || normalizedAccountName, error: 'Missing token or user ID' });
        continue;
      }

      try {
        // Determine correct base URL based on token type
        const baseUrl = accessToken.startsWith('IGAA') ? 'https://graph.instagram.com' : 'https://graph.facebook.com/v24.0';

        // Fetch recent media with captions, timestamps, and engagement
        const url = `${baseUrl}/${account.igUserId}/media?fields=id,caption,timestamp,media_type,like_count,comments_count,permalink&limit=${limit}&access_token=${accessToken}`;
        const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
        const data = JSON.parse(response.getContentText());

        if (data.error) {
          errors.push({
            account: account.name || normalizedAccountName,
            error: data.error.message
          });
          continue;
        }

        if (data.data && Array.isArray(data.data)) {
          data.data.forEach(post => {
            if (post.caption && post.caption.trim()) { // Only include posts with captions
              allPosts.push({
                id: post.id,
                caption: post.caption,
                timestamp: post.timestamp,
                mediaType: post.media_type,
                likes: post.like_count || 0,
                comments: post.comments_count || 0,
                permalink: post.permalink,
                account: normalizedAccountName, // Use normalized name for frontend compatibility
                accountDisplayName: account.name || normalizedAccountName,
                accountIndex: i
              });
            }
          });
        }
      } catch (apiError) {
        errors.push({ account: account.name || normalizedAccountName, error: apiError.toString() });
      }
    }

    // Sort by engagement (likes + comments) to prioritize high-performing content for voice learning
    allPosts.sort((a, b) => (b.likes + b.comments) - (a.likes + a.comments));

    return {
      success: true,
      posts: allPosts,
      totalPosts: allPosts.length,
      accountsFetched: accounts.length - errors.length,
      errors: errors.length > 0 ? errors : undefined,
      fetchedAt: new Date().toISOString()
    };
  } catch (error) {
    Logger.log('Error getting Instagram post history: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * Get Facebook Page stats including followers
 * Uses Facebook Graph API
 */
function getFacebookPageStats() {
  try {
    const props = PropertiesService.getScriptProperties();
    const accounts = JSON.parse(props.getProperty('instagram_accounts') || '[]');

    // Find account with Facebook page ID
    const accountWithFB = accounts.find(a => a.fbPageId);
    if (!accountWithFB) {
      return { success: false, error: 'No Facebook page configured' };
    }

    const tokenIndex = accounts.indexOf(accountWithFB);
    const accessToken = props.getProperty(`ig_token_${tokenIndex}`);

    if (!accessToken) {
      return { success: false, error: 'No access token for Facebook page' };
    }

    try {
      // Get page info including follower count (use v24.0 to match posting API)
      const url = `https://graph.facebook.com/v24.0/${accountWithFB.fbPageId}?fields=id,name,followers_count,fan_count,link&access_token=${accessToken}`;
      const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
      const data = JSON.parse(response.getContentText());

      if (data.error) {
        return {
          success: false,
          error: data.error.message,
          code: data.error.code
        };
      }

      return {
        success: true,
        pageId: data.id,
        name: data.name,
        followers: data.followers_count || data.fan_count || 0,
        link: data.link,
        fetchedAt: new Date().toISOString()
      };
    } catch (apiError) {
      return { success: false, error: apiError.toString() };
    }
  } catch (error) {
    Logger.log('Error getting Facebook page stats: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

/**
 * ═══════════════════════════════════════════════════════════════════════════
 * META ADS CAMPAIGN API - Marketing Command Center Integration
 * ═══════════════════════════════════════════════════════════════════════════
 */

/**
 * Get Meta/Facebook ad campaigns
 * Returns list of campaigns with status, budget, and spend
 *
 * Requires ScriptProperties:
 *   - meta_ad_account_id: Ad account ID (format: act_123456789)
 *   - meta_access_token: Long-lived token with ads_read permission
 */
function getMetaCampaigns(params) {
  try {
    const props = PropertiesService.getScriptProperties();
    const adAccountId = props.getProperty('meta_ad_account_id');
    const accessToken = props.getProperty('meta_access_token');

    // Check for credentials
    if (!adAccountId || !accessToken) {
      return {
        success: false,
        error: 'Meta Ads credentials not configured',
        needsSetup: true,
        missingFields: {
          adAccountId: !adAccountId,
          accessToken: !accessToken
        }
      };
    }

    // Build Meta Marketing API URL (v24.0)
    const fields = 'id,name,status,daily_budget,lifetime_budget,budget_remaining,objective,effective_status';
    const url = `https://graph.facebook.com/v24.0/${adAccountId}/campaigns?fields=${fields}&access_token=${accessToken}`;

    const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    const data = JSON.parse(response.getContentText());

    // Handle API errors
    if (data.error) {
      Logger.log('Meta Ads API error: ' + JSON.stringify(data.error));
      return {
        success: false,
        error: data.error.message || 'API request failed',
        code: data.error.code,
        type: data.error.type
      };
    }

    // Transform campaigns to consistent format
    const campaigns = (data.data || []).map(campaign => {
      // Budget is in cents, convert to dollars
      const dailyBudget = campaign.daily_budget ? parseFloat(campaign.daily_budget) / 100 : null;
      const lifetimeBudget = campaign.lifetime_budget ? parseFloat(campaign.lifetime_budget) / 100 : null;
      const budgetRemaining = campaign.budget_remaining ? parseFloat(campaign.budget_remaining) / 100 : null;

      // Calculate spent (lifetime budget - remaining)
      let spent = null;
      if (lifetimeBudget !== null && budgetRemaining !== null) {
        spent = lifetimeBudget - budgetRemaining;
      }

      return {
        id: campaign.id,
        name: campaign.name,
        status: campaign.effective_status || campaign.status,
        budget: lifetimeBudget || dailyBudget || 0,
        budgetType: lifetimeBudget ? 'lifetime' : 'daily',
        spent: spent,
        budgetRemaining: budgetRemaining,
        objective: campaign.objective
      };
    });

    return {
      success: true,
      campaigns: campaigns,
      count: campaigns.length,
      fetchedAt: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('Error in getMetaCampaigns: ' + error.toString());
    return {
      success: false,
      error: error.toString()
    };
  }
}

/**
 * Get Meta Ads campaign performance metrics
 * Returns aggregated performance data across all campaigns
 *
 * Optional params:
 *   - datePreset: 'today', 'yesterday', 'this_week', 'last_7d', 'last_30d', 'this_month' (default: 'last_30d')
 *   - campaignId: Specific campaign ID to get metrics for (optional)
 *
 * Requires ScriptProperties:
 *   - meta_ad_account_id: Ad account ID (format: act_123456789)
 *   - meta_access_token: Long-lived token with ads_read permission
 */
function getAdCampaignPerformance(params) {
  try {
    const props = PropertiesService.getScriptProperties();
    const adAccountId = props.getProperty('meta_ad_account_id');
    const accessToken = props.getProperty('meta_access_token');

    // Check for credentials
    if (!adAccountId || !accessToken) {
      return {
        success: false,
        error: 'Meta Ads credentials not configured',
        needsSetup: true,
        missingFields: {
          adAccountId: !adAccountId,
          accessToken: !accessToken
        }
      };
    }

    // Parse parameters
    params = params || {};
    const datePreset = params.datePreset || 'last_30d';
    const campaignId = params.campaignId || null;

    // Determine endpoint - either ad account level or specific campaign
    let endpoint;
    if (campaignId) {
      endpoint = `${campaignId}/insights`;
    } else {
      endpoint = `${adAccountId}/insights`;
    }

    // Fields for performance metrics
    const fields = [
      'spend',
      'impressions',
      'clicks',
      'ctr',
      'cpc',
      'cpm',
      'reach',
      'frequency',
      'actions',
      'cost_per_action_type',
      'purchase_roas'
    ].join(',');

    // Build URL
    const url = `https://graph.facebook.com/v24.0/${endpoint}?fields=${fields}&date_preset=${datePreset}&access_token=${accessToken}`;

    const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    const data = JSON.parse(response.getContentText());

    // Handle API errors
    if (data.error) {
      Logger.log('Meta Ads Insights API error: ' + JSON.stringify(data.error));
      return {
        success: false,
        error: data.error.message || 'API request failed',
        code: data.error.code,
        type: data.error.type
      };
    }

    // Extract insights (API returns array, we want first entry for aggregated data)
    const insights = data.data && data.data.length > 0 ? data.data[0] : {};

    // Parse spend (already in currency units from API)
    const totalSpend = parseFloat(insights.spend || 0);
    const impressions = parseInt(insights.impressions || 0);
    const clicks = parseInt(insights.clicks || 0);
    const reach = parseInt(insights.reach || 0);

    // CTR comes as percentage string (e.g., "1.8") or number
    const ctr = parseFloat(insights.ctr || 0);

    // CPC and CPM
    const cpc = parseFloat(insights.cpc || 0);
    const cpm = parseFloat(insights.cpm || 0);

    // Extract conversions from actions array
    let conversions = 0;
    let purchases = 0;
    let leads = 0;

    if (insights.actions && Array.isArray(insights.actions)) {
      for (const action of insights.actions) {
        if (action.action_type === 'purchase' || action.action_type === 'omni_purchase') {
          purchases += parseInt(action.value || 0);
          conversions += parseInt(action.value || 0);
        } else if (action.action_type === 'lead') {
          leads += parseInt(action.value || 0);
          conversions += parseInt(action.value || 0);
        } else if (action.action_type === 'complete_registration') {
          conversions += parseInt(action.value || 0);
        }
      }
    }

    // Calculate cost per conversion
    const costPerConversion = conversions > 0 ? totalSpend / conversions : 0;

    // Extract ROAS from purchase_roas array
    let roas = 0;
    if (insights.purchase_roas && Array.isArray(insights.purchase_roas)) {
      const roasEntry = insights.purchase_roas.find(r => r.action_type === 'omni_purchase' || r.action_type === 'purchase');
      if (roasEntry) {
        roas = parseFloat(roasEntry.value || 0);
      }
    }

    // Extract cost per action types for more detail
    let costPerPurchase = 0;
    let costPerLead = 0;

    if (insights.cost_per_action_type && Array.isArray(insights.cost_per_action_type)) {
      for (const cpa of insights.cost_per_action_type) {
        if (cpa.action_type === 'purchase' || cpa.action_type === 'omni_purchase') {
          costPerPurchase = parseFloat(cpa.value || 0);
        } else if (cpa.action_type === 'lead') {
          costPerLead = parseFloat(cpa.value || 0);
        }
      }
    }

    return {
      success: true,
      performance: {
        totalSpend: Math.round(totalSpend * 100) / 100,
        impressions: impressions,
        clicks: clicks,
        ctr: Math.round(ctr * 100) / 100,
        cpc: Math.round(cpc * 100) / 100,
        cpm: Math.round(cpm * 100) / 100,
        reach: reach,
        frequency: parseFloat(insights.frequency || 0),
        conversions: conversions,
        purchases: purchases,
        leads: leads,
        costPerConversion: Math.round(costPerConversion * 100) / 100,
        costPerPurchase: Math.round(costPerPurchase * 100) / 100,
        costPerLead: Math.round(costPerLead * 100) / 100,
        roas: Math.round(roas * 100) / 100
      },
      datePreset: datePreset,
      campaignId: campaignId,
      fetchedAt: new Date().toISOString()
    };

  } catch (error) {
    Logger.log('Error in getAdCampaignPerformance: ' + error.toString());
    return {
      success: false,
      error: error.toString()
    };
  }
}

/**
 * BULK ENDPOINT: Get all marketing dashboard data in a single call
 * This dramatically reduces load time by combining 15+ API calls into 1
 *
 * Returns: briefing, followers, scheduled posts, connections, farm pics summary
 */
function getMarketingDashboardBulk(params) {
  const startTime = new Date();
  const result = {
    success: true,
    loadedAt: startTime.toISOString()
  };

  try {
    // 1. Instagram follower counts (most important for stats row)
    try {
      result.instagram = getInstagramFollowerCounts();
    } catch (e) {
      result.instagram = { success: false, error: e.toString() };
    }

    // 2. Marketing queue (scheduled posts)
    try {
      const queueData = getMarketingQueue({ status: 'scheduled' });
      const posts = queueData.queue || queueData.posts || [];
      const now = new Date();
      const weekEnd = new Date(now);
      weekEnd.setDate(now.getDate() + 7);
      const thisWeekPosts = posts.filter(p => {
        const postDate = new Date(p.scheduledDate || p.date);
        return postDate >= now && postDate <= weekEnd;
      });
      result.scheduledPosts = {
        success: true,
        total: posts.length,
        thisWeek: thisWeekPosts.length,
        posts: thisWeekPosts.slice(0, 10) // Limit to 10 for preview
      };
    } catch (e) {
      result.scheduledPosts = { success: false, error: e.toString() };
    }

    // 3. Social connections status (quick check)
    try {
      result.connections = getSocialConnections({});
    } catch (e) {
      result.connections = { success: false, error: e.toString() };
    }

    // 4. Farm pics count (just count, not all data)
    try {
      const ss = SpreadsheetApp.openById('128O56X_FN9_U-s0ENHBBRyLpae_yvWHPYbBheVlR3Vc');
      const sheet = ss.getSheetByName('Farm_Pics');
      if (sheet) {
        const lastRow = sheet.getLastRow();
        result.farmPics = {
          success: true,
          count: Math.max(0, lastRow - 1) // Subtract header
        };
      } else {
        result.farmPics = { success: true, count: 0 };
      }
    } catch (e) {
      result.farmPics = { success: false, error: e.toString() };
    }

    // 5. Marketing tasks from unified system (for urgent/today counts)
    try {
      const taskData = getMarketingTasksFromUnified({});
      result.tasks = {
        success: true,
        urgent: (taskData.actionQueue?.urgent || []).length,
        today: (taskData.actionQueue?.today || []).length,
        total: taskData.stats?.total || 0
      };
    } catch (e) {
      result.tasks = { success: false, error: e.toString() };
    }

    // Calculate total load time
    const endTime = new Date();
    result.loadTimeMs = endTime.getTime() - startTime.getTime();

    return result;
  } catch (error) {
    Logger.log('Error in bulk dashboard load: ' + error.toString());
    return { success: false, error: error.toString() };
  }
}

